/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20081007-4","meetingId":"h20-c-settlement","date":"2008年10月7日","dateIso":"2008-10-07","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１９年度品川区一般会計歳入歳出決算","agenda":"平成１９年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"総務費、成果報告書の１０７ページの防災対策費を中心に質問させていただきたいと思います。中段に防災行政無線管理費という項目があります。その機械はともかくとして、今は結構お年を召された方でも携帯を持っていらっしゃる方が多いかと思うんですね。防災テルてるの使い勝手の工夫、今後の活用、そういうものをどうお考えなのか、教えてください。","respondent":"中山防災課長","answer":"私どもといたしましては、今現在、各町会長にアンケートをとるという形で、返還される場合には返還していただいて、そのかわりに自分の携帯電話をお使いになるですので、それに見合うような保証もしていかなければならないだろうということで、もうだいぶ。","voiceIndex":6,"id":"exchange-001"},{"speaker":"山内委員","kind":"質問・要望","question":"よろしくお願いをいたします。続きまして、１０８ページの集中豪雨等対策費についてお尋ねをさせていただきたいと思います。それからあと、品川区にそのようなゲリラ豪雨、そういう洪水が起こり得るような箇所というものは大体何箇所ありまして、例えば起きたときの緊急の心得とかその辺、近所に住んでいらっしゃる方の緊急避難の心得とかをどのように促しているかというのをお聞かせください。","respondent":"中山防災課長","answer":"緊急避難の心得ですけれども、これも同じように「わが家の防災ハンドブック」の２１ページに風水害対策のときの心構え、過去の被害を教訓にするだとか、日ごろから気象情報に注意しましょうというようなことで、注意を喚起しています。","voiceIndex":10,"id":"exchange-002"},{"speaker":"山内委員","kind":"質問・要望","question":"もちろん区民の方々にそういうことを周知するのは当然のことかと思うんですけれども、例えば品川区でお仕事をされている方、そういうような工事をされている方というものは、やはり今後、そういう方々にもちゃんとした注意というか、危険性というものをしっかりと促していくことが大事だと思うんですけれども、その辺は、例えば品川区の仕事を請け負った工事会社の方々にはどのような。","respondent":"家壽田下水道河川課長","answer":"下水道の事故につきましては、東京都が基本的には品川区も含めまして２３区の下水道を管理しておりまして、今回、この事故を踏まえまして、１滴の雨が降っても工事を中断するというようなことを決定しておりまして、当然下水道工事を受託それから実施される方は。","voiceIndex":12,"id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"わかりました。これは要望で終わらさせていただきたいと思います。それからあと、これはゲリラ豪雨が起きたときに比較的起こりやすい落雷なんですね。そのような被害が多いと。直接人に落ちるとかそういうこともありますけれども、改めてちょっとお伺いをさせていただきたいんですが、この夏、品川区に落雷の被害というのは何件ぐらいあったのか、もしわかればでいいんですけれども、教えてください。","respondent":"中山防災課長","answer":"私どもでは、落雷の件数については把握してございません。","voiceIndex":14,"id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"というと、だれが。これは消防庁がどこかなんでしょうか。ちょっとその辺はクリアにしてください。","respondent":"中山防災課長","answer":"落雷は、警報というのが出ないんです。落雷注意報と、注意報まででとまるという形なんです。ですから消防庁でも、どこに何件落ちたとか、もっとも被害が出れば、それは把握していると思いますけれども、通常落ちた件数を把握していることはないと思ってあります。","voiceIndex":16,"id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"今の課長のご答弁だと、品川区にはこの夏にそれだけ大きな被害はなかったということで、把握してよろしいんですか。","respondent":"中山防災課長","answer":"おっしゃるとおりです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"山内委員","kind":"質問・要望","question":"今後もやはり被害というものに対しては、なかなか把握をできかねるということなんでしょうね。そうしますと、対策としまして、避雷針というのが大きな大きな対策の１つではないかなと思うんですけれども、ちょっと教えていただきたいんですけれども、例えばどこかにビルを建てました。そこに避雷針を立てますといったときに、何か補助制度というんですか、そういうようなものはあるんですか。","respondent":"宍戸施設担当課長","answer":"避雷針につきましては建築基準法で設置することが義務づけられておりますが、補助制度というのはないというふうに承知しております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"山内委員","kind":"質問","question":"過日、高知県で、落雷事故があって重度の障害を負った青年が裁判所の判決で、家族に、これは回避できたというような裁判の判決が出ました。教育委員会の方にお伺いしたいんですけれども、いつ起こるかわからない、そういうような意味で、各学校やスポーツ団体にしっかりとした注意というものを、やはり起きてからでは遅いので、その辺をどのように啓発しているのか、最後に教えてください。","respondent":"河野指導課長","answer":"部活動等で落雷の危険性がある場合については、さまざまなメディアを使って情報を取得していますが、例えば急に天候が暗くなったとか、そういうような場合には運動を直ちに中止するということで指導しております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"最初に、地域防災無線デジタル化経費ですけれども、この地域防災無線のほかに、今、山内委員からもお話がありました防災テルてると防災伝言板が含まれていますけれども、それぞれ利用するのに幾らかかったのか、固定費、固定費というのは毎月の使用料と、従量制でかかるものがあれば、従量費も分けて教えていただければと思います。","respondent":"中山防災課長","answer":"それから機器の保守の点検委託等がございまして、これが１,９５８万１,８７１円等々となっています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"さて、この防災伝言板ですけれども、今、山内委員からもお話がありましたとおり、この文字情報を一斉に同報できるということで５年ほど前から利用されておりますけれども、災害に関する重要な情報なので、これはしっかりと継続していっていただきたいと思うんですが、本サービスを提供している通信事業者の現在の経営状況、事業継続性などについて。","respondent":"中山防災課長","answer":"防災伝言板につきましては、各町会長から非常に評価をいただいてありますので、なるべくならば継続したいと思ってありますけれども、状況をよく踏まえながら、継続か打ち切りかを決定してまいりたいと思ってあります。","voiceIndex":27,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"この情報システムに関しましては、ある程度できているという文書があるんですけれども、例えば８月に総務省からガイドラインが出ているというふうに聞いておりますけれども、このガイドラインの中身と、そしてまた平成２０年度震災復興マニュアルを作成するための予算が計上されていますけれども、このＢＣＰがこれに関係してくるのか、それとも関係しないのか、またＢＣＰの作成の全体像また計画について。","respondent":"原情報システム課長、伊勢危機管理室長、中山防災課長","answer":"品川区におきましても、この総務省で出しているガイドラインに従いまして、現行のものを点検しながら。新型インフルエンザの関係ですけれども、危機管理室では、いろいろなシチュエーションに合わせて危機管理を行わなければいけないのですが、特に。震災復興マニュアルの関係ですけれども、策定に向けまして、現在精力的に検討を重ねているところです。","voiceIndex":29,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも区民のサービスが継続できるという観点からも、このＢＣＰにつきましては、しっかりと検討を進めてつくっていっていただきたいと思います。イータックスの電子申告の特典で、カード枚数が急に増えたりして対応ができない自治体もあったわけですけれども、特に本区では、この住基カードに関しまして問題等、また課題等があれば、お伺いします。","respondent":"上川内戸籍住民課長、原情報システム課長","answer":"本区につきましても若干枚数がぎりぎりになってしまうようなことがあった事実はあります。そのような状況がございました。それで、今後また今年イータックスが継続されるわけですので、少し余分に購入をしています。そういった中で、いろいろな報道で、社会保障カードと住基カードを一緒にしたらどうかとか、いろいろな報道もありますので、そういった報道を受けながら。","voiceIndex":33,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"今、回答のありましたとおり、荒川区とかでもさまざまな、住基カードを活用するとか、いろいろな動きが出ております。この中で、国の動向等を含めまして、区に利便性のある、住民に利便性のある計画をどんどん立てていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"私は成果報告書１０７ページの新基本構想・長期基本計画策定経費に関連して、何点か伺いたいと思います。この内容が私は非常に不十分じゃないかなという感じがしているんですけれども、区のほうはどういうふうに考えているかなということなんですけれども、パブリックコメントが１１４件ということで、３４万区民ですから、１１４件は非常に少ないなというイメージです。","respondent":"福島長期計画担当課長","answer":"もっと集まるような仕組み、工夫はですけれども、今回も長期基本計画を策定するに当たりまして、パブリックコメントを１０月１１日に行う予定です。","voiceIndex":38,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"提案","question":"こんなもんだということは、私はちょっとこの姿勢を変えていただきたいと改めて思いました。２つ改善を提案したいんですけれども、１つはやはり周知の問題です。読売新聞ですと、大体世帯３割。そのほかで大体１０％いくかどうかで、今の新聞折り込みをやっても８割程度かなというふうに思うんですけれども、区のほうは、今のやり方でどのぐらいまで届いているというふうにお考えでしょうか。","respondent":"中川原広報広聴課長","answer":"届ける、補完する工夫は今後もしていきますが、あくまでも新聞折り込みを中心とした形でやっていきたいというふうに考えているところです。","voiceIndex":40,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"新聞折り込みを中心にということで、それ自体を否定しているわけではないんですけれども、今、工夫するということなんですけれども、私はちょっと今、伺っていて、どうかなと思ったのは、２割の人は何があっても読まないんだという、新聞折り込みでやっても８割いくんだ、この２割と２割がイコールではないというふうに私は思うんですよね。","respondent":"中川原広報広聴課長","answer":"今ホームページでも同じようにアップしますと、ホームページで閲覧する率が若い世代はとても上がってきておりますので、そういった意味で区から発信している情報がどういう形で届いているかというのを、広報としましてももう少し研究しまして。","voiceIndex":42,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それともう一つ、私はやはりやったほうがいいと思うのは説明会なんですよね。例えば介護保険、後期高齢者医療もそうでしたけれども、やはり説明会を開いて直接区民に説明する。その場で質問を受けて質疑応答をする。パブリックコメントの考え方はやはり区の重要な施策について、区民の理解をもらったり意見を聞くということですから、こういう手段も必要だと思うんですけれども、いかがでしょうか。","respondent":"福島長期計画担当課長","answer":"説明会ですけれども、今のところは説明会は考えてはいません。といいますのも、先ほど言いましたように、一番ＰＲとして効果があるのは広報紙を活用することだろうと思いましたので、広報紙の増刷といいますか、増ページで対応していきたいというふうに考えてあります。","voiceIndex":44,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"広報紙を工夫しますということですから、それはそれで大いにやっていただきたいと思います。要望を反映させるということを言っているわけですから。そうであれば、まさに長期計画のところで、具体的にどうしていくのかというのが盛り込まれなければおかしな話なんじゃないでしょうか。意見を聞こうとしないのではないかというふうに思えてしようがないんですけれども、そこら辺はどうでしょうか。","respondent":"福島長期計画担当課長","answer":"今、伝える、あるいは直接聞くことが大切だですけれども、例えば私ども、区政モニター集会等を通じまして内容を説明し、理解をしていただいた上で意見を聞く、そういったことも行っていきます。","voiceIndex":46,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういうところの要望が一番高いというところが、やはり結局私は重視されていないというふうに思います。議会でも４０人ですが。そのうち持ち家が４０％で借家が４０％と出ているわけですから、９０％の圧倒的多数の中に借家の方々、もしかしたら家賃等で出ていかなきゃいけない方々というのは非常に多いんですよね。だから、今回の長期計画をつくっている中で、こうした要望がなぜ反映されないのか。","respondent":"福田企画部長","answer":"本会議でも区長が申しましたけれども、区民の皆様にはいろいろな要望があります。それは我々の言葉で言えば、いろいろな政策分野における要望、これは本当に区民の皆様から見れば甲乙つけがたい要望だろうというふうに考えております。","voiceIndex":48,"id":"exchange-019"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"私からは成果報告書の１０２ページ、国際友好都市交流事業についてと、１１０ページ、外国人登録事務費について、時間があったら１０６ページのＣＡＴＶ視聴困難地域解消対策負担金についてお伺いさせていただきたいと思います。そこで、この質問に当たるにあたって、まず初めに区長にお伺いしたいと思います。よろしくお願いします。","respondent":"濱野区長","answer":"品川も同じ海に面したところでありますけれども、海岸線はほとんどが東京都の港湾局が管理をするところになっていて、区が直接何かをするということがなかなかできないということについて、いささか忸怩たるものがございました。","voiceIndex":51,"id":"exchange-020"},{"speaker":"石田（慎）委員","kind":"質問","question":"ぜひこれからも国際的ビジョンを持った品川区長でいてほしいと思います。そこで、まず予算が約１億円、この国際友好都市交流事業に費やされているんですが、この内訳が、どのようになっているのか。それと、この自主交流事業の支援なんですが、いままでどのようなものが実際にあったのか教えてください。その３点お願いします。","respondent":"伊勢総務課長","answer":"もちろん、新聞報道であった、そういう民間のものとは違って、この友好協会で実施している各事業については安心して派遣できる、こういうふうに自信を持っております。","voiceIndex":53,"id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"内訳は補助金が主だということで、その補助金の中身については、区としては把握されていないんでしょうか。それと、自主交流支援についてですが、民間レベルでの外国人の交流ということになっていますが、例えば品川区も多くの外資系企業等もあると思うので、その企業とかにお声かけとかというのはされているのでしょうか。","respondent":"伊勢総務課長","answer":"そういう面も含めまして、今、長期基本計画を策定中ですけれども、こういうものも検討しているというような状況です。","voiceIndex":55,"id":"exchange-022"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"なぜかというと、海外の人というのは、ものすごくボランティア精神豊かな人が非常に多い中で、そういった気持ちは他国に行ったときにもぜひ活用していただきたいなという思いで、ぜひよろしくお願いいたします。これは要望で終わります。窓口での対応は、基本的に日本語で行われていると思うんですが、どの程度の日本語と英語と中国語等を使っているのかを教えていただきたいと思います。","respondent":"中川原広報広聴課長、上川内戸籍住民課長","answer":"区内の外国人の方への外国語の情報提供ですが、ホームページに限って申し上げれば、ホームページの右上に４カ国語の表示がありまして、４カ国語でさまざま生活の細かい緊急事態から手続きまでをご案内しています。私のほうからは窓口の対応についてお答えいたします。","voiceIndex":57,"id":"exchange-023"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は、１０２ページの、１目一般管理費の中の新年名刺交換会経費、それから１０３ページの奨学金貸付事業についてお伺いをいたします。非常に素朴な疑問なんですけれども、まず、この総務費の中に、この１つ上に成人式経費というのはよくわかるんですが、当たり前のように見ていたんですが、この新年名刺交換会という、この会自体の経緯ですか、どのように、どういった経緯で行われていたのか。","respondent":"伊勢総務課長、本間副区長","answer":"新年名刺交換会ですけれども、これは新年を区の関係者が集ってことほぐというかお祝いをするという事業でございまして、経過のほうはちょっとあれなんですが、相当前からこの事業は行われております。経緯というご質問ですが、なかなか昔のことを知っている人間が少なくなりまして、私からお答えしますが、これは例の新生活運動ということで、そういう、区内でそれぞれのいろいろなところで。","voiceIndex":61,"id":"exchange-024"},{"speaker":"井桁委員","kind":"質問・要望","question":"古い古い歴史がある中で、あえてもう一度聞かせていただきたいと思うんですけれども、先ほど区政に携わっている方を呼んでと、またさらなる協力であったり横のつながりであったりとか、そういったことを深めていこうという会だということはよくわかったんですけれども、それでは、毎年、何人ぐらいの方に、この会に出席をいただくような案内を送っているのかということと、また出席率というのも。","respondent":"伊勢総務課長","answer":"ご出席をいただいた人数が８６２名で、出席率は４８.７％でございました。平成１８年度は出席率が５０％、平成１７年度は５１％、大体同じような数字で、招待者数もほぼ１,７００人台、こういうことになってあります。","voiceIndex":64,"id":"exchange-025"},{"speaker":"井桁委員","kind":"質問","question":"この出席率を見ると高いとは言えませんよね。そういった中で、区政に携わっている方というのもあるんでしょうけれども、このやはり招待をする方の選定というんですか、そういった招待をする方の考え方であったり、そういったものの改定というのも行っての、この率なのでしょうか。","respondent":"伊勢総務課長","answer":"新年名刺交換会の団体の毎年の見直しですけれども、基本的には全庁的に総務課のほうで、どういう団体を呼べばいいかということで、それぞれの所管に声をかけています。その中で若干の見直しが出てくるです。","voiceIndex":66,"id":"exchange-026"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひ今後、あり方等々、考え方というのもやはり明確に、そしてやはり長く続いているから慣性的になってこのままというよりは、やはり新たな形で、新たな考え方で、この交換会というのをぜひ交流を深めるという意味でももう一度考えていただきたいなと考えています。次に１０３ページの奨学金貸付事業なんですけれども、この事業の近年の受給者の推移というのをまずお聞かせください。","respondent":"小野区民課長","answer":"奨学金の受給者の推移です。平成１６年度に高校に入学された方で、品川区の奨学金を受けた方が９２名です。平成１７年度が６６名、平成１８年度が７０名、平成１９年度が６１名、平成２０年度で入学された方で受けた方が４６名という形になっております。","voiceIndex":68,"id":"exchange-027"},{"speaker":"井桁委員","kind":"質問・要望","question":"数にやはりむらがあるといいますか、特に平成２０年度は随分低くなっておりますが、そういった形で、この人数の変化ということと、これを品川区のほうではどう考えていらっしゃるのかということと、この事業というのは貸し付けということで、やはり借りているとなると、返却ということになると思うんですけれども、その返却率を教えていただきたいと考えています。","respondent":"小野区民課長","answer":"返還率というところですけれども、これはいわゆる現年の、これは１５年の均等で年１回返還という形なんですけれども、そのときに現年として払わなければいけない方と、それから支払いが滞って滞納というふうな形の方、こういうものも含めてですけれども。","voiceIndex":70,"id":"exchange-028"},{"speaker":"井桁委員","kind":"質問","question":"奨学金の制度自体でも返還の率が少ないというのもやはり問題となっておりますので、ぜひこのあたりについて、ご努力されている部分と、あと、お聞きしたのが一括返還もできたりとか、やはりいろいろな返し方の方法というのがあると思うんですけれども、品川区のほうとしては一括返還以外にも柔軟な対応というのをどうお考えでしょうか。","respondent":"小野区民課長","answer":"こちらについては、平成１６年度からずっと毎年毎年それによります実績が上がっておりまして、昨年度が１,７００万円強のシルバー人材センターの委託による収納があったんですが、今年度につきましては、今の時点で４８６万円ございまして。","voiceIndex":72,"id":"exchange-029"},{"speaker":"井桁委員","kind":"質問・要望","question":"返還に向けて柔軟な対応をしていただいているということなんですけれども、やはりそういったシルバー人材を使った催促であったりということもありだとは思うんですけれども、やはり年１回の支払いであったりとか、それと制度自体も柔軟に見ていただきたいということと、額についても一定の額を返したくても返せないということもあるとは思うので、ぜひともそういった額であったり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-030"},{"speaker":"金野委員","kind":"質問","question":"私のほうからは１０２ページの私立幼稚園預かり保育事業「きんだぁくらぶ」と、１０８ページの民間施設借上、１０３ページの奨学金貸付事業、その３点をお伺いいたします。実施に当たっては、してくださっている園、対象となる園、実施できる園の規定というのはあるのでしょうか。","respondent":"小林保育課長","answer":"区から「きんだぁくらぶ」の実施園に対する助成については、一定の水準以上の実施を行っている８園についてのみ助成金を交付していますが、それ以外の園につきましても、実施の時間数等が少ないために助成対象にはなっていないけれども。","voiceIndex":76,"id":"exchange-031"},{"speaker":"金野委員","kind":"質問","question":"そうすると、ある一定の基準で実施園をつくっているのではなくて、幼稚園側がこのようにしますよということで、それに対して助成がされているということですが、その時間数、ある一定の時間数というのは大体、それは月数で数えているのでしょうか。年間で日数を数えているのでしょうか。教えてください。","respondent":"小林保育課長","answer":"助成金の交付の対象となる水準につきましては、１点目は実施時間が朝７時半から午後６時半までご希望があれば預かること。そして２つ目には、夏季の休暇中も実施することが前提となっています。","voiceIndex":78,"id":"exchange-032"},{"speaker":"金野委員","kind":"質問","question":"わかりました。それから冬休み、春休みもやってくださっている園もあるかと思いますが、そういったところも含めて、そういうところに助成をされているというのが２０園の中で８園あるということですね。そうすると、決算書の数字から見ますと、今年度のは予算額から比較すると約４０２万円余ですか、決算額が増えているんですが、その予算額と比べての差異、この内容を教えてください。","respondent":"小林保育課長","answer":"それで、区の補助金はこの都の補助額を前提として、その実績に応じて選定しておりますので、利用率が上がりますと東京都の補助も上がり、それにつれて、品川区の助成額も上がったために、利用者の増に対応して補助額が増加しています。","voiceIndex":80,"id":"exchange-033"},{"speaker":"金野委員","kind":"質問・要望","question":"ということは保護者の方も、これを利用する方が非常に増えているというふうにも見えるのかなというふうに思うんですけれども、そうすると、この先、やはり子育て支援策としてお母様方からこうした長く預かっていただける、私立幼稚園でもそういうように長く預かっていただけるというのが希望かというふうに思うんですが、前にも一度、私はこの要望をさせていただいたところですけれども。","respondent":"小林保育課長","answer":"今後も園児の実態に応じてきめ細やかな対応をしてくださるようにお願いをしつつ、その結果、利用の拡大があれば、ぜひこれを推進してまいりたいと考えております。","voiceIndex":82,"id":"exchange-034"},{"speaker":"金野委員","kind":"質問","question":"私立幼稚園では２歳児クラスの受け入れというのがかなり増えてきているかと思うんですが、こうしたことも、子育て支援策の１つとして、園独自で多分されているんだというふうに思うんですけれども、また文部科学省のほうでも、これを推奨するまではいかないんでしょうが、２歳児を受けるに当たっての留意点みたいなものも出されている中で、こうした私立幼稚園での２歳児保育の受け入れは。","respondent":"小林保育課長","answer":"いずれにいたしましても、在宅での子育てを支援するという機能を持ってありますので、この取り組みにつきましては、私立幼稚園それぞれの状況等を幼稚園の方々、協会とも状況を確認しつつ、対応してまいりたいと考えております。","voiceIndex":84,"id":"exchange-035"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。私たち公明党としましても、この幼児教育に関しては無料化を訴えております。続きまして、先ほども質問が出ておりましたけれども、奨学金の件に関してお伺いいたします。１０３ページ、奨学金貸付事業ですけれども、先ほど利用者の推移は伺いました。内訳ですね、公立、私立、また入学準備等々、そういった内訳を教えてください。","respondent":"小野区民課長","answer":"内訳は、こちらの今お話ししました人数が年度の最終の受給人数という形になりますので、それより数名下がるというふうにお考えいただければよろしいかと思います。","voiceIndex":86,"id":"exchange-036"},{"speaker":"金野委員","kind":"質問","question":"この入学準備金ですが、申し込みをされる時期というのは、準備金ですので入学をしてからでは遅いので、いつ入学の申請ができるのか。それから、その申請の時期が終わった後でも、年度末までの間に、やはり経済的な理由でそれを申請したい、そういったのは受け付けていただけるのか、教えてください。","respondent":"小野区民課長","answer":"現在、大体９月１日から１０月３１日までというのが翌年度の奨学金の受け付けの期間になりまして、これは公立の中学校を通じて全員の方にお知らせするんですけれども、実際に入学が決まった時点で書類等を出していただきまして。","voiceIndex":88,"id":"exchange-037"},{"speaker":"金野委員","kind":"質問","question":"この奨学金のお知らせなんですけれども、どのようにされていますでしょうか。一部、私はホームページでも見させていただいたんですが、とてもすっきりとされていて、もう少し細かく制度の中身が書かれていてもいいのかなと、そんな気もしたんですが、いかがでしょうか。","respondent":"小野区民課長","answer":"もちろん、私立中学に行っている方も区民であれば対象になりますので、この方たちについては、広報あるいはホームページという形のお知らせになりますけれども、紙面の関係がありますので、そちらのほうについては。","voiceIndex":90,"id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"私は１０１ページの総務管理費、一般管理費の中で、電子計算組織運営費および基幹事務管理システム運営費の部分で伺っていきたいと思います。教えていただけますでしょうか。","respondent":"原情報システム課長","answer":"基幹事務管理システム、こちらのほうは、例えば財務会計でありますとか、それから１人１台にパソコンを配って勤怠、こういったものをまとめておりますこういった事業を取りまとめて基幹事務管理システム、こういった形で計上させていただいているものです。","voiceIndex":94,"id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"今、その電子計算組織運営費の中で、ホストコンピュータの管理ということだったんですが、事務事業概要を見ていまして、そのホストコンピュータですけれども、平成１９年度から外注され、アウトソーシングする。決算になって、これが項目が上がってきたのがなぜなのかというようなところをひとつ教えていただけますでしょうか。","respondent":"原情報システム課長","answer":"平成１９年度、特に平成１９年度、２０年度を含めてですけれども、医療制度改正がございまして、後期高齢者医療の関係で国保のシステムが大きく変わり、あるいは介護、そういうふうな形でシステムが変わったということもございまして、なるべくその辺をわかりやすくということで。","voiceIndex":96,"id":"exchange-040"},{"speaker":"渡部委員","kind":"質問","question":"それで、この品川区の個人情報をすべて詰まったこのホストコンピュータというのが外にあるということで、例えばその辺のリスク回避的な考えは、例えばホストコンピュータは実は品川区のデータセンター１カ所ではなくて、いろいろな地域に何カ所か置いているとか、何か具体的なリスク回避策をとっていらっしゃるのか、とっていらっしゃるのであれば。","respondent":"原情報システム課長","answer":"ただ、ソフトとかデータについては、何かあったときにきちっとバックアップができるようにということで、また違う場所に委託をして、きちっと保管して、何かあった場合はそれを速やかに復旧できるような形で週１回そういったものは渡して、保管を依頼しています。","voiceIndex":98,"id":"exchange-041"},{"speaker":"渡部委員","kind":"質問・要望","question":"過誤納金ということなんですけれども、これは例えばどういう、多く取り過ぎちゃうのは、やはり人的なミスなのか、それとも、そもそも基本的に一番最初の税額を計算するときに何かミスがあって、あなたはこれだけ払うんですよというので払ってしまうのか、払う側は気づかないのかな、気づくわけもないなという気もするんですが、この辺の考え方というのを教えていただけますでしょうか。","respondent":"武内税務課長","answer":"それを毎月、区のほうで税務署と連携をとりながらやりますので、そういった意味で、税が変更になった場合については税をお返しするというような形になりますので、それが過納金というような形になります。","voiceIndex":100,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"成果報告書１０３ページの奨学金貸付事業について、幾つかお伺いしたいと思います。改めてこの奨学金事業の目的について、本会議では、経済的に困窮している方を援助、学生生活を送る上で支援とありましたが、改めて何を保証する事業なのかご説明いただきたいと思います。過去に何回か引き上げられておりますけれども、その基準は何を見ているのか、あわせてご説明いただけますか。","respondent":"小野区民課長","answer":"やはり都立高校の授業料あるいは入学金、こういったものに対応できる、そういうふうな額というものを１つ考えております。私立については、公立高校と私立高校の違いというのがありますので、一定の額を、公立高校よりも上回る額という形で設定をしています。","voiceIndex":103,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"私はもっと使いやすく、もっと充実していただきたいと思っています。昨年、高校受験を控えている中学３年生が私にこんなことを言っていたんです。うちは自営業で営業も生活も大変そうだから、妹や弟のために都立受験一本に絞るしかない。仕方がないと話していました。決して子どもには責任はない。学校の教育の環境づくり、社会や政治にこそ責任があると思うんですけれども、いかがでしょうか。","respondent":"小野区民課長","answer":"ただいまの生活が苦しいから進学をあきらめなきゃいけない状況、これは大変悲しい状況だと思いますけれども、その状況を解決するものが奨学金というふうなことではないのではないかなと、これはやはりもっと別な部分の施策。","voiceIndex":105,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"希望する学校や高校に通うための奨学金ではないと。一体何なのかと私は伺いたい。本会議で学校で必要な額をすべて奨学金で賄う考えはないと答弁がありましたけれども、ずばり一体何を賄う、保証する制度なのか、教えていただきたいと思います。","respondent":"小野区民課長","answer":"入学金については５,６５０円ですので、入学準備金は公立で７万円という金額を奨学金で出しておりますので、十分、入学には足りる金額であるというふうに考えております。","voiceIndex":107,"id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここの実態をぜひ直視していただきたいと思うんですよね。学費が上がり続けている中で家計の状況はどうかといいますと、働く貧困層の拡大、仕事といっても非正規雇用の拡大、いわゆるワーキングプアが１,０００万人を超えた、こういう状況をしっかり見るならば、私は奨学金の充実こそ必要だと考えています。今後の方向についてのお考えを教えていただきたいと思います。","respondent":"小野区民課長","answer":"年間の学費については９４万８,０００円というふうなアンケートによる調査結果が出ておりますけれども、これも私立の入学金、授業料に対しては３５.４％の対応という形になりますので、この辺も１００％ではないですけれども、公立ではなくて私立を選択される方については。","voiceIndex":109,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここにメスを入れなければいけないと思いますが、区としてできる事業をもっと広げるべきだと思っています。ここの負担を何とかしてほしい。貸付金額の引き上げ、対象を大学まで拡大、返済の要らない給付制度、こうした奨学金の充実を私は必要だと思うんですけれども、その子育てに一番お金がかかる、この高校、大学、ここをしっかり視野に入れるべきではないかと思うんですけれども、いかがでしょうか。","respondent":"小野区民課長","answer":"こういうさまざまな調査の中でも、いろいろな、就学にかかわるというふうな調査項目の中に入っている経費も相当広い部分が含まれておりまして、そういう点からいって、奨学金というふうなところで支援をしていくという部分については。","voiceIndex":111,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"先ほど来、国民生活金融公庫の調査がいろいろ紹介されていましたが、高校入学から大学卒業までかかる我が子の教育費、家計の年収のおよそ３４％。結局、生活が苦しい、所得が少ない家計ほど負担が重くなってきている。今後１０年の長期基本計画の中でもこうした教育費への負担感軽減、そこは一体どのように位置づけているのか、私はしっかり位置づけるべきだと思うんですけれども、いかがでしょうか。","respondent":"宮地区民生活事業部長","answer":"あくまでもコアの部分の学費について区がご支援申し上げる、そういったことで取り組んでいきたいというふうに考えております。","voiceIndex":113,"id":"exchange-048"},{"speaker":"中塚委員","kind":"意見","question":"今、親の話がありましたけれども、親の責任と言いますけれども、家計が厳しい子どもを教育の機会から排除してよいのか、それが問われていると思うんですよね、一番子育ての中でお金がかかる高校、大学のこの負担、そこを全く無視して長期計画が立てられるのかと。ぜひしっかり位置づけていただいて、子育て世代の経済的負担の軽減、それは取り組むべきだと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問・要望","question":"初めに１０２ページの職員研修費について伺います。そういった中で、具体的なことは些細なことだと思うんですね。いろいろな制度の中では、休日出勤であったり難しい面はあるんですが、外に出ることを性格的に好まれる方ばかりではないかとは思いますが、ぜひ研修の中、あるいは日常の業務において、うまく仕組みや仕掛けをつくっていただけるならと思うので、この辺のご見解を伺いたいと思います。","respondent":"榎本人事課長","answer":"それで、研修でやる部分と、あとはＯＪＴという職場の中でやる部分と取り入れてやっていくのが一番いいのかなと思うんですけれども、まず、研修については特に新人のとき、新任のうちに、入区して５年以内ぐらいには数多くの職場を見てもらおうという意味で。","voiceIndex":118,"id":"exchange-050"},{"speaker":"渡辺委員","kind":"質問","question":"ぜひそういう方向に、自分もその輪に入っていきたいなと思いますので、よろしくお願いします。続いて、文化振興事業団について伺いたいと思います。その中で、多くの区民が利用されて、区民サービス向上につながっているとまず考えられているか、この点を１つ伺いたいと思います。その状況などはどのように把握されているのか、２つ伺いたいと思います。","respondent":"小野区民課長","answer":"そういう点では、本来の設置目的であります文化の向上だとか、あるいはコミュニティの活性化というふうなところに十分役立っている施設だなというふうに考えております。","voiceIndex":120,"id":"exchange-051"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう中で、やはり区内で定着している、本当の意味で愛着や利用の趣旨から沿う形、そういった区内団体の方を、やはり今、見ますと、抽せんの段階も含めて優先枠というのがどうも見受けられなかったので、そういう時期かなと、これまではこれまででよかったかと思うんですが、そういった中でご検討の余地があるかどうか伺いたいと思います。","respondent":"小野区民課長","answer":"この辺のところは本当に重要な課題だというふうにとらえておりまして、今後きゅりあんを受託をしております文化振興事業団とも十分協議をしながら、解決の方法について検討してまいりたいと考えております。","voiceIndex":122,"id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"市町村交流、早川町との交流経費のところで伺いたいと思います。そこで伺いたいのが１つ目、交流負担金という中で、主な用途と内訳。ここ数年の、細かいことはいいんですが予算の推移、そしてあとはヘルシー美里とヴィラ雨畑の助成対象の利用者数、その中で、団体利用で地区委員会や町会でもご利用が多いということなので、あとは個人利用の割合などがありましたら伺いたいと思います。","respondent":"小野区民課長","answer":"早川町との交流経費の中の交流負担金の内訳ですけれども、こちらについては、事業実施に伴います負担金ということで、さまざまなツアーをやっておりますけれども、そのときに現地に行きまして、いろいろと指導をしていただいたり、体験の材料を整えたり。","voiceIndex":124,"id":"exchange-053"},{"speaker":"渡辺委員","kind":"提案","question":"そういった中で伺いたいのが、１つは要望と合わせて伺います。区民が行きたくなる整備が必要な時期ではないかと思っています。提案要望のもう１点、今、答弁をいただいたように、個人や小グループが行きたくなる旅行企画パッケージ等もこれからは必要になる。あるいは、今ありました研修やサークル、スポーツ活動などを主目的にした、団体が行きたくなる仕掛けが必要ではないかと要望と合わせて伺います。","respondent":"小野区民課長","answer":"やはり本来それぞれの市町村、区、そういうところの役割あるいは個人の利用のあり方、あるいは団体の利用のあり方、こういうところを踏まえまして、さまざまな負担のあり方、あるいは利用しやすいようなメニュー。","voiceIndex":126,"id":"exchange-054"},{"speaker":"藤原委員","kind":"質問","question":"１０２ページの訟務員関係費と、１０３ページの人事給与関係についてお伺いします。初めに、人事ということでお伺いしたいんですけれども、来年の５月から裁判員制度が始まると思うんですけれども、職員の方が指名されることもあると思うんですけれども、まず人事上の取り扱いというのはどのようにしていくのか、お伺いします。","respondent":"榎本人事課長","answer":"国家公務員のほうは公民権行使等という形での部分で行くという形になりますので、例えば公務員が選挙の投票へ行くときに仕事がぶつかった場合については、その一部時間を特別休暇として認めておりますので、そのような形で公民権。","voiceIndex":129,"id":"exchange-055"},{"speaker":"藤原委員","kind":"質問・要望","question":"裁判員に指名された人はだれでも同じだと思うんですけれども、その人の判断でいろいろな影響が出てくると思いますので、いわゆる区の職員としての仕事また裁判員としての仕事という形で、あまり職員が負担にならないようにご配慮していただきたいと思うんですけれども、そのことについてお伺いしたい。","respondent":"榎本人事課長、伊勢総務課長","answer":"職員の負担ですけれども、裁判員制度は日本国民全員に対して課せられる義務という形でのスタートで、職務でどうしても代替できない場合については免除されるという形ですけれども、公務員の場合についてもそれぞれの事情に応じた形で。ただ、法律的にいろいろと難しい問題がありましたら、訟務員の方に直接所管が相談するだとか、我々が一緒になって相談する等をやっているということがありますけれども、件数は特にとってございません。","voiceIndex":131,"id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"それは件数をとらないでいいんですか。それと、区が直接訴えられた場合は、公務上なので、区がいろいろな費用とかを出してくれると思うんですけれども、もちろん公務上、個人が訴えられるという場合もあると思うんですけれども、そういうときの補償というのはどうなるんでしょうか。やはり公費負担でその辺は補償してくれるんでしょうか。","respondent":"伊勢総務課長","answer":"訟務員の事件はあくまでも区が訴訟の当事者になるという場合の訟務員です。それから、個人が訴えられる場合は、それは個人の負担で弁護士を雇うという形になります。","voiceIndex":134,"id":"exchange-057"},{"speaker":"藤原委員","kind":"質問","question":"件数をとらないのはなぜですかという質問に答えられていないので、総務課として総務部として、その辺はちゃんと押さえておかないといけないんじゃないんですかというのがいただいていないのと、それと、補償はちゃんとしてくれているという形なんですけれども、理不尽な形で訴えられるというのがあると思うんですよ。","respondent":"伊勢総務課長","answer":"この辺はいろいろな場面で具体的に検討していかなくてはいけない、こういうふうに考えてあります。","voiceIndex":136,"id":"exchange-058"},{"speaker":"藤原委員","kind":"質問","question":"その辺はよろしくお願いします。ただ事務とか技術系は２３区の共同採用をして、区が面接という形ですから、事実上、まだ独自採用とは違うと思うんですけれども、やはり品川区に来たい、品川区で働きたいという方を区が独自でとっていくという方向というのは、私はいいと思うんですけれども、それはモチベーションのことも含めて。その辺については、人事課長としてはどういうふうにお考えでしょうか。","respondent":"榎本人事課長","answer":"そういった意味で、いろいろな試験の募集から事務量からを考えていった場合に、品川区独自でやったほうがいいのか、それともそういう２３区の利用できるものは共通の部分を基盤にして。","voiceIndex":138,"id":"exchange-059"},{"speaker":"藤原委員","kind":"質問","question":"本当にこの公務員試験は難しいんですけれども、そこで受かってこられた方が、品川区という形で面接を第１番でしてくるということは、事実上は、技術系、事務も品川区の独自採用に限りなく近いという思いでよろしいんでしょうか。","respondent":"榎本人事課長","answer":"そのとおりです。それで、例えば今年の品川区の面接ですね、特別区で受かった後の区の面接につきましては、品川区が第１希望で入ってきた方がほとんど面接をしたんですけれども、それでも要は採用数に限りがありますので、どうしてもその中から選ばざるを得ないという状況です。","voiceIndex":140,"id":"exchange-060"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは、１０４ページのふれあいサポート推進事業と、隣の１０５ページの行政サービスコーナー経費についてお伺いをさせていただきたいと思います。最初に、１０４ページに地域食事サービス経費が１,３００万円になっておりますが、平成１９年度の会計予算が約２,２００万円になっております。この約１,０００万円近い差というのはどういうことなのか、教えていただきたいと思います。","respondent":"中山地域活動課長","answer":"ふれあいサポート事業のうち、地域食事サービスの経費について見ますと、平成１８年度、前年度の決算は１,３２１万７,０００円で、今年度平成１９年度決算が記載の１,３３１万１,３６１円ですので、これについてはそんなに大きく変動はないです。","voiceIndex":143,"id":"exchange-061"},{"speaker":"山元委員","kind":"質問","question":"今、地域食事サービス経費の中に、掲示板とかというのは入っているということ、予定としては入れていたということなんでしょうか。","respondent":"中山地域活動課長","answer":"後段に申し上げた、新しい事業の部分については地域食事サービスとは別です。地域食事サービスというのは、いわゆる地域食事サービスに伴う材料費であるとか、ボランティアの報償費、それに伴う経費です。","voiceIndex":145,"id":"exchange-062"},{"speaker":"山元委員","kind":"質問","question":"ちょっとよく理解できない部分があるんですが、次に行きます。すみません。週２回、お昼と夕方に２回ボランティアの方々がお年寄りのお宅に温かい食事を届けていただいているわけなんですが、実際にその品川区全体でこのお弁当といいますか、利用なさっている方の人数、また、その方たちに対してお届けをしていただいているボランティアの方々の人数を教えていただけますでしょうか。","respondent":"中山地域活動課長","answer":"ボランティアの方は、登録者でいえば５３０人ほどいらっしゃいますので、その中から受給者に応じて交代でやっていただいている部分がありますけれども、基本的には大体受給者の方と固定されておりますので。","voiceIndex":147,"id":"exchange-063"},{"speaker":"山元委員","kind":"質問","question":"たまたま私の周りの方が、受けたいんだけれども、ボランティアの方がいらっしゃらないので届けていただけないんだというお話を聞きましたが、それは偽りだったということになりますでしょうか。","respondent":"中山地域活動課長","answer":"調整します。","voiceIndex":149,"id":"exchange-064"},{"speaker":"山元委員","kind":"質問・要望","question":"実は今、約５３０人ですか、ボランティアの方がいらっしゃるとおっしゃっていましたが、特にこのお昼、お年寄りに対して配っている方々というのは、どういう年代層といいますか、もしわかるのであれば教えていただきたいと思うんですけれども、いかがでしょうか。","respondent":"中山地域活動課長","answer":"ボランティアの細かい年齢の資料は今ちょっとございませんけれども、実はこの食事サービスを始めてからもう２０年近くなりまして、正直申し上げて非常にボランティア自身も年齢が高くなっているのは事実です。","voiceIndex":151,"id":"exchange-065"},{"speaker":"山元委員","kind":"質問","question":"昨今、子どもたちが少なくなって、またおじいちゃん、おばあちゃんというのはなかなか接触がないことを考えると、今おっしゃったようにどんどん年代が上がっているというお話ですが、もし小学生とか中学生が、上手におじいちゃん、おばあちゃんたちにお届けできるような何かそういう工夫というか、できないのかなと思うんですが、その辺はいかがですか。","respondent":"中山地域活動課長","answer":"いずれにしましても、幅広く地域の力をかりながら、ボランティアの力を伸ばしていく努力だけは続けてまいりたいと思います。","voiceIndex":153,"id":"exchange-066"},{"speaker":"山元委員","kind":"質問","question":"費用についてお伺いをしたいと思います。昼食代が２９０円、そして夕食が４００円というふうになっております。主婦の端くれの私としては、こんなに安くできたらいいななんて思いますが、実際、本当は２９０円であがるわけはないと思いますが、その分、区のほうで助成をしているかと思いますけれども、この２９０円、４００円に対して本当はお幾らぐらいなんでしょうか。","respondent":"中山地域活動課長","answer":"そういう面で言えば、これは学校給食を前提とした、いわゆる給食の材料費がベースになっておるところですけれども、実際の経費というのは、これに例えば人件費等々を掛けると、相当そういうものについてはまた別の経費がかかるようになってまいりますけれども。","voiceIndex":155,"id":"exchange-067"},{"speaker":"山元委員","kind":"質問","question":"このとき、実はこの申請といいますか、６５歳以上の調理とか外出が困難な方がこれを受けられるということなんですけれども、その際に、例えばのど越しが悪いのでご飯をやわらかくしてほしいとか、塩分控えめにしてほしいとか、そういう希望というのはかなえていただけるものなんでしょうか。","respondent":"中山地域活動課長","answer":"いわゆる学校給食の場合、特別にそれだけのメニューというのは現実的にはなかなか難しいんですけれども、実は現場のほうではこれは配食の曜日の際に、例えばなるべく和食的な、あるいは子どもも食べられる味つけの割合濃くないものを工夫するとか。","voiceIndex":157,"id":"exchange-068"},{"speaker":"山元委員","kind":"質問","question":"行政サービスコーナーについてちょっと質問します。今、大井町とまた武蔵小山にサービスコーナーがありますけれども、実際にこの平日と土日の利用される方々の人数を教えていただけますでしょうか。","respondent":"上川内戸籍住民課長","answer":"全体的な傾向としましては、日曜開庁が今始まりましたので、日曜日、大井町が前年比で約８７％、武蔵小山で９０％、土曜日が、大井町で前年比１０７％、武蔵小山９４％という程度です。","voiceIndex":159,"id":"exchange-069"},{"speaker":"本間委員","kind":"質問","question":"３点ほどにわたって、短い時間ですのでよろしくお願いします。１０６ページ、区民相談経費、１０７ページから１０８ページにかけて防災対策費に関連して、消火器維持管理についてお尋ねします。これは日常どのように管理されているのか、その内容について。定期的に年に何回とかいうふうに動きを把握されているのでしょうか。その動きを把握する主体はどこでしょうか。お尋ねします。","respondent":"中山防災課長","answer":"工事請負費のほうで、赤い格納箱ですけれども、これが時々車にぶつけられたり、いたずらされたりということで破損してしまいますので、それらの工事、それからもう一つは、消火器工事のあっせんをしていますけれども、その補助金が１,３００件支出しているものです。","voiceIndex":162,"id":"exchange-070"},{"speaker":"本間委員","kind":"質問","question":"この件につきましては、わかりました。業者に委託をして管理をしているですね。地域のほうでそれぞれの部分でやっているというものはないのでしょうか。その辺をちょっと、例えば今お話にありましたように外見が壊れていたり、ごみが入れられていたり、扉が破損したりというような部分がありますよね。その部分について、よろしく。","respondent":"中山防災課長","answer":"実は今申し上げましたのは業者による性能の点検です。そのほかに地区の防災協議会のほうにお願いをいたしまして、５,７００本すべて外観点検、要するに外から見て異常がないかどうかということで、すべての地区で点検をお願いしています。","voiceIndex":164,"id":"exchange-071"},{"speaker":"本間委員","kind":"質問","question":"消火器の定期的な点検をきちっとされていると、５,６５２本に及んでされているということをお聞きして安心しました。次に行きます。そしてあとは、その後の取捨選択する方向、話がそこに立ちどまらないで、その人が本当に迷っている場合に、どちらの方向をあなたが選択するかというところまでを含めてのサジェスチョンがあるのかどうなのかということでお尋ねしたいと思います。","respondent":"中川原広報広聴課長","answer":"私ども区民相談室で法律相談を実施しているところですが、大変多くのお申し込みがあります。今のお尋ねですけれども、さまざまな状況でご相談にお見えになる方がいます。","voiceIndex":166,"id":"exchange-072"},{"speaker":"本間委員","kind":"質問・要望","question":"実はその件に触れまして、最近やはり悩み、相談事が多い。間口も広くなってきているという中で、かつて社会保険労務士の部分があった経過があるんですけれども、最近なくなったというふうなことも聞いておりますが、どんどん間口を広げながら区民の悩みの相談に乗っていただけるような方法をとっていただきたいと思いますが、いかがでしょうか。","respondent":"中川原広報広聴課長","answer":"社会保険労務士相談のことにつきましても、その内容につきましては一般質問でもお答えしたとおりなんですが、それだけの相談として設定しますのは、今はちょっとニーズという面からも少なうありますので、一般区民相談の中で。","voiceIndex":168,"id":"exchange-073"},{"speaker":"本間委員","kind":"質問・要望","question":"間口を広げていただきたいということを希望します。次に時間がなくなりましたので、水と緑の市町村との交流事業なんですけれども、この件につきましては、予算がついて、着々と道が、道づくりが半ばまで行っているですが、もう少し予算をつけて、ひとつさらに私どもの夢の膨らむようなものにしていただきたいと思います。これは要望になってしまいました。時間がありませんのでよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-074"},{"speaker":"井上委員","kind":"質問","question":"その前に、全庁的なことなので総務かなと思ってお伺いするのですが、各事業部がつくっている事務事業概要についてなんですが、基本的に質問としては、統一したものを検討していくべきではないかということについてお伺いしていくんですが、その事務事業概要はどのような目的でどのような意図を持ってつくられているものなのか、まず教えてください。","respondent":"伊勢総務課長","answer":"事務事業概要につきましては各事業部で作成しておりまして、各事業部では、その事業部の事業がわかりやすい、福祉の分野だったり教育だったり、いろいろありますけれども、それぞれの事業部のわかりやすい、そういう形で、例えば総務部だとしたら。","voiceIndex":172,"id":"exchange-075"},{"speaker":"井上委員","kind":"確認","question":"確認をすると、総合実施計画に沿った事業計画書だというふうに思うんですが、その認識でよろしいでしょうか。","respondent":"日下部企画財政課長","answer":"総合実施計画につきましては、これは長期基本計画に基づいた形での中期的な計画ということでありますけれども、事務事業概要というのは、事業計画というよりも、それぞれが所管しております事業全般にわたりまして、これはいろいろな幅がありますけれども。","voiceIndex":174,"id":"exchange-076"},{"speaker":"井上委員","kind":"質問","question":"事業の全体像ということですけれども、毎回、新年度になりまして、その事業についての概要説明をというところで、その事業課がやっている事業について、その部分で予算も明記されているところがあったり、経年を追って事業を行っている推移、実績が書いてあったりとか、いろいろばらばらなんですけれども、そのときに、その区が今年力を入れている部分について明記されていたり。","respondent":"市岡総務部長","answer":"この事務事業概要は、委員のいろいろご期待はわかるのですが、特に委員会構成が新たになったときに、最初の議会の委員会説明に供しているのがまず第一の目的です。","voiceIndex":176,"id":"exchange-077"},{"speaker":"井上委員","kind":"質問","question":"中でも資料コーナーは、計画形成段階においての過程を示すものも資料として置いていただくようにもなりましたし、見やすく、明るく、レイアウトも変わったりということで、工夫をされてきていることは評価をしているんですけれども、そういった中で、区政資料コーナーの運営経費がどのくらいになっているかということと、資料コーナーでの公開する資料の基準は、どなたが把握をしているというか。","respondent":"中川原広報広聴課長","answer":"運営経費については、人件費を除きますと、資料を、書籍を買うお金です。利用者は年間１万５,０００人ぐらいです。","voiceIndex":178,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"今日伺って、いろいろな各事業部のチラシも行政資料なんかも置かれているけれども、なかなかそこにまで立ち寄る方がいらっしゃらないということですので、役所に行って何か用事を済ませたときに区政コーナーにちょっと寄れば品川区の動きがわかるとか、こんな新しいことをやっているんだなというような、魅力のある区政資料コーナーに変えていくことができないかというふうに思っているんですが。","respondent":"中川原広報広聴課長","answer":"場所につきましては、今、耐震工事もやっておりまして、これから組織改正もありましてレイアウト変更もありますので、その中で、また検討になろうかと思いますが、今回、イベントなんかがあるときに、先ほど長期計画担当の課長も言っていたんですが。","voiceIndex":180,"id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"次なんですけれども、品川区の防災対策を行う会議体で、その中の委員の女性の比率が何％あるのかお伺いします。先ほど、午前中にも復興マニュアルの策定を精力的に行っているところだというお話もありましたので、その中の女性の委員の比率も合わせてお答えください。","respondent":"中山防災課長","answer":"消防団運営委員会のほうは３名です。それから復興マニュアルにつきましては、そういう合議体で制作するのではなくて、うちの防災課内でたたき台を作成しまして、それで課内で検討していくというような進みぐあいになってあります。","voiceIndex":182,"id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"復興マニュアルのほうは課内でということだったんですけれども、そちらのほうでの女性の比率はいかがでしょうか。","respondent":"中山防災課長","answer":"復興マニュアルは、今、業者を選定して、制作に向けて鋭意検討していますけれども、これにつきましては、私防災課長と、防災安全担当課長と、それからうちの係長、課内で検討しているという段階です。私どもに女性職員は１名しかおりません。","voiceIndex":184,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問","question":"今伺ったところで、本当に防災会議の５９人中２人の女性というのは、副区長と区民生活事業部長だと思いますけれども、そういう状態であるということは、とても少ないとしか言いようがないので、本当に阪神・淡路大震災のときも、中越沖地震のときも、災害復興のそういった経過の中で、女性の２次被害があったということが今やっと公になってきています。","respondent":"中山防災課長","answer":"実は防災に関しましては、昭和４９年から防災区民組織、これは町会、自治会を軸にした組織をつくってあります。現在２００組織あります。","voiceIndex":186,"id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"次に行きます。ホームページの改善についてお伺いをいたします。そこで、それをホームページのほうにアップをしていただきたいというふうにまず要望したいんですけれども、他の区でもう既にそういう区もありますので、そのことについて１点だけ先に確認をさせていただきたいなと思います。","respondent":"市岡総務部長","answer":"こういうものについては、もう既にホームページで、各事業部のほうで登載しているものもあります。したがって、各要綱の性質等をよく考えながら、一定の検討を進めさせていただきたいというふうに考えております。","voiceIndex":188,"id":"exchange-083"},{"speaker":"井上委員","kind":"質問・要望","question":"ホームページのほうで、２００６年のときにホームページのシステム改修があって、変更、リニューアルしたと思うんですが、その後、今年の予算特別委員会では５００万円ほどで機能向上を図りたいということで答弁があったんですが、その中で、どのように見やすい、そして必要な情報がとりやすい、区民が求めるリニューアルというか機能向上が図られたのか、まず１点、そこをお聞かせください。","respondent":"中川原広報広聴課長","answer":"その移しかえがある一定以上終わりますと、今度は検索が非常にしやすくなるという、そういったことが今年の目標ということで今取り組んでいるところです。","voiceIndex":190,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問・要望","question":"私も視覚障害者の方とメールを交換しているんですけれども、イメージが全然わからなくてお話を聞いたところで、スクリーンリーダーという音声読み上げソフトを使って文字処理をしているということで、そのソフトはテキストファイルとワード、エクセルなんかでは対応するんですけれども、ＰＤＦになったらもうアウトだということで、そこのところでちょっと手間をかけてもらえれば、ＰＤＦでなくて。","respondent":"中川原広報広聴課長","answer":"先ほど一体性のお話をいたしました。一体的になりますと、文字拡大とか背景色の変更まではできるようになります。今言った音声対応なんですが、オルト記述というところまではやっておりまして、そこまでは音声でいきます。","voiceIndex":192,"id":"exchange-085"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうなるとテレビは大体家庭に２台だとすると３０万台からおよそ３２万、４０万台を切るぐらい切りかえが必要になるわけでして、その件について国から、これは総務省のことですけれども、国から地方自治体に切りかえに伴って、タイムスケジュール的に何かをしなさいという施策というか対策の指示はあったと思いますけれども、それを教えていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"それに基づきまして、私ども１０月２１日号の広報に地上デジタル放送に切りかえになりますということの周知を図っているところです。その他チラシ等も置いたり、これから総務省のほうの指示に基づきながら周知を図っていきたいと考えているところです。","voiceIndex":195,"id":"exchange-086"},{"speaker":"大沢委員","kind":"質問","question":"総務省から対策の指示が来たということですけれども、指示がありますけれども、当然これは購入をしなければいけなくなるわけでして、それに対して、やはりチューナーやいろいろな買いかえとかという対応、それはお金が伴うんですけれども、それについて、いろいろそれが簡単に取りかえることが可能な人、いろいろな世の中といいますか社会、いろいろな方が、単身の高齢者の方、また生活保護の世帯の方。","respondent":"久保田行財政改革担当課長","answer":"２３区におきましては、千代田区のほうでそういう支援をしていくということを載せておりますけれども、あと２２区につきまして、他の区につきましては、品川区も含めまして国の動向を注視しながら検討していくということで、今どういう状態。","voiceIndex":197,"id":"exchange-087"},{"speaker":"大沢委員","kind":"質問","question":"行政サービスコーナー、武蔵小山なんですけれども、質問に入る前に、行政サービスコーナー、ホームページを２つ見させていただきました。「月曜から金曜の午前８：００～午前８：３０」というのはオールナイトの記載になっているんですけれども、これは当然間違いだと思いますので直していただけるか、間違いでしょうか、それともどうなんでしょう。間違いだと思うんですけれども、間違いですよね。","respondent":"上川内戸籍住民課長","answer":"確認して、間違いであれば訂正します。","voiceIndex":201,"id":"exchange-088"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど土日の利用率を伺いました。武蔵小山等を聞きましたけれども、どうもこの武蔵小山行政サービスコーナーは、当初は本当に期待多く、私たちも期待をしたものですけれども、土日もそうなんですけれども、私は真ん前に居を構えておりますけれども、どうも利用率が少ないような、当初の行政側が意図していたところと現状、どのような認識の乖離があるのか教えていただきたいと思います。","respondent":"上川内戸籍住民課長","answer":"それで、少ないということなんですが、実は大井町のサービスコーナーも開設当初は本当に少なくて、平成５年から先になって、かなり多くの利用者が見込まれるようになってきています。","voiceIndex":203,"id":"exchange-089"},{"speaker":"大沢委員","kind":"質問・要望","question":"以上でこの質問は終わらせていただきます。次に、会計管理なんですけれども、大体５時１５分前後でしょうか、１日の各課の出納の締めの時間というのは５時なんでしょうか、何時になるのか、ちょっと教えていただきたいと思います。","respondent":"野田口会計管理者","answer":"支出命令とか一定の起案については午後３時までに持ってきていただくように、書類関係は。それから金庫については保管の関係上、５時１５分までに金庫室に入れるようにということでしております。","voiceIndex":205,"id":"exchange-090"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、金庫というお話、単語が出てまいりました。この金庫なんですけれども、会計管理室にどのような方法で各課から皆さんが持っていっていらっしゃるのか教えていただきたいんですけれども。","respondent":"野田口会計管理者","answer":"各所管の中で現金を取り扱うところ、そういった課について、それぞれの各課で手提げ金庫というものを持っております。我々の金庫室の中に各課の保管する手提げ金庫を入れる金庫がある。そこに入れていただくということになってあります。","voiceIndex":207,"id":"exchange-091"},{"speaker":"大沢委員","kind":"質問","question":"金庫室に入れるという作業ですけれども、たまたま見てしまったんですが、これもたまたまなんですけれども、役所の中を金庫をこういうふうな形で、庁内をこういう形で持っていく。これは私たち見る上に非常にこれはスマートではなくて、あまりよろしからぬ光景だと思うんですけれども、そこのところをどういうふうにお考えですか。","respondent":"野田口会計管理者","answer":"そういった意味では、私どももいろいろな各所管のほうに、そういった事例については周知し、そういうことのないように徹底してまいりたいと思います。","voiceIndex":209,"id":"exchange-092"},{"speaker":"大沢委員","kind":"質問・要望","question":"公金ということです。いずれにしても持っていらっしゃる方は、それは注意を払って持っていく、これはもう言うに及ばずですけれども、万が一の危機管理という点からも、やはりむき出しの金庫を持って庁内を、闊歩とまではいきませんけれども庁内を歩く、この光景だけはお気をつけいただきたいなと思います。それに関して、ご意見をもう一回いただければと思います。","respondent":"野田口会計管理者","answer":"委員のご指摘のとおりですので、十分その意を酌んで対応してまいりたいというふうに思います。","voiceIndex":211,"id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"意を酌んでいただいたので、これで質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-094"},{"speaker":"武内委員","kind":"質問・要望","question":"私は１０７ページの防災対策費で２点、１１０ページの戸籍事務費で１点お伺いします。平成２０年度予算では１１１台ついていますので、これについてどうなるか、これを教えていただきたいのと、それからここに防災対策費が出ていませんが、今年３月に災害初動対応マニュアル、これができました。","respondent":"中山防災課長、上川内戸籍住民課長","answer":"ということで、これからその代替機種について早急に検討しまして、平成２０年度内に１１１台設置していく予定です。それから、参集についてですが、部長以上全職員を対象に研修をしました。平成１９年度の戸籍の謄抄本等の交付は１３万６,１６６件でございまして、その中で本人請求が約６割、第三者請求が約４割、その４割のうちの公用が２３％、職務上が１６％です。","voiceIndex":215,"id":"exchange-095"},{"speaker":"武内委員","kind":"質問・要望","question":"平成１９年度に１５台ついていますけれども。この分のお金だって考えなくてはいけない。これは要望します。これも要望で結構です。私どものほうにもいろいろな関係者の方から非常に心配されている声を聞きまして、例えば品川区として、これは事態をどうこうできないんですが、ただ、なるべく事前にそれを食いとめるような策として、何かお考えかどうか教えてください。","respondent":"上川内戸籍住民課長","answer":"いずれにしましても、告知をした場合、ただ告知をしただけでは該当者はご心配になると思いますので、関係課と調整しながら、その後の該当者へのフォローも考えていかなければならないというふうに思っておりまして、今後検討してまいります。","voiceIndex":218,"id":"exchange-096"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひ検討していただいて、例えば葛飾区あたりは、そうした今の不正請求を行って、それが発覚した場合には公表しますよというのを、広報ですとかホームページですとかに載せているところもあるんですね。これはあまりしょっちゅう載せているのがいいかどうかは別なんですが、やはり、そうした事前に食いとめるようなものも考えていただきたいなと要望しますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-097"},{"speaker":"高橋委員","kind":"質問・要望","question":"１０７ページの防災対策費と１０９ページの地域センター等管理運営費、１０９ページのほうから先に質問します。地域センターの職員の方々は、日ごろから地域活動、お祭り等、地域の活動に大変ご協力いただいて、非常に感謝しております。ここで１３カ所で職員数１０８という形であるんですが、地域センターとそのほかについての職員の内訳をお教えいただきたいんですが。","respondent":"中山地域活動課長","answer":"１０８人とここに記載のありますのは１３カ所の地域センターの職員数です。そのほかというお尋ねは、いわゆる地域活動課の中の本庁職員を含めた人数というお尋ねでよろしゅうありますでしょうか。よろしいでしょうか。以上です。","voiceIndex":222,"id":"exchange-098"},{"speaker":"高橋委員","kind":"質問","question":"地域センターに１０８人の方が働かれているということでよろしいでしょうか。それで、地域センターは、今、地域の活動のこともお話ししたんですが、区の出先機関としてのさまざまな業務を行っていると思います。その概略を簡単にご説明ください。","respondent":"中山地域活動課長","answer":"地域センターの役割は大きく行政事務として住民基本台帳、戸籍収納等の窓口、行政事務をやっている部分と、地域の核としての地域事務ということで、例えば町会自治会連合会の事務局、地区委員会の事務局。","voiceIndex":224,"id":"exchange-099"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、地域センターに今１０８名の職員の方がいらっしゃるんですが、地域事務ではなく、窓口業務等の行政事務にかかわっている職員の方は何人いらっしゃるのでしょうか。","respondent":"中山地域活動課長","answer":"事務分掌の中に、それぞれ行政事務、地域事務を合わせて分掌しているのが通常ですので、地域事務の専属人員というふうな形での人数の出し方はしておりません。","voiceIndex":226,"id":"exchange-100"},{"speaker":"高橋委員","kind":"意見","question":"すると、地域センターの地域事務の充実、それと民間委託推進との観点から幾つかお尋ねしたいんですが、先ごろ、公共サービス改革法が、一昨年、競争の導入に関して成立いたしました。その解釈基準の中で、地域センターに関係する部分がどのようなものか、お示しいただければと思います。","respondent":"久保田行財政改革担当課長","answer":"公共サービス改革基本方針、平成１９年１２月に示されたものだと思いますけれども、そのうち地方自治体に関係いたします業務につきましては、窓口関連業務といたしまして、２４挙げられております。","voiceIndex":228,"id":"exchange-101"},{"speaker":"高橋委員","kind":"質問","question":"業務が拡大されたということですが、もう一つ、住民票などの申請のときに、受け付けと引き渡しというものだけだったのが、さらにそのほかの業務も含めて一連の業務として拡大されたと伺っているんですが、それもよろしいでしょうか。","respondent":"久保田行財政改革担当課長","answer":"２４事業のうち、幾つかの事業につきましては、それぞれ所管します省のほうから通知が、助言という形で各自治体のほうに来ております。","voiceIndex":230,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、今後、区としては、総務省等から通知のあったことを踏まえて、地域センターやあるいはサービスコーナー等の民間委託の方向性についてはどのようにお考えでしょうか。","respondent":"中山地域活動課長","answer":"さまざまこういう法の動き、あるいはどこまでが例えば民間活用が可能かというふうなことについては十分研究はしてまいりますけれども、それが即体制に影響させるかどうかということについては。","voiceIndex":232,"id":"exchange-103"},{"speaker":"高橋委員","kind":"質問・要望","question":"企業等とのかかわりで、先日、９月２５日の日経ですか、企業がいろいろな備えをしているのが３割であるという記事が載っていました。区内にもそういった大きな量販店がありますので、そういうことも含めて、どのような取り組みをされるつもりでしょうか、お聞きします。","respondent":"中山防災課長","answer":"ただ、なかなか容易に、本社機能を持った会社が３０社入っていたり、そこだけではなくて、ゲートシティとか等々も顔を出して協定を結んでいただけないかというようなお話をしている最中です。これは今後とも積極的に詰めてまいりたいと思ってあります。","voiceIndex":234,"id":"exchange-104"},{"speaker":"高橋委員","kind":"質問・要望","question":"もう一つ、ではボランティアの受け入れ体制についてお尋ねをして、ボランティア災害対応マニュアルを策定していくということですので、それを作成して、それに基づく訓練というか、そういったことが、ボランティアを受け入れて区内の震災の被害があったところに彼らを派遣するという、そういう訓練等も必要だと思うんですが、そのボランティア災害対応マニュアルの制作の進捗状況と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問・要望","question":"指定管理者制度とモニタリング評価についてお伺いしたいのですが、何ページかわからないので、あとでページ数があったら教えてください。質問ですけれども、平成１６年からこの制度が導入されていますが、指定先の数を知りたいので、福祉法人とか株式会社とか、もしできたら種類別に、わからなかったら全体でもいいんですが、ちょっと数を教えていただきたいのが１点目の質問です。","respondent":"久保田行財政改革担当課長","answer":"それぞれの施設におきまして、各指定管理の団体がそれぞれの施設の特性に応じた対応をしておりますし、また迅速な、実際に利用される方々と接する中でも、そういった苦情なども取り入れながら改善を図っているというふうに伺っておりますので。","voiceIndex":238,"id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全体で８３施設ということで、かなりここのところ広がっているなという受けとめ方をしています。１点目は公共サービスの水準の確保の観点が重要であること。２点目は専門的知見を有する外部有識者等の視点を導入することが重要であること。こんな見直しが求められているんですが、この観点に沿って、再度品川区のところを見直した時点で、いかがなんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"それと、先ほど８３ということで施設のお話をいたしましたけれども、その中には区営住宅、区民住宅の３４件というものも含まれますし、自転車等の駐車場というところ２０カ所、そういうものも含めまして８３ということで。","voiceIndex":240,"id":"exchange-107"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここが重要であると、このところをちょっと答えていただきたい。必要な体制、物的、人的、この事項をきちんと定めているのかというあたり、この辺をしっかりと見直して把握をしなければいけないというふうに書かれているんですが、この辺についても具体的にはなかったので、私としては、公共サービスの質の向上を求める場合においては、人の問題がとても重要であると思っています。","respondent":"久保田行財政改革担当課長","answer":"セルフモニタリングにつきましては、指定管理者の業者がやっているところですけれども、こちらは指定管理者の業者がアンケート箱などを設置しながら利用者の方の声を直接聞くといったことで、改善することがあれば。","voiceIndex":242,"id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"外部の有識者の視点というのは大事なので、前向きにぜひアドバイスを取り入れる等、入れていただきたいと思います。この辺もチェックをしていかないと私はいけないと思っています。モニタリングの評価で、総括シートが平成１８年、そして平成１９年出されているんですが、いろいろ意見が委員会でこの間出されていたと思うんです。この辺で、委員会の意見を受けて改善されたことがあったら教えてください。","respondent":"久保田行財政改革担当課長","answer":"平成１９年度の総括シートにつきましては、もう既に議会のほうに報告をさせていただいたといった形にはなっておりますけれども、来年度以降に向けて、議会からのいただいた意見を含めながら、その部分、よりよい総括シートになるように検討しています。","voiceIndex":246,"id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どのくらい再委託を把握をしていらっしゃるのか、そこも具体的に聞きたいのと、あと、労働条件のところがあまり答えられていなかったと思うので、その辺と、あと改善が検討されているというあたりは、一体どの辺なんでしょうか、お聞かせをいただきたい。時間が少しずつなくなってきているので、特にこの間、私たちが求めていたのは、具体的に３点言いたいと思います。これが１点目です。","respondent":"久保田行財政改革担当課長","answer":"その後、経営会議におきまして、総括シートの検証を行います。それをまた議会のほうに報告という形で、そういった仕組みの中で見直しのほうを検討しているといったところです。","voiceIndex":248,"id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、区のほうがアンケートをとる仕組みとか、指定管理者の中に設けられている第三者評価ではなくて、外部からしっかりと行う第三者評価システム、そういった客観性のあるものが必要であると考えていますが、いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"先ほどの指定管理業者の中で働く方の賃金や体制といったご質問にお答えをしますけれども、管理運営に関しまして、私ども、常日ごろより、もう繰り返しになりますけれども、コミュニケーションを図っていく中で、経営効率を重視するあまり。","voiceIndex":250,"id":"exchange-111"},{"speaker":"飯沼委員","kind":"意見","question":"今の答弁は不満なんですけれども、職員体制のことについて答弁がなかったので、そこが１つと、業者だけではなくて、区が全体の把握をする意味でも、区の独自のとらえ方が必要であると思いますけれども、職員体制のことを答えてください。","respondent":"久保田行財政改革担当課長","answer":"職員体制といったことですけれども、そういうものにつきましては、この指定管理者制度の中で、そういったものを区のほうが指導するといった制度ではございませんので、また別の観点が必要なのかなというふうに思っております。","voiceIndex":252,"id":"exchange-112"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、物価高等、単品スライドの運用については、積算と契約とのタイムラグなどの課題への対応ということで対応が決まりまして、それに直接単品スライドの適用ではないんですけれども、原小学校跡のこうほうえん、これは契約後の追加で補正予算が出されておりますが、その取り扱いというのは当然区の発注するものが単品スライドが適用で、これは民設民営ですから単品スライドの適用ではないと思うんですが。","respondent":"阿部経理課長、日下部企画財政課長","answer":"１点目の業者が変更したという事例ですけれども、今回のようなご質問のありました保養所につきましては、関係会社に事業譲渡されました。原小学校の関係につきましては私のほうからお答えをします。今、委員のご質問にもございました原小学校跡につきましては、民間の創意を生かすということで民設民営方式を採用しているわけです。","voiceIndex":255,"id":"exchange-113"},{"speaker":"本多委員","kind":"確認","question":"その取り扱いについてはわかりました。ほかにも何かそういう、例えば手法というか、事務的に分類があるか。特にないでしょうか、ちょっと確認だけお願いいたします。","respondent":"日下部企画財政課長","answer":"単品スライド、先ほど経理課長から説明がありましたけれども、基本的には区が発注するもので、しかもそういうタイムラグの関係でどうしても対応が必要なものというような、そういう性格があります。原小学校の場合は、やはりそういった点でちょっと性格が異なります。","voiceIndex":258,"id":"exchange-114"},{"speaker":"本多委員","kind":"質問・要望","question":"１０９ページのほうなんですけれども、日曜開庁が平成２０年１月６日から始まったということで、戸籍ですとか国保、児童手当など、幾つかの区分がありまして、３カ月での平成１９年度の実績は１８ページに載っておりますが、そうした、平日になかなか手続きができない方が日曜開庁を活用して、いいと思うんですけれども、地域センターでの実務について、もし変動というか。","respondent":"中山地域活動課長","answer":"日曜開庁で行っている事務と地域センターの事務とで重複しているもの、いわゆる住民基本台帳の異動関係および証明関係の発行事務の件数を１月から８月末までの数字で平成１９年度と平成２０年度をとってみましたところ、地域センターの受け付け。","voiceIndex":260,"id":"exchange-115"},{"speaker":"本多委員","kind":"質問","question":"そうすると、また次の週で探してくれないかというと、また全部Ａ施設、Ｂ施設、Ｃ施設、順番にやって非常に手間がかかったりしている状況もあるかと思うんですが、もしその辺の整合がとれれば、何か方策などがないかなと思うんですが、教えていただければと思います。","respondent":"中山地域活動課長","answer":"それで、こういういろいろな日曜開庁も含めて、処理件数等の動きはありますけれども、逆に言えば、その辺のきちんとした丁寧な対応というふうな部分も実際にしているということはありますので、この辺は数字とは別な。","voiceIndex":262,"id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"ページ数を示しながら、１０３ページの庁舎等維持管理では、今、庁舎の耐震化に伴いまして、前庭というんですか、噴水のあるところ、白線で仕切られまして自転車が置けるようになりまして、そこに至るまでスロープを登って自転車を、庭の中を通行するわけですが、ここの交通安全管理というんでしょうか、そこら辺が気になりましたので、要するに乗ってもいいのか、引っ張っていったほうがいいのか。","respondent":"阿部経理課長、高濱生活安全担当課長、中山防災課長","answer":"１点目のプラッツァの自転車の通行ですけれども、当然のことながら歩行者の安全確保が第一ですので。しかし、区民との作成検討会を重ねる中で、まず１つのものとしてつくり上げようとの意見が大勢を占めまして。災害時の要援護者の避難誘導ワークショップの内容と実施状況ですけれども、要介護者や高齢者等、災害時。","voiceIndex":270,"id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"要援護者につきましては、そうしますと、足の不自由な方の車いすということだけで、現状は障害のある方へのこういう防災訓練というんでしょうかワークショップ、これはされていないというふうに理解をいたしましたので、ぜひともこれは、こういう観点で、障害のある方もない方も地域に住まわれているというところで、これから取り組んでいただきたいという要望をしておきたいと思うんです。","respondent":"阿部経理課長、高濱生活安全担当課長、中山防災課長","answer":"したがいまして、このつくり上げ方自体が地域安全マップのつくり方でつくっておりますので、これが成果物だというふうに認識しております。それで、ワークショップについても工夫した活用をして、今後進めてまいりたいと思います。","voiceIndex":274,"id":"exchange-118"},{"speaker":"阿部委員","kind":"質問","question":"私からは１０１ページになるでしょうか、庁舎の光熱費あるいは通信費等々についてお伺いしたい。それから、１０２ページの国際友好都市への派遣、それから、１０３ページの都市交流、そして同じく１０３ページの奨学金あたりまでをまず伺いたいと思います。庁舎の光熱費あるいは通信費なんですけれども、この歳出の中ではどこに入っているのかということと、それぞれの額をお伺いしたいと思います。","respondent":"阿部経理課長、伊勢総務課長、小野区民課長","answer":"金額的には光熱水費で申しますと本庁舎、第二庁舎、防災センターを含めまして１億１,８００万円余、通信費につきましては。もともと、この交流事業につきましては、それぞれ姉妹都市提携書あるいは協定書あるいはジュネーブですと友好憲章を設けまして。山北町と早川町の交流の経費が非常に類似しているというご指摘ですけれども、平成１９年度は確かに非常に似ておりますけれども。","voiceIndex":279,"id":"exchange-119"},{"speaker":"阿部委員","kind":"質問・要望","question":"通信費なんですけれども、これについてお伺いしましたのは、つい先日ですけれども、防衛省の通信費の関係のニュースがございまして、それで防衛省も１つの組織の中で、幾つか通信費を別々にＮＴＴと契約していたために、大口割引の受け方が少なかったということが会計検査院から指摘をされております。これについてもちょっとお考えを聞かせてください。以上、お願いします。","respondent":"阿部経理課長、伊勢総務課長、小野区民課長","answer":"引き続き経費の縮減には努めてまいりたいというふうに思っております。ふれあい掲示板にも載せたというようなことで、協会のほうもこういう形で努力しておりますので、いろいろな周知の方法を今後研究。奨学金の在学生の中途の申請について、経済的理由による退学が非常に増えているのに、少しまだ申請が少ないのではないかということですけれども、今後。","voiceIndex":283,"id":"exchange-120"},{"speaker":"阿部委員","kind":"質問","question":"１０７ページの消防団なんですけれども、品川区の都市化に伴ってなんでしょうか、練習場所がなかなか確保できないというお声をよくいただいております。そういった練習場所などについて、区全体で調整したり相談したりということもしていただければと思うんですが、それは可能でしょうか。","respondent":"斉藤防災安全担当課長","answer":"基本的には消防団の訓練場所、それぞれの場所につきましては、各消防団のほうで対応をお願いしています。","voiceIndex":287,"id":"exchange-121"},{"speaker":"阿部委員","kind":"意見","question":"基本的にそのようなこと、運営になっているので、練習場所が確保できなくて困っている。ですので、今、車で動いても構わないという声もありますので、ちょっと地域から離れていても、もう少し広い範囲でここなら気持ちよく思い切ってホースを伸ばせるぞというようなところをぜひ行政としても少しお考えいただければと思いますが、もう一度ご答弁いただけますか。","respondent":"宮地区民生活事業部長","answer":"いろいろなご要望、悩みの種等々おありになるかと思いますので、ちょっと現状でどんな課題、問題点、悩みがあるか、私のほうでもじっくり聞いてみたいと思います。それからの対応ということになろうかと思います。","voiceIndex":289,"id":"exchange-122"},{"speaker":"阿部委員","kind":"確認","question":"これは内容の多様化については私は慎重な立場ではあるんですけれども、少なくともとりたいと申請を考えていらっしゃる方の利便性、それとセキュリティの問題を考えますと、今、役所に２回来るということではなくて、１回目は地域センターで申請を出して、本人確認の後、受け取りはここの大井町の本庁舎でというような方式もあり得るのではないかと思いますが、いかがでしょうか。","respondent":"上川内戸籍住民課長","answer":"委員おっしゃるとおり、２回ご足労を今願っているわけですが、いままでは本人が２回申請のときにもいらしていただいていたんですが、今は代理人で最初の申請は来ていただいて、本交付のときにパスワード等を入れますので、２回来ていただくように変更したところです。","voiceIndex":291,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"１０２ページの「きんだぁくらぶ」、午前中ありましたが、気になるご答弁がありましたので確認をします。１０４ページの近隣セキュリティシステム運営経費の件と、それから１０６ページのボランティア・ＮＰＯ法人等との協働のしくみづくり、それと民間活力の推進経費というのがありますのでお聞きします。要件が変わってきます。それについてのご見解をまずお聞きしたいと思います。","respondent":"小林保育課長","answer":"２歳児の取り組みについては、基本的には今、区としてこういう対応をお願いしたいというところまで取りまとまった考え方は持っておりません。今後、園の状況に応じて、その実態を把握し、その必要性も含めて構成する協会の各園の皆様のご意見をお尋ねしていきたいと思います。","voiceIndex":294,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問・要望","question":"２歳児については、いろいろ兄弟関係でという事情はあるかと思いますので、それはそれで状況に合わせていっていただきたいですが、預かり保育に本当に慎重にしていただきたいなというふうに要望をしていきたいと思います。ですから、そういうことであってはいけないので、これを何かしら使いやすい方向として、そういう実態があるということをまず知っているかどうかというのをお聞きしたいと思います。","respondent":"高濱生活安全担当課長","answer":"それについては、再三いろいろな場で伝えております。引っ張った場合、必ずうちのほうのオペレーターが対応しますが、その際にもどんな理由で引っ張ったにしても、きちんと優しく、それに対しても、自分が引け目を負うようなことのないように応対をしています。","voiceIndex":296,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"これは１年生だけではなくて、現に持っている子どもたちもわからないんですよ。ですから例えば９月１日の引き取り訓練がありますね。協力者。でも親同士も親の顔が見えなくなってきてわからなくなっている。祭りなんかがあったときに、そういう人たちと話が、そういう地域の方たちが触れ合うとか、ちょっと意識した形でやっていただきたいなと思いますが、いかがでしょうか。","respondent":"市川教育次長","answer":"１点目の取り扱いの説明なり訓練、ご提案の趣旨も含めてこれから取り組んでまいりたいと思います。２点目につきましては、ご指摘されたようなことも含めて、このまもるっちという有効なツールをいかに地域の中で子どもを守るものとして用いていくか。","voiceIndex":298,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ有効的に、実際に使えるようによろしくお願いいたします。それがないと、結局、地域の中で自分たちが考えているから自分たちのものでいいんだよね、みたいな形になってしまうので、そうではなくて、やはり全部の区民、品川区の区民という意識づけというのをきっちりした形で協働ということを考えていただきたいなというふうに思っておりますが、その考え方についてお伺いします。","respondent":"久保田行財政改革担当課長","answer":"民間委託につきましても、そういった意味では民間活力を活用しながら進めていきたいというふうに考えております。","voiceIndex":300,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"嫌な言葉ですけれども、丸投げにはしないでほしいということです。やはり品川区の政策は品川区がしっかりと見据えて、その上で民間の方たちと協働をとっていく、いろいろな方たちと協働をとっていくということをぜひ進めていただきたいというふうに思っております。その責任の所在ということもしっかりと認識をしていただいて、全庁的にやっていただきたいと思いますが、もう一度ご答弁をお願いします。","respondent":"久保田行財政改革担当課長","answer":"事業の実施主体は区ですので、協働という手法を使いながら、区の施策、事業がきちんとうまく回るように、責任を持って取り組んでいきたいというふうに考えております。","voiceIndex":302,"id":"exchange-128"},{"speaker":"須貝委員","kind":"確認","question":"私は、１０６ページ、会計管理費、１０７ページ、防災対策費、そして、１１０ページの選挙管理委員報酬についてお聞きします。品川区はそういうことはないと思うんですが、その点について回答だけ、大丈夫ですということでお聞かせ願えれば、確認の意味でお聞きします。そして工場も復興できなくなる。一人当たり年間幾ら報酬が出ているのか、ただ単に４で割ればいいのか、その辺についてお聞かせください。","respondent":"野田口会計管理者、中山防災課長、早津選挙管理委員会事務局長","answer":"そういった意味では、品川区における公金管理につきましては、今のところ金融不安がいろいろありますけれども、安全に対応しているです。復興マニュアルの件ですけれども、先ほどご説明申し上げましたように、今、鋭意検討中です。委員が２３万８,０００円ということで、それぞれの合計額が１,２００万円です。","voiceIndex":305,"id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうすると、金額的に常勤としてこういうふうに維持する、役職として置いておくのはどうなのかなと。逆に選挙というのはそのたび、そのたびにあるわけですから、その前後に採用していくような方式でいいのではないかなと。要は臨時ということでいいのではないかなということを、ちょっともう一度確認させてください。何かそれに対しては、私は今後きちっと早急に対策をとっていただきたいと思います。","respondent":"早津選挙管理委員会事務局長、中山防災課長","answer":"選挙管理委員の仕事は選挙事務を適正かつ公正に実施していくということでございまして、そのために、平常時から例えば選挙人名簿の管理、そのほかの事務があるほかに、いざというときの選挙事務が適正かつ公正に行われるための。先ほど申し上げましたように、もう業者も選定しています。したがいまして、防災復興マニュアルにつきましては今年度内に作成を見るです。","voiceIndex":309,"id":"exchange-130"},{"speaker":"山路委員","kind":"質問・要望","question":"３点目が１０４ページ、生活安全推進事業の振り込め詐欺対策についてお伺いいたします。順不同ですが、まず最初に奨学金貸付事業の入学準備金について、午前中、我が党の金野委員から質問いたしましたが、その中の答弁で、入学する前年の９月から１０月までに申し込んで、入学に間に合う準備ができますよということでございました。これでよろしいのですか。ちょっと確認をさせていただきたいと思います。","respondent":"小野区民課長","answer":"今、委員のおっしゃったとおりです。","voiceIndex":313,"id":"exchange-131"},{"speaker":"山路委員","kind":"質問・要望","question":"この奨学金貸付事業は長年にわたって拡充につぐ拡充をしていただきまして、不幸にして親が倒産した、あるいはリストラに遭ったというときに、受験生自身の努力で進学ができるという、非常に夢のある大切な事業だと私はいままで思っていろいろ要望もしてまいりました。その中で、１つ、区民の方からご要望をいただいている課題は、特に景気がよくないときは、１月から３月までに倒産する可能性が高いんですね。","respondent":"小野区民課長","answer":"そういう場合に、できるだけ迅速に審査等をいたしまして、利用者のご要望に、必要にこたえられるように進めてまいりたいと考えております。","voiceIndex":315,"id":"exchange-132"},{"speaker":"山路委員","kind":"提案","question":"力強いご答弁をありがとうございました。次に行きます。昨年の第２回定例会におきまして、私も振り込め詐欺の防止する方法について、発信者情報通知サービスを利用する方法を提案し、また理事者からのご答弁で、今後の啓発の中で趣旨を生かすよう検討してまいりますとの回答をいただきました。具体的にどのように検討され、どのように推進していらっしゃるかお伺いいたします。","respondent":"高濱生活安全担当課長","answer":"委員がおっしゃっていただきました発信者に対する対策ということで、昨年、振り込め詐欺はすべて電話が入り口なので、その電話に対して何らかの対策をすべきではないかというご意見をいただきまして、それに対する検討をさせてくださいというご答弁を差し上げました。","voiceIndex":317,"id":"exchange-133"},{"speaker":"山路委員","kind":"質問","question":"これは早急に対策を進めなければいけないんですが、ケーブルテレビの電話設置のときに、設置費用が安く済む方法がありますよね。それを区でサービスしていただいて、取りつけていただければ防止できるという具体的な例を紹介したんですけれども、その辺についてはどこまで研究されたか、お伺いいたします。","respondent":"高濱生活安全担当課長","answer":"品川ケーブルテレビを使った場合に、発信限定などのような措置がとれるということまでは検討していますけれども、それを使った振り込め詐欺防止の補助金という形での検討まではまだ踏み込んでいないのが現状です。","voiceIndex":319,"id":"exchange-134"},{"speaker":"山路委員","kind":"質問・要望","question":"ぜひ踏み込んでいただきたいことを要望しておきます。続きまして、地域からの情報提供ですが、用地情報については年にどれぐらいあるものか、またどういう情報があるのかお伺いをいたします。","respondent":"阿部経理課長","answer":"寄せられ方ですけれども、区内の不動産業者の方からの情報の場合と、あとは土地の所有者の方から直接の場合、大きく分ければこの２点です。","voiceIndex":321,"id":"exchange-135"},{"speaker":"山路委員","kind":"質問・要望","question":"こういうものを含めまして、新たにきめ細かく、また地域からの情報提供と区の計画とがマッチングするように検討を深めていただきたいと思いますが、どのようにお考えでしょうか。","respondent":"阿部経理課長","answer":"１点目の先ほどの用地情報の件ですけれども、件数といたしまして、平成１９年度は６件、平成２０年度は現在までに１２件です。","voiceIndex":323,"id":"exchange-136"},{"speaker":"山路委員","kind":"質問・要望","question":"もう少しありますので、来年の長期基本計画に向かっての事業計画と地域からの情報提供とマッチングしながらきめ細かく検討していただきたいということにつきまして、ご意見をお願いいたします。","respondent":"福島長期計画担当課長","answer":"そういった拠点をこれからつくるに当たりまして、地域の情報をいかに得ていくか、そのときに得たときにどうするか、そのときの状況あるいは予算あるいは使い勝手等を勘案しながら計画に盛り込むとともに。","voiceIndex":325,"id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"１０３ページの庁舎等維持管理費、それと１０７ページの防災対策費あるいは防災訓練経費、時間がありましたら１０４ページの区民まつり経費までいければいいなというふうに思っています。１点目の１０３ページの庁舎等維持管理費６億１,８２５万３,１７０円、これだけ大きな金額が１行でまとめられているんですけれども、これの内容をお聞きしたいと思います。","respondent":"阿部経理課長","answer":"その委託経費です。それは３億９,０００万円余です。その次には先ほども出ましたけれども、庁舎等の光熱水費、これが１億１,８００万円余です。この２つが大きいものです。","voiceIndex":328,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問・要望","question":"実は光熱水費のほうですけれども、光熱水費というとガス、水道、電気でしょうか、これがどれぐらい、１年間に１億１,８００万円という話を聞きましたけれども、４、５年前からさかのぼれるならば、どれぐらいの経費がかかっているのか数字的にお教えいただきたいと思います。","respondent":"阿部経理課長","answer":"水道につきましては、平成１５年度については２,２００万円、平成１６年度については２,１００万円、平成１７年度１,９００万円、平成１８年度２,０００万円、平成１９年度２,１００万円という推移です。","voiceIndex":330,"id":"exchange-139"},{"speaker":"松澤委員","kind":"質問・要望","question":"細かく数字を出していただきました。この契約の見直し、我々もガス料金、水道料金、契約書があるんですけれども、細かくてよくわからない、見ないよ、なんていう人もいるんですけれども、その内容が近年、いろいろな中で変わってきているというんですけれども、この契約の見直しについて、品川区としては省エネ診断というんですか、どのような形をとっているのか、お教えいただきたいと思います。","respondent":"阿部経理課長","answer":"契約の改正につきましては、この診断を受けた時点で契約電気料を削減、７００ワットから６００ワットに契約変更するという工夫をして、省エネを図っているものです。","voiceIndex":332,"id":"exchange-140"},{"speaker":"松澤委員","kind":"質問","question":"診断ですね。「現在お客様がガス料金を払いすぎていないかどうか、ガス料金削減の余地があるかどうかを無料で診断します」。こういう形で書かれているんですね。水道なんかもおそらく、電気なんかも、そういう形でやっていくんでしょうけれども、こういうコンサルタント業務というんですか、こういうのとお話をして、さらに削減をしようというお気持ちがあるのかどうか、その辺をお聞きしたいと思います。","respondent":"阿部経理課長","answer":"今さまざまな方法がありますので、そういうことも含めまして、より一層のコストの削減、省エネルギー、あるいはコストの削減に努めていくということは検討してまいりたいというふうに思っております。","voiceIndex":334,"id":"exchange-141"},{"speaker":"松澤委員","kind":"質問","question":"民間の会社。やはり品川区は行革も率先してやっているんですから、こういう新しい業界が出てきたら、やはりその勉強も、ほかがやっていないからやらないではなくて、少しは勉強したらいかがですかというのが、これは、私は答弁は要りませんので意見だけ申し上げております。それから、１０７ページの防災対策費、防災行政無線スピーカー取替工事等７９２万８,８６５円、これはどこを取りかえたのでしょうか。","respondent":"中山防災課長","answer":"区内に固定系のスピーカーは１３４基立っていますけれども、そのうちの３８カ所、１つに大体４つのスピーカーがついていますので、そのすべて４つをかえるか、３つをかえたかというようなことで１４４台取りかえたものです。","voiceIndex":336,"id":"exchange-142"},{"speaker":"松澤委員","kind":"質問","question":"これは、品川区内にある全部の防災無線を取りかえたのでしょうか、その辺をお聞きしたいと思います。","respondent":"中山防災課長","answer":"一応３年計画で、全固定系のスピーカーを取りかえる予定です。","voiceIndex":338,"id":"exchange-143"},{"speaker":"松澤委員","kind":"質問・要望","question":"実は防災訓練に参加させていただきました。その運用がどういうふうにされているかなというふうに見たんですけれども、中学生が全員参加していて、ポンプ３台、１２人、これは一斉に放水しているんですね。ああ、中学生がやってくれる、これが本当の防災だねというふうな感じで、私はいたく感激したんですけれども、そこに副区長がずっといたので、その感想を一言ちょっとお聞きしたい。","respondent":"本間副区長","answer":"こういうような、荏原第四中に続いて、今回大崎中を私は見させていただきましたけれども、こういう輪がさらにそれぞれの他の中学校でも広がってくれたら力強いなというのが私の抱いた感想です。","voiceIndex":340,"id":"exchange-144"},{"speaker":"松澤委員","kind":"質問・要望","question":"この中学校で防災訓練をやっていれば参加しやすい学校も、ただいろいろな地域ですから、１３地域の中では林試の森公園でやっていたり、あるいは小学校でやっていたりということで参加できない中学校もあるんでしょうけれども、これは今回はモデルで４校ですけれども、来年度から順次配置していくようになったときに、予算特別委員会の中でも言ったんですけれども、子どもたちが参加できる。","respondent":"中山防災課長","answer":"ご指摘のとおり、順次マッチング式にかえていく予定です。それから私もあの場におりました。余計かもしれませんけれども、私も副区長と全く同感です。","voiceIndex":342,"id":"exchange-145"},{"speaker":"川西委員","kind":"質問","question":"１０９ページ、地域センター等管理運営費、１０６ページ、事業部支援プロジェクト、職員研修、そして、時間があれば保養所について伺います。一番初めに地域センター管理運営費、エレベーターの設置についてです。この事業内容、そして地域センターの中で、エレベーター設置のまだ残っている箇所といいますか、数についてお知らせください。","respondent":"中山地域活動課長","answer":"平成１９年度の維持管理の中の工事ですけれども、エレベーターを設置したのが品川第二地域センターです。そのほか、エレベーター関係ですと管制装置等の取りつけを行いましたけれども、エレベーター設置は１カ所です。","voiceIndex":345,"id":"exchange-146"},{"speaker":"川西委員","kind":"質問","question":"私は、品川区第二地域センターの区域に住んでおりまして、びっくりしております。大変入り口が明るくなりまして、使いやすく、近寄りやすい、利用しやすいセンターになりました。ついでに伺うんですけれども、昇降機の効用について、いまどういうふうに反省をしていらっしゃるのかというのと、今後の計画がわかれば、わからなかったら、地域センターをエレベーター化するのに、わかったら教えてください。","respondent":"中山地域活動課長","answer":"いわゆるバリアフリーを含めたこの昇降の手段ですけれども、やはり利用者の方で、午前中のご質問にもありましたように、地域センターあるいは区民集会所利用の方、高齢化を考えますと、こういう昇降手段というものは、きちんと充実すると同時に。","voiceIndex":347,"id":"exchange-147"},{"speaker":"川西委員","kind":"質問・要望","question":"地域センター、これからコミュニティの拠点として今後いろいろ改善をされていくと思うんですけれども、第一歩として、品川第二地域センターのこの明るさといいますか、利用しやすさ、これを大変評価したいと思いますので、今後また要望をつけ加えていきたいと思います。","respondent":"久保田行財政改革担当課長、福島長期計画担当課長","answer":"ボランティア・ＮＰＯ法人との協働のしくみづくりですけれども、こちらにつきましては、基本構想のほうで協働を進めるといった中で、品川区として、その協働を進めるに当たりまして。私からは次世代育成支援対策についてお答えさせていただきたいと思います。こちらにつきましては、品川区次世代育成支援対策推進計画、行動計画を平成１７年３月に制定しました。その後、推進のための推進協議会を開催しているものです。","voiceIndex":349,"id":"exchange-148"},{"speaker":"川西委員","kind":"意見","question":"そうしますと、ボランティアそれから民間活力のほうは、具体的にどんな活動をしたかというのはご答弁がなくて、この今の次世代のように協議会をつくって行動をしたと。協議会のメンバーについてはどういうメンバーなのか、何回ぐらい年間にこの年度、この経費でおやりになったのか、聞きたいと思います。","respondent":"福島長期計画担当課長、久保田行財政改革担当課長","answer":"次世代育成のほうの推進協議会ですけれども、メンバーは全部で１５人です。学識経験者２名、それと公募区民が５名、それ以外に青少年委員ですとか教育関係者、主任児童委員、保育事業者などです。年間２回行っているものです。作業部会につきましては、平成１８年度から継続してやっておりますけれども、約１０回ほど作業部会ということで検討を進めまして、それで協働を進めるに当たりまして、区としてどういった仕組みをつくっていくかという。","voiceIndex":352,"id":"exchange-149"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、この経費、これは主に庁内でやっている事業なのに講師の謝礼なのか、民間の方の出会手当なのか、それだけ、ちょっと一言でいいですから。","respondent":"久保田行財政改革担当課長","answer":"これにつきましては、調査研究にかかりますコンサルタントへの委託料といったものです。","voiceIndex":355,"id":"exchange-150"},{"speaker":"川西委員","kind":"質問","question":"わかりました。そうしますと、職員研修の共同研修、これはグループ研修のことかというふうに認識しておりますが、これは区政運営のために提言が重点なのか、職員の資質向上が重点なのか、そこだけお伺いいたします。","respondent":"榎本人事課長","answer":"この共同研修というのは特別区の研修所の研修というもので、ともに働くというほうの研修ではないので、実際の実績で出ているのは研修所に行った人数の実績です。","voiceIndex":357,"id":"exchange-151"},{"speaker":"川西委員","kind":"質問・要望","question":"それは改めてまたもう一回伺います。最後に保養所のことだけ要望で申し上げます。今、過去において伺っているのは、６０％以上の部屋稼働率といいますか、それはやはり民間のホテルや何かでも７０％を越すことは少ないのではないかというご答弁をいただいたことがあります。私は品川区の中で、非常にやはり守っていくべき、この２つの保養所はぜひ直営でお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":359,"id":"exchange-152"},{"speaker":"安藤委員","kind":"質問","question":"成果報告書１０２ページの非核平和都市品川宣言事業について伺いたいと思います。事業の目的を改めて簡単にお伺いしたいのと、あとは区民への定着、浸透度合いなどということでは、どのようにお考えでしょうか。","respondent":"伊勢総務課長","answer":"この事業の目的ですけれども、昭和６０年３月に非核平和都市品川宣言が出されまして、この趣旨である核兵器の廃絶と恒久平和確立の精神を継続的に普及させていくとともに、戦争の悲惨さ、平和の大切さを次世代に伝え、区民の平和意識の高揚を図るというものでございまして。","voiceIndex":361,"id":"exchange-153"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこでちょっとお伺いしたいのが、区民の手による自主的な平和活動、区内ではどのようなものがあって、どのような現状になっているのか、具体的にそのような活動に対して、区としてどのような支援を行っているのかというのをお伺いしたいと思います。","respondent":"伊勢総務課長","answer":"基本的にはこの平和事業は区が主体的に行う事業ということで、いろいろな団体の方が平和事業をやられていると思いますけれども、我々がやっているのは、あくまでも区が自主的に判断して平和事業を展開している、こういうことで、特に調査などはしてございません。","voiceIndex":363,"id":"exchange-154"},{"speaker":"安藤委員","kind":"提案","question":"支援が不十分だと思いますので、改めてこちらのほうでも支援していただきたいのですが、実際に自主的に平和活動をやっている方からちょっと伺ったことなんですけれども、支援が不十分どころか、なかなか積極的に平和団体のほうから、こういう普及活動、平和の自主的な活動を行いたいんですけれども支援してほしいんですがという具体的な提案をしたそうなんです。","respondent":"伊勢総務課長","answer":"そういうようなお申し出があったかどうかにつきましては、私のほうは把握してございません。それから、そういうような支援についてはどうかですけれども、先ほどから申し上げていますように、区が主体的にこの事業を進めていくと。","voiceIndex":365,"id":"exchange-155"},{"speaker":"安藤委員","kind":"質問","question":"はなからそういうことを考えていないというのではなく、より多くの区民の方と手を携えて、しかも今戦争体験をお持ちの方ですとか、もちろん被爆者の方も高齢、平均年齢が７５歳、いつまで語り継げるかわからないという中で、一人でも、だれもが戦争体験を語り広げなくてはいけないというように思います。なぜこういった支援をはなから検討もしないではねのけてしまうのか。なぜしないのでしょうか。","respondent":"伊勢総務課長","answer":"これにつきましては確かにご高齢の方がいらっしゃいますので、そういう方々の声を何らかの形で広めるといいますか、保存するといいますか、そういうことは区としても大事だというふうに、この宣言１０周年のときも考えていましたし、今もそういうことで。","voiceIndex":367,"id":"exchange-156"},{"speaker":"安藤委員","kind":"質問","question":"いろいろな団体、核兵器を廃絶してほしい、あるいは戦争をなくしたいという思いは、思想信条関係なく、ありとあらゆる方が願っていることだと思いますので、どうか色眼鏡で見ないで、まずきちっと、どういう活動をしているのかというのをまずいったん申し出を受けた上で、考えた上で、やるべきだと思うんですけれども、いかがかというところが１つ。","respondent":"伊勢総務課長","answer":"その団体の関係ですけれども、区は区自身で判断しまして事業を進めておりますから、そういう面で、その団体に入っているか入っていないかというところが決まってきたのではないかと思ってあります。","voiceIndex":369,"id":"exchange-157"},{"speaker":"安藤委員","kind":"質問・要望","question":"この長期計画の案であります、この地域における身近な非核平和意識の普及活動展開、区民参加による平和事業の推進というところは一体何を指しているのかというのを、具体的にちょっと今考えているところがあれば説明していただきたいのと、先ほどの離脱の件、こちらもなぜ離脱してしまったのか、お願いします。","respondent":"伊勢総務課長","answer":"ですから離脱の具体的な理由といいますか、区の考えと合っているかどうかというところがポイントになると思います。","voiceIndex":371,"id":"exchange-158"},{"speaker":"安藤委員","kind":"質問・要望","question":"区のほうで、より好みといいますか、私は広島に行ってきましたけれども、今年、品川の青年の皆さんと一緒に行ってきました。そうしたら、広島を初め、もう２０２０年までに核兵器廃絶というのをしっかりと明確に見据えて、世界１つで頑張ろうという雰囲気を感じました。ぜひ、そういう流れに品川区も合流していただきたいと要望したいと、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":373,"id":"exchange-159"},{"speaker":"三上委員","kind":"質問","question":"１０２ページの国際友好都市交流について。時間がありましたら、１０６ページの契約という部分についてお伺いをさせていただこうと思います。最初に、この人件費比率について、人件費比率の推移の中で、平成１８年度から平成１９年度、品川区としては２０.５％から２２.３％、ちょっと膨らんだというふうになっていますけれども、これについての原因というのはどういうことでしょうか。","respondent":"榎本人事課長","answer":"その中で職員給与は前年比マイナスなんですけれども、退職手当につきましては、退職者の増加に伴いまして、前年比で１０億円プラスになったというところで人件費が伸びたという形です。","voiceIndex":375,"id":"exchange-160"},{"speaker":"三上委員","kind":"質問","question":"そうすると、退職手当ということで膨らんできている。となると、品川区の３３万人、３４万人になりますか、そういう人口のところにあっての適正な職員数という、区民サービスが低下しない、そういったことを考えていったときには、どういうふうなところまで絞っていくということが考えられるのかということについては、どういうふうにお考えでしょうか。簡単でいいですから。","respondent":"榎本人事課長、伊勢総務課長","answer":"そういった意味で、２３区平均のところまで来ましたので、今後については、その推移をきちんと維持できる形を目指していきたいというふうに思っております。近隣のところとの交流ですけれども、大変アジアとの交流が、とみに最近活発になってきておりまして、そういう背景を考えますと、そういうご提案の方向でやるべきだというふうに考えてございまして、現在そういう検討を始めているです。","voiceIndex":377,"id":"exchange-161"},{"speaker":"三上委員","kind":"確認","question":"ということになってくると、やはり東南アジアというような部分についても積極的にそういう交流活動というものは、民間が中心になるのかは別としても、そういうことの交流に対しての基本的な考え方はもっと持っていったほうがいいんじゃないかな、こういうふうに思いますけれども、あわせて区長、いかがでしょうか。","respondent":"濱野区長","answer":"これは既に長期基本計画の中でもいろいろ検討しているようでありますけれども、そういった方向も見ていかなければいけないのではないかというふうに思っております。","voiceIndex":380,"id":"exchange-162"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は、今の三上委員の質問とかなり重なってしまっているんですけれども、１０１ページの退職手当、職員給与費、それから１０２ページ、国際友好都市交流事業、それから１０５ページ、広報費、それから、１０６ページ、会計管理費、契約関係の事務費関係です。ですから、これはやはり表現方法をかなりお考えいただきたいなと思うんですが、その辺でお答えをいただきたいと思います。","respondent":"日下部企画財政課長","answer":"確かに今ご指摘のように、ルールではありますけれども、ただそれを区民の皆さんにご覧いただいたときに、やはりどちらかというと誤解を招きやすい面、確かにあろうかと思いますので、区民の皆さん方にお知らせする際は、その辺、誤解を招かないような工夫を図ってまいりたい。","voiceIndex":384,"id":"exchange-163"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"東京電子自治体共同運営に関しての話ですので、直接区のほうでどこまで答えられるかというのが難しい部分もあるかと思うんですけれども、その辺、お考えを教えていただきたいと思います。それが仕事ですから、こういうこともできないのかというお話も伺っております。それと同時に、区から電子自治体共同運営のほうに申し入れをしていくこともできるのかどうか、その辺のお考えをまずお聞きしたいと思います。","respondent":"原情報システム課長","answer":"共同運営の関係のシステムにかかわるところですので、私のほうからご説明させていただきたいと思います。","voiceIndex":386,"id":"exchange-164"},{"speaker":"鈴木（真）委員","kind":"確認","question":"状況はだいぶわかりました。１つ残念なのは、ニュージーランドへ行って羊もキウイも見なかった。その交流の中で、今度頑張って行っていただいた茶道、華道の協会ですか、それから攻玉社の皆さん、すごく成果を発揮していただいたと思っているんですが、今後、この方たちと友好協会ではなくて区がどういう接点を持っていくのか、そこら辺をどういうふうにお考えになるのかなというのが１点。","respondent":"濱野区長","answer":"そういう意味では茶華道、こういったもの、あるいは剣道、今回剣道ですけれども、こういったもの、日本を代表する文化であり、スポーツである、こういったものを紹介するというのは十分に意味のあることだというふうに思っておりますので、これはこれで継続してまいりますし。","voiceIndex":388,"id":"exchange-165"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひそういう方向に向かっていただきたいと思います。あまりここで先の数字を想像してもわかりにくいところなので、そちらは後回しにしますけれども、逆に、中途採用を今なさっていらっしゃる状況を確認をさせていただきたいと思います。","respondent":"榎本人事課長","answer":"その中で経験者採用という形で、民間企業の経験ある方が、平成２０年４月から、１８名ということでスタートして、また来年、平成２１年度につきましても採用する予定で、今作業を進めております。","voiceIndex":390,"id":"exchange-166"},{"speaker":"鈴木（真）委員","kind":"質問","question":"経験者採用ということで１８名ということなんですが、当然経験者の方が、民間で働いていた方が区に新しい力を入れてくださると思います。その方のポジションというか、資格というか、どういうふうにスタートを切っていくのか、現在の今役職を持っている、例えば係長、課長との兼ね合い、その辺はどうなっているんでしょうか。","respondent":"榎本人事課長","answer":"係員のほうの２級の採用につきましては、３年目で主任主事の選考が受けられるという形で、新規採用で入った方よりかは、わりと近い時間で主任選考の資格が出るというような形のポジションにおります。","voiceIndex":392,"id":"exchange-167"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。そうすると、現在もともと下からずっと上がってきて今頑張っていらっしゃる方と、やる気というか、その辺の、片一方は活性化を図ってくださる部分、逆に本当はハッパをかけて、いままでやっている方は頑張ってもらいたいという意味があるんですけれども、そこら辺で、職員の方の意識というのは何か変わりが出ているんでしょうか。","respondent":"榎本人事課長","answer":"やはり民間の企業経験があるということで、それも職歴が１カ所ではなくて、２カ所とか３カ所ある方もおりまして、そういったもので自分が天職としたい仕事をどこに求めるかという形で十分仕事と向き合ってきた人材ということでありますので、そういった中では。","voiceIndex":394,"id":"exchange-168"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ切磋琢磨していっていただいて、仕事のほうを、これからも品川区のために頑張っていただきたいと思います。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":396,"id":"exchange-169"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1294#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":115194,"voices":397}},{"id":"h20-20081009-4","meetingId":"h20-c-settlement","date":"2008年10月9日","dateIso":"2008-10-09","committee":"決算特別委員会","time":"午前１０時０２分～午後５時４５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を152件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井桁委員","kind":"質問・要望","question":"私は１２４ページ、３項の児童福祉施設費の中の相談機能充実経費と、すくすく赤ちゃん訪問事業についてお伺いしたいと思います。このすくすく赤ちゃん訪問事業というのは、平成１９年度から開始されたと聞いております。そこでまた、ますますの拡充をお願いして、幾つか質問させていただきたいと思います。","respondent":"諸岡児童課長","answer":"すくすく赤ちゃん訪問事業に関するお尋ねです。この事業、平成１９年度から開始いたしまして、それまで行っておりました保健所、保健センターの新生児訪問と連携をして実施をしております。児童センターの職員がご家庭を訪問するという事業です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"井桁委員","kind":"質問・要望","question":"そしてまた、先ほど連携といった意味でのお伺いなんですが、相談機能充実経費という中に、品川区こども家庭あんしんねっと協議会というのを平成１８年から行っているということなんですが、これとのかかわりも、先ほどの最初に介入して、やはり小さいときから周りで見守っていくといった中で、この協議会というのは大変大切な存在となってくると思うんですけれども、これについてもいろいろな連携を図る中で。","respondent":"諸岡児童課長","answer":"先ほど申し上げました、すくすく赤ちゃん訪問事業の中で発見されました、支援が必要な家庭も、このこども家庭あんしんねっと協議会につなげまして、地域の中での地域の方々の見守り、それから関係機関のかかわり等につないでいって。","voiceIndex":6,"id":"exchange-002"},{"speaker":"井桁委員","kind":"質問","question":"そこで、この相談なんですけれども、平成１８年度と平成１９年度と、資料のほうで調べましたら、育児・しつけ相談というのが約半数に減っているんですが、それについて児童館なりで早期に対応した結果なのかなと思っているんですが、その辺はいかがでしょうか。","respondent":"諸岡児童課長","answer":"特に平成１８年度から、そこに専門相談員ということで、児童相談所で長年子どもにかかわってきた方々、そういうベテランの方を配置して、児童センターも相談の窓口ということで、相談を開始しております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"井桁委員","kind":"意見","question":"昨年のすくすく赤ちゃん訪問事業のほうで、保健所の件数というのも、平成１８年度が１,３１２件だったのが、平成１９年に１,６９４件と、保健所との連携というところで、再度かかわり合いといいますか、そういったことをお聞かせ願いたいと思います。","respondent":"諸岡児童課長","answer":"すくすく赤ちゃん訪問事業です。冒頭申し上げましたように、保健所・保健センターと連携を図りながら行っておりまして、これは最終的にはすべてのご家庭、育児の孤立化等を防ぐために、全戸訪問をいたしております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひともこの事業をさらに拡充していっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"若林委員","kind":"質問","question":"介護保険全般、保険料も含めまして質問をします。そこで平成１９年度決算も踏まえまして、この第三期の計画の見込みが当然立てられて、第三期の計画がここまで進められてまいったわけですが、ここら辺の見込みの現状認識をまずお伺いしたいと思います。ここら辺がなぜこういう見込みとまたちょっとずれてきたというんでしょうか、見込みとの変化が起きてきたというところをポイントにお願いしたいと思います。","respondent":"冨岡高齢福祉課長","answer":"当然、介護給付をベースに、どのくらい伸びていくのかというのをベースに考えまして、それから次に保険料を設定するという形で進めていくわけでありますけれども、結果的に介護給付のほうが諸制度の変更等によりまして。","voiceIndex":14,"id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"ちょっと時間がなくなりましたので、そこで保険料の設定について伺いたいと思います。第三期の当初、国のモデルに従いまして、６段階の設定がされました。通院の考え方についても、今使いづらい、通院だけ、病院の中に入った時間はまたそこに算定されないというような現状もありますので、ここら辺のより高齢者の身に添った制度のあり方についてお示ししていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"生活援助の考え方ですが、これにつきましても、通院中の介助というものは確かに問題意識を持っておりますので、これは計画の中でどのように反映させていくかということも含めて検討させていただきたいと考えています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"私のほうからは、国民健康保険について伺ってまいりたいと思います。数字を伺いたいんですけれども、滞納世帯数、これは平成１９年度は２万３,１４７世帯ということで、２８.０４％というふうに聞いているんですけれども、滞納世帯で年金収入のみ、あるいは無収入という世帯数を教えていただきたいと思います。","respondent":"本城国保年金課長","answer":"それとあと、今までの内訳を若干変えた件ですが、こちらにつきましては、システム改修に合わせて、内訳を変更させていただいたんですが、ただ基本的な構成は大きく変えたわけではありませんで、今までの統計のとり方が。","voiceIndex":19,"id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"そこでちょっと伺いたいんですけれども、後期高齢者医療制度が実施をされまして、国民健康保険から７５歳以上の方、３万７００人が品川区の場合は始めていったわけですけれども、国民健康保険制度だけで考えると、これは、医療費の削減につながっているわけですから、保険料率というのは下がって当たり前なんだと思いますけれども、この辺についてお聞かせ願いたい。","respondent":"本城国保年金課長","answer":"それとあと、もう１点の天引き、特別徴収の関係ですが、そちらにつきましては、平成２０年度から特別徴収制度が国の制度として開始されたわけですが、途中から若干の国の制度の軌道修正がございまして、口座振替等希望される方については、そちらに移行することができる等。","voiceIndex":21,"id":"exchange-009"},{"speaker":"菊地委員","kind":"質問・要望","question":"保険料が、これからの運営の中で、私は下げられるのではないかと聞いたんです。この辺をお聞かせ願いたいんです。実際に６月にまとめられた徴収額の決定の状況だと、老人保健拠出金から、この後期高齢者への支援金の変更でもって５,３２４億円減少したんだと発表していますけれども、先ほどお答えくださった中身だと、どうもよくわからないんですね。この辺をもう少し明確にしていただきたいと思います。","respondent":"本城国保年金課長","answer":"後期高齢者の支援金が今どういう状況かですが、そちらについて、まず平成２０年度の予算ベースですと、３９億１,０００万円です。それに対して、老人保健の拠出金につきましては、平成１９年度決算時点で６８億４,０００万円という状況です。","voiceIndex":23,"id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"そうであれば、これは２３区との関係もあるんでしょうけれども、いずれにしても、制度全体が切り替えられたわけですから、当然のことながら、例えば一般財源からの繰り入れというのを減少させればまた別になりますけれども、少なくとも今までの計算上の流れで言えば、明らかに政府でも言っているように、国民健康保険の状況というのは改善をされているということになるわけですから、当然のことながら。","respondent":"本城国保年金課長","answer":"ちょっとご説明不足だったかもしれませんが、今回の平成２０年の制度改革の中で、新たに後期高齢者医療制度が創設されましたが、それとともに前期高齢者の財政調整制度とか、もろもろの制度改革があわせてあったところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"収入との関係でね。その所得に占める保険料率が出されているんですけれども、これを見ますと、国民健康保険で収入に占める割合は１１.６％だと。所得の最も低い世帯に最も高い医療保険料が課せられているわけですから、これはだれが考えたっておかしいじゃないですか。やっぱり今、考えるべきなのは、どうすれば皆さんが大きな負担なく安心をして医療にかかれるかどうか、ここなんだと思うんです。","respondent":"本城国保年金課長","answer":"それにつきましては、国民健康保険は社会保障制度の一環として相互扶助ということで、より多くの方がみんなで支え合うという制度の趣旨ですので、そういった点から保険料も今のような状況になっていると考えてよろしいかと考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"菊地委員","kind":"意見","question":"今のお話だと、国民皆保険制度というのは一体何なのかとなりますよね。政府はこの間、今の社会保障改革で、２,２００億円からの社会保障費を削ってきた。私も先月、７２歳になる方、非常にぐあいが悪くなって、病院に行ったけれども、大丈夫ですよと帰された。その方が３日後にぐあいが悪くなって入院されたけれども、そのまま亡くなっちゃった。保険料率を下げること、ぜひ考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-013"},{"speaker":"稲川委員","kind":"質問・要望","question":"私は成果報告書の１１３ページ、団塊世代意識調査、１１６ページの高齢者世帯の安否確認事業全体、緊急通報システム、安全確保、福祉電話、住宅用火災警報器、１２５ページの生活保護費についてお伺いいたします。今回、１回目、昨年の６月から７月に調査をして、結果が３月に取りまとめが出ているんですが、今後もこういった調査をしていくのかどうかがまず１点。その３点をお聞かせください。","respondent":"永尾高齢事業課長","answer":"この結果、就労を希望されている方というのが、予想外に多かったという結果になっておりますけれども、印象としましては、まだまだこれから６５歳まで定年も延びるということもありまして、働きたいというような意向が強いというのと。","voiceIndex":31,"id":"exchange-014"},{"speaker":"稲川委員","kind":"質問","question":"なおかつ、ほかを見ると、町会への参加率とかを見ても、本当に８％とか、１０％行っているところはない、こういったアンケートをもとに今後もやらないという状況で、この調査をもとに施策を練るというのはちょっと無理が、なかなか参考にならないアンケートじゃないかなと思うんですが、いかがでしょうか。","respondent":"永尾高齢事業課長","answer":"ということなので、まずはこういう方々に働きかけをいたしまして、そういう方を中心に地域でどういうことができるかということに取りかかってまいりたいと考えております。","voiceIndex":33,"id":"exchange-015"},{"speaker":"稲川委員","kind":"質問・要望","question":"この質問は以上です。次に高齢者世帯の安否確認事業なんですが、これはこのシステムというのは警備会社がすべて運営管理をされているということなんですが、まずこの導入件数ですか、高齢者世帯にこれを設置している件数を教えてください。","respondent":"冨岡高齢福祉課長","answer":"内訳が民間型が１７３台で、消防庁型が１２４台です。","voiceIndex":35,"id":"exchange-016"},{"speaker":"稲川委員","kind":"質問","question":"この２９７件において、過去、現在の段階で、警備会社がそこに緊急で行ったとか、行ってなおかつそこで警察を呼んだとか、改めて消防を呼んだとかというケースというのは何件ぐらいあるか教えてください。","respondent":"冨岡高齢福祉課長","answer":"実際に出ましたのが平成１９年度では１０件出ております。今年は８件と、これは９月末現在です。そういった出動状況です。警察が出たということについては、こちらに報告が来ていませんので、警備の段階で終わったと理解しております。","voiceIndex":37,"id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問","question":"私は障害者福祉費の１１８ページ、レクリエーション大会経費、１２３ページ、児童センター運営費、１１７ページの補装具について伺ってまいります。今後の障害者福祉を進めていく上で、今日取り上げたいのが、啓発活動の大切さを自分が少し感じているものですから、伺いたいと思います。主な啓発事業と、規模と対象をまずご紹介いただければと思います。","respondent":"高橋障害者福祉課長","answer":"それと２点目が、障害者週間記念のつどいということで、１２月３日から１２月９日まで障害者基本法に基づきまして、障害者週間ということがありますが、そこの中で１日だけですが、きゅりあんの大ホールを貸し切りまして、記念のつどいを開催し。","voiceIndex":40,"id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"そういった中で先日、障害者福祉課長と障害者福祉について別件でお話しした中で、自助と、あとこれからの時代、共助だというお話に触れられていまして、自分の中で共助って何だろうという中で、非常に印象に残ったことがあったので、こういった啓発活動の仕組みというか、伝わり方、伝え方含めたあり方を１点と、ひいては共助への考え方を伺えればと思います。","respondent":"高橋障害者福祉課長","answer":"その方について、なぜ自区内かと申し上げますと、自区内の方をサポートするために派遣されるということで、名簿を渡さなくても、自分が実際上支援をしている方はどういう方なのかということで、自分の身の安全を守った後。","voiceIndex":42,"id":"exchange-019"},{"speaker":"渡辺委員","kind":"質問","question":"では次に、１２３ページの児童センター運営費で伺いたいと思います。それを伺いたいと思います。ふざけ合うのも許容範囲かなと。その辺の対策を伺いたいなと思います。平日は学校のある時間は、うまくすみ分けがなされていると思うんですが、土日祝日も今、児童センターは頑張っているので、学校が休みの日、あるいは夏休み等の休業日で、この辺の時間のすみ分け等が考えられているのか、伺いたいと思います。","respondent":"諸岡児童課長","answer":"次にベビーカー等の対応ですけれども、通常の平日であれば、時間的に乳幼児のお母さん方は午前中、小学生は午後から３時前後ということで、時間的なすみ分けができているんですけれども、日曜日等につきましては、大勢の方がいらっしゃいます。","voiceIndex":44,"id":"exchange-020"},{"speaker":"渡辺委員","kind":"質問","question":"全部を見たわけではないので、ただそういう声が、自分の中で多そうな感じがしたので、ちょうど今の時代の耐震化と合わせて、おおよその大規模改修を含めた施設の状況とか考え方を伺えればと思います。","respondent":"諸岡児童課長","answer":"児童センター、これは保育園も含めてですけれども、耐震改修を行っておりまして、今年度、９施設を予定しております。平成２０年度ですべての子どもにかかわる施設、児童センター、保育園の耐震改修が終わる予定です。","voiceIndex":46,"id":"exchange-021"},{"speaker":"渡辺委員","kind":"質問","question":"こういった状況に関しては、何か理由があったのか、あるいは今後の対策について伺いたいと思います。","respondent":"諸岡児童課長","answer":"その中庭を活用して、その活動に参加してできないか。そこをちょっと耕したりというようなことで予定をしています。","voiceIndex":48,"id":"exchange-022"},{"speaker":"浅野委員","kind":"質問","question":"私のほうからは、主要施策の成果報告書の１７５ページ、国民健康保険事業の医療制度改革準備経費、１１６ページ、社会福祉費の高齢者医療関係事業、後期高齢者医療制度準備経費についてお伺いします。データがお手元にあればということですけれども、平成１９年度の４０歳から７４歳の区民健診の受診率についてもあわせてお伺いします。","respondent":"本城国保年金課長、山岡健康課長","answer":"それとあと、その後、それを受けた形での特定保健指導の実施状況ですが、現在、その受診の結果、保健指導が必要だという方を対象にして、今、９月から実施しておりまして、受診した結果。区民健診の平成１９年度の状況ですけれども、平成１９年度は４０歳以上の方、対象者は１７万７,５９６人の方のうち、受診者、３万８,９１２人の方が受診しております。","voiceIndex":51,"id":"exchange-023"},{"speaker":"浅野委員","kind":"質問","question":"この前半に特定健診を受診していない方、再通知をするという回答をいただいておりますけれども、この実施時期と方法、特に前に送った券で受診して、また再度受診券を送った場合、もう１回受診してしまうという危険性もありますので、その回避の方法とか、また年度を通しまして、この参酌標準値、３５％の受診率の達成の見込みと。","respondent":"本城国保年金課長","answer":"現在、受診していない方についての新規の受診の勧奨についてですが、今回、初めての制度ということでもありますので、個別に周知するという意味合いで、１１月にまだ受診していない方についてリストアップしまして、すべての方に送る予定です。","voiceIndex":54,"id":"exchange-024"},{"speaker":"浅野委員","kind":"質問・要望","question":"先ほども前向きのご答弁をいただきまして、本当にありがとうあります。当然品川区では出さないと思いますけれども、この辺の確認と、あと受診費用ですけれども、国民健康保険は今無料で行っていただいておりますけれども、こちらのほうの集合契約については、集合契約ということで、１本で幾らなのか、それとも健保組合ごとに違うのか、もしこの場でおわかりになりましたら、教えていただきたいと思います。","respondent":"山岡健康課長","answer":"各保険者の特定健診ということで、それぞれの保険者が今準備して実施しようとしています。実はこのそれぞれの保険者によって、自己負担のかけ方等々が違っていると伺っております。","voiceIndex":56,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"施設に入所されている方は対象にはならないと思いますけれども、平成２０年度の予算は１万６,３００人の予算を計上しているんですけれども、この対象者数と現時点までの受診者数、またこれもデータがお手元にあればですけれども、平成１９年度の７５歳以上の区民健診受診者の数についてお伺いします。","respondent":"永尾高齢事業課長","answer":"区民健診のほうですけれども、平成１９年の区民健診の７５歳以上の方ですけれども、人口が２万９,３３５人、受診者数が１万３７１人ということで、受診率は３５.３５％となっております。","voiceIndex":58,"id":"exchange-026"},{"speaker":"浅野委員","kind":"質問","question":"いよいよこの後期高齢者医療制度、年金からの天引きが１０月１５日からスタートすると聞いておりますけれども、こちらも第２回定例会で質問させていただきましたけれども、そのときの回答で混乱を防ぐためにも、ホットラインの開設、日曜日の窓口開設によりきめ細かい対応をされると聞いております。","respondent":"永尾高齢事業課長","answer":"これまでの窓口の状況ですけれども、最初に７月の半ばにお送りした時点と、あと８月の中旬、変更になったときにお送りしたとき、その後１週間ほどが非常にピークになっておりまして、窓口、電話両方とも増えている状況です。","voiceIndex":60,"id":"exchange-027"},{"speaker":"浅野委員","kind":"質問","question":"ぜひとも混乱のないように、区民の皆様を待たせるようなことがないように対応をお願いしたいと思います。この点につきまして、最後にご意見をお伺いしたいと思うんですけれども、国民皆保険の維持ということに関しまして、今回の後期高齢者医療制度を含めた医療制度改革が必要なものであったという件につきまして、最後に区のほうのご意見をお伺いして終わりたいと思います。ご意見をお願いします。","respondent":"木下福祉高齢事業部長","answer":"今回の医療制度改革につきましては、国民皆保険を維持するという観点から、やはり必要な改革でございまして、保険者の統一ということが１つのコアの部分としてあったかと思います。そのことは今後とも必要だと考えております。","voiceIndex":62,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"１２１ページの空き店舗活用型保育サービス拠点支援事業、１２２ページ、保育園運営費、１２３ページ、子育て支援事業費、１２４ページ、家庭あんしんセンター運営費ですが、まず空き店舗活用なんですけれども、利用状況と実績、あとこれからのほかの地域への展開はどのように考えているのか、教えてください。他地域、地区の展開というのはどのように考えているのか、教えてください。","respondent":"小林保育課長、諸岡児童課長","answer":"延べ日数で８９６日ほどです。一方、一時預かりにつきましては４６４人と、延べ４,１７８時間の時間で、安定して、若干利用増の傾向にあります。子育て支援センターにおきましては、子育て相談等による来館者等が年々増えておりまして、さらには平成１７年の地方自治法改正に伴いまして。子育てルームの今後の方向性ということでございましたが、今回は空き店舗でしたが、空き店舗に限らず、地域の子育てという観点で。","voiceIndex":65,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"今回、空き店舗で伺いましたけれども、空き店舗という形に限定しないで、地域でやっていくという確認でいいと思います。これ、数字的に間違いがないのかということと、２,７００円で何をやるんですかという思いがあるんですけれども、内容の説明よりも、金額の説明をしていただきたいと思います。お年寄りというのは、年齢的といいますか、どこら辺を指してお年寄りと言うんでしょうか。","respondent":"小林保育課長、諸岡児童課長","answer":"保育園におきます交流の中では、お年寄り、何歳というよりはおおむねめどとして６５歳以上で、保育園の中で主にふれあい給食を一緒に食事をしながら、子どもと交流していいただくということで。他地域での展開ということですけれども、今後の展開の必要性は感じておりますけれども、まずはこの子育て支援センターの新たな展開に向けての充実を図って、その上での展開を考えていきたいと考えております。","voiceIndex":69,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、その辺は考えていっていただきたいと要望します。それと、保育のことでお伺いしたいんですけれども、特別委員会の議事録を読んでいましたら、自助努力みたいな、保育に関しては自助ということが読み返すと結構出てきているんですね。段階的にいろいろしているということはわかっているんですけれども、やはり待機児のことが頭から離れないもので、改めて今後の待機児の対策等についてお伺いします。","respondent":"小林保育課長","answer":"そういった意味では既存の施設の活用のほか、内容、レベルの向上も含めて、幼保一体の制度、あるいは認証保育所の助成等も含めまして、総合的に対応してまいりたいと考えております。","voiceIndex":72,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"もっと単純なことで、難しいことじゃなくて、入れる方と入れない方がいるわけですね。入れない方というのは、切実な要望があるわけですね。入りたい、お子さんを預けて働きたいと。その辺の解消が、私も毎回質問していますが、やっぱりなかなか解消できないじゃないですか。その辺をぜひ解消していただきたいという気持ちで質問しているんですけれども。","respondent":"古川児童保健事業部長","answer":"切実な家庭に対しても、十分に私ども目を向けながら、保育園も増設していく部分もありますし、他の機関の活用もあります。国も新待機児ゼロ作戦の中では、特に施設だけではない、家庭的な保育ということを掲げてありますので、総合的に進めていきたいと考えております。","voiceIndex":74,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは成果報告書１１６ページの障害者福祉について何点か伺いたいと思います。みんなそれぞれ前向きに頑張ろうとしておりますけれども、お話を伺いまして、共通する悩みが幾つかあるなと思いました。親亡き後の子の問題とあわせて、とりわけ障害者の高齢化の問題について、現状の施策概要を教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"今まで障害者の方につきましては、高齢化のところでやはり親亡き後に十分に対応するということでは、施設入所なり、それぞれ個別に対応してきたところですが、１０年前に比べて高齢化が進んだ知的障害者の方については、今後、重要な課題と考えておりますので。","voiceIndex":77,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"知的障害者の方に限れば、６０代の方が今３倍というご説明だったんでしょうか。重要な課題というお話でありましたけれども、私も障害者の生活の悩みを伺う中で、この家族、あとご本人の高齢化が進んでいるなということを実感いたしました。今、重要な課題という話がありましたけれども、もう少し具体的にその中身を伺いたいと思います。","respondent":"高橋障害者福祉課長","answer":"高齢化の部分については、１０年間の推移を見た段階で、こういう状況になってきた、今後もこれは増えていくということは考えております。今後、１０年間の実施計画の中で、この課題を具体的にどう実現していくかということで、今、検討をしております。","voiceIndex":79,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"私も先日、知的障害の１人娘と一緒にお住まいになっている方にお話を伺ってきました。この方は、知的障害の娘さんは４５歳、７４歳のお母さんと、７８歳の義理のお姉さんの３人暮らしでした。その娘さんを７４歳のお母さんが１日中生活を支えていると。お昼は急いで帰って、昼食の準備、娘に食事を与えてから、自分も急いでとる。その検討の課題について、もう少しお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"やはりそれぞれの本人の状況、暮らし方の希望ということは、ケアマネジメントの中で十分聞いていかなくてはならないかとは思いますし、障害者が地域で安心して暮らせる社会というのが、障害者自立支援法の基礎となっておりますので、その辺につきましては。","voiceIndex":81,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"きめ細かなケアマネジメントが本当に大事だと思います。この方に将来のことを思うと、心配なことは何ですかと伺ったときに、１つはもし自分が入院でもしたら、娘がどうなるのかと。現状、緊急のときにどういった対応があるのか、ちょっと教えていただきたい。いかがでしょうか。その障害者の方が親子で入れる特別養護老人ホームといった工夫も必要ではないかと思うんですけれども、いかがでしょうか。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"グループホームのことなんですが、やはりグループホームが区立でも、例えば北品川つばさの家ということで、平成３年に建てたのが、もう１７年経っていますので、高齢化になったということで、障害者自立支援法になってから。それで、例えば原小学校の跡のように、高齢者向け優良賃貸住宅をつくって高齢者住宅、こういうところでは例えば広めのところでは、ご家族でしたらお入りになれるという可能性はあります。","voiceIndex":83,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"親子で入れる特別養護老人ホーム、ぜひご検討いただきたいと思うんですね。この方の障害を持っている娘さんは今４５歳ということで、特定疾病がない限り、現在の仕組みではなかなか特別養護老人ホームの入所対象にはならないわけですよね。なぜ親子で入りたいかといいますと、お話を伺いましたら、何が悲しいかといえば、自分も今生きていると。もう少し現状、検討方向をお聞かせいただけますか。","respondent":"木下福祉高齢事業部長","answer":"やっぱりこういうことを先に考えていくことが、おそらくご本人の今後の暮らし方という部分でもニーズに合っているだろうと考えていますので、そのことも含めて進めていきたいと考えています。","voiceIndex":86,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"障害の程度も含めて、もちろんさまざまなのは私も感じています。ただ、この方の場合は、今寝たきりになって３年目なんですね。病気なら治るかもしれないし、治してみせるとお母さんは頑張っておりました。しかし、私の娘の場合は治るというよりも、それこそなかなか希望が見えず、いつまでかかるか、いつ終わるのかとも話しておりました。ぜひこの分野でも福祉の充実を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-038"},{"speaker":"山内委員","kind":"意見","question":"成果報告書の１２４ページの生活保護費についてお尋ねをします。","respondent":"志村生活福祉課長","answer":"生活保護受給の状況です。初めに平成１９年度決算におきましては、まだ平成１８年度の影響というんですか、それがあまり私どもの受給の人員にははね返ってくる数字ではありませんでした。ということは、大変微増な範囲で終わってあります。","voiceIndex":91,"id":"exchange-039"},{"speaker":"山内委員","kind":"意見","question":"大変苦しい状況なのかなということが今推測されたんですけれども、わかりました。この成果報告書の中から１つお尋ねします。この生活保護総務費の４段目、この専門調査員等報酬とありますけれども、専門調査員５人と書いてありますけれども、これは一体どのようなことをされる方なんでしょう。","respondent":"志村生活福祉課長","answer":"ちなみにこの方たちの人件費、それから事業費につきましては１０分の１０、国庫補助でいただいております。","voiceIndex":93,"id":"exchange-040"},{"speaker":"山内委員","kind":"質問・要望","question":"今、専門調査員５人、これは国庫負担で一般財源からの支出はないということを伺いまして、この５人という人数なんですが、これは品川区で適正な数と言えているのでしょうか。それからあともう１つ、品川区もケースワーカーがいらっしゃると思うんですけど、今、品川区全体のケースワーカーの数をお尋ねさせていただきたいと思います。","respondent":"志村生活福祉課長","answer":"今のところ５人の範囲でとは思ってありますので、先ほど申し上げたとおり、これから劇的に受給者が増えていくとかいうことになりましたときには、また考えていこうかなと思ってあります。現在、ケースワーカーの数ですけれども、３８人です。","voiceIndex":95,"id":"exchange-041"},{"speaker":"山内委員","kind":"質問","question":"国の基準では、ケースワーカーが１人につき８０世帯が基準というんですか、その世帯を見ていくというような数を打ち出しておりますけれども、今、ケースワーカーが３８人いらっしゃるということで、この８０人に対しての品川の数というものはいかがなんでしょう。例えば８０人以上見ているのか、それとも８０人という基準よりも少ないのか、その辺を教えてください。","respondent":"志村生活福祉課長","answer":"ですから、この単純な公式を用いますと、２人足りないじゃないかというふうなことになるかと思いますけれども、ただ私どもから申し上げますと、先ほど申し上げたとおり、いろいろケースワーク業務を補完する者、この下にも書いてありますけれども、嘱託相談員。","voiceIndex":97,"id":"exchange-042"},{"speaker":"山内委員","kind":"意見","question":"後々起こってからでは遅いというようなことで、その辺のチェック体制というものをもう１回強化をしていく必要性があると思うんですが、最後にそこをどうしていくかということをもう１度お願いします。","respondent":"志村生活福祉課長","answer":"生活保護の執行に当たりましては、いろいろなところから私ども挙証資料といいますか、提出をいただいてあります。この調査員５人を含めまして、その中身をこれからもその精度を高めていこうというふうには考えてあります。","voiceIndex":99,"id":"exchange-043"},{"speaker":"高橋委員","kind":"質問・要望","question":"１１６ページのほうなんですが、国等による障害者就労施設からの物品等の調達、その推進に関する法令、その形で地方自治法施行令等が改正されたのですが、その改正された内容を簡単にお答えいただきたいのと、それに伴って品川区は障害者施設等の業務の発注について、これまで配慮をされてきたと思うんですが、どのような配慮をされてきたか、お答えください。","respondent":"高橋障害者福祉課長、阿部経理課長","answer":"通知が出たことは承知しております。それで具体的には障害者施策の中で、すぐ反映しているかということになりますと、今のところ反映しておりません。もう１点加えますと、役務の提供につきましても、そういう区内の社会福祉法人、あるいは社会福祉協議会等と随意契約を行って、委託契約をしたという例があります。","voiceIndex":102,"id":"exchange-044"},{"speaker":"高橋委員","kind":"質問","question":"特に今年の３月に役務の提供等も随意契約でできるということになりまして、今お話があったように、これまで取り組んでこられたと思うんですが、今後、さらにその随意契約等で、障害者の方々の就労支援とのかかわりもあると思うんですが、どのようにお考えでしょうか。","respondent":"阿部経理課長","answer":"今回はそのほかに加えまして、例えば障害者支援施設とか、あるいは小規模作業所、そういうところとの随意契約ができるようになったです。それにつきましては、具体的にどのような団体があって、どのような契約ができるのか、それは今後の検討課題だと考えています。","voiceIndex":105,"id":"exchange-045"},{"speaker":"高橋委員","kind":"質問・要望","question":"品川区は今お話があったんですが、就労支援施設に関してのお話なんですが、これまでクリーニングとか公園の公共施設等の形で、今お話があったように社会福祉法人との関係で就労支援をしてきたと思うんですが、特にいろいろな経済状況もあるのかもしれませんが、クリーニングに関する事業に関して、現在の状況と、今後の見通しをご説明いただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"ここにつきましては、保育園のシーツを中心に行っているものです。ただ、ここのところについてもシーツのクリーニングだけじゃなくて、いろいろな形で民間のところの営業活動も含めまして、今後やっていかなければならないのかなと考えています。","voiceIndex":109,"id":"exchange-046"},{"speaker":"高橋委員","kind":"質問・要望","question":"今の現状でのお考えをお話しください。","respondent":"高橋障害者福祉課長","answer":"就労支援ネットワークということで、今年の４月から各作業所の方に集まっていただきまして、品川名産を中心に、具体的にどういうことだったらワークシェアリングできるのかということで考えて、検討を進めさせていただいています。","voiceIndex":111,"id":"exchange-047"},{"speaker":"高橋委員","kind":"質問・要望","question":"１２３ページのぷりすくーる西五反田のほうなんですが、全国的にも大きな注目を集めたぷりすくーる西五反田なんですが、５年経ったわけですが、この間の幼児教育に関する、あるいは施設に関する運営について実績や、幼児教育についての経営、姿勢や理念についてどうお考えか、ご説明いただきたいと思います。","respondent":"小林保育課長","answer":"この間、幼児教育の視点をより強めて、個々の伝統的な取り組みですとか、それからリズム、あるいは体操というような観点も随時取り組みながら、子どもに新しい感覚や体験をする場を与えるという意味で、乳幼児教育の実践が十分図られてきたというふうに評価しております。","voiceIndex":113,"id":"exchange-048"},{"speaker":"高橋委員","kind":"意見","question":"園児１人当たりの経費を出しますと、区立の保育園ですと２３３万円、区内私立保育園だと２１１万円、ぷりすくーる西五反田だと１０８万円ということで、経費の面でこのような結果が出ているんですが、このような違いと、これをどう評価されているか、お願いいたします。","respondent":"小林保育課長","answer":"いい保育をしていただいて、現実ぷりすくーる西五反田の場合はそういった意味で、単純に比べても２,０００万円弱の相差が今、まだ公立保育園とあることは事実です。","voiceIndex":115,"id":"exchange-049"},{"speaker":"高橋委員","kind":"確認","question":"その差が出ても、同じサービス、もしくは先ほど評価していただいたようなサービスがこのぷりすくーる西五反田で出されているということをこの５年間の中で、結果として運営がされたということをちょっと確認させていただいたので終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-050"},{"speaker":"金野委員","kind":"提案","question":"園と保護者との連携のとり方ですけれども、個人情報保護条例ということもある中で、名簿の管理などはどのようになっていますでしょうか。それから、すくすく赤ちゃん訪問事業のほうですが、先ほども別の委員からも質問があり、一定の効果と成果がありましたという報告も受けましたが、ちょっと重なる点もありますけれども、提案も含めてお聞きしたいと思います。ご所見をお伺いいたします。","respondent":"小林保育課長、諸岡児童課長、矢野品川区保健センター保健サービス課長","answer":"そしてまた、親御さん自体が子育てを学ぶ場の助けとなるようにという目的に照らして適切に対応してまいりたいと思います。その中でどうしてもこの問題が発生したり、支援が必要になったということであれば。すくすく赤ちゃん訪問事業に関しましては、児童課と連携して、要支援家庭については保健師のほうも必要とされる家庭については４カ月以降。","voiceIndex":119,"id":"exchange-051"},{"speaker":"石田（慎）委員","kind":"提案","question":"それと、午前中の答弁の中に、地域の子育てにつながるようにというようなお答えがあったと思うんですが、この空き店舗活用型という中で、空き店舗以外にも考えているということで、これはちょっと提案になるんですが、地域センターとか、この総合庁舎を含めた区有施設において空き部屋等の活用を考えていただければと思うのですが、その辺の考えはどうなのかということ、この２点をまずお伺いします。","respondent":"小林保育課長","answer":"今後の可能性なんですけれども、基本的には必ずしも長時間の施設サービスだけではなくて、まちの中で必要な保育を、できればまちの人たちと一緒に提供できるという意味での地域の子育てという形の可能性を今後とも考えてまいりたいと考えていますので。","voiceIndex":124,"id":"exchange-052"},{"speaker":"石田（慎）委員","kind":"質問","question":"続きまして、後期高齢者医療制度準備経費、これはさまざまな賛否があると思うんですが、あくまでも今回平成１９年度の決算ということで、準備経費ということに関して質問をします。初めに制度改正を認知してもらうために、どのような周知を徹底されてきたのでしょうか。周知のほかにどのような準備をして、この制度のスタート時の体制を整えていったのか、まずこの２点をお聞かせください。","respondent":"永尾高齢事業課長","answer":"主にシステムの開発経費と機器のほうの整備になってあります。それから、区の組織の体制ですけれども、数カ月は老人医療のほうと並行してまいるということで、両方に対応できるように組織のほうも対応してきました。","voiceIndex":126,"id":"exchange-053"},{"speaker":"石田（慎）委員","kind":"意見","question":"そういったさまざまな準備をされてきた中で、新聞、テレビ等でさまざまな問題が出てきてしまった中で、品川区では実際どのような状況だったのか。主にスタートのときはどのようなものだったのかというのをお知らせください。","respondent":"永尾高齢事業課長","answer":"その後、ほかの区においては、４月から年金からの徴収や普通徴収等始まりましたけれども、品川区におきましては、周知を十分に行いたいという理由から、７月から開始いたしました。","voiceIndex":128,"id":"exchange-054"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"この後期高齢者医療制度は今後、廃止や見直し等が予想されている中で、もう既にこの医療制度がスタートしてしまっている中で、区民の方に不利じゃないようにというのがやっぱり一番ですので、その点はぜひしっかりとした準備があるというのをご答弁いただいているので、ぜひ今後も努めていただきたいと思いますが、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-055"},{"speaker":"本多委員","kind":"質問","question":"１１３ページの社会福祉費、１２０ページの児童福祉費のあたりで質問いたします。軽度発達障害に関連しまして、発達障害者支援法などの絡みで、全国的にも取り組みが進んできているようですけれども、まず品川区としてのその点についての取り組みについてお聞かせください。","respondent":"高橋障害者福祉課長","answer":"しかし品川区におきましては昨年から発達障害児に対応するものとして、品川児童学園の２階にコンパスということで、発達障害児に対する療育を行いたいということで、児童デイサービスを行っているものです。","voiceIndex":132,"id":"exchange-056"},{"speaker":"本多委員","kind":"質問・要望","question":"区の取り組み、現状はわかりました。それで保健所とか教育委員会等との連携についてお聞かせいただきたいんですが、一般的に幼児ですと保育園ですとか、幼稚園ですとか、そういった環境において、区の取り組みは今お話しいただいたんですけれども、それに絡むいろいろなケースに当たりまして、どのような連携がとれているのか、教えてください。","respondent":"高橋障害者福祉課長","answer":"その後、委員おっしゃるとおり保健所、保健センターとの連携、また小学校に上がりますと教育委員会との連携というのが重要になりますので、その辺については今、ネットワークというか、連携をどうやって進めていくのかということで検討している段階です。","voiceIndex":134,"id":"exchange-057"},{"speaker":"本多委員","kind":"質問・要望","question":"成長とともに、そういう障害が除かれていくような方法というか、取り組みとかもあわせて必要だと思うんですけれども、それまでの間、あるいはそういった方向に向かうまでの取り組みとして、現場、例えば幼稚園ですとか保育園ですとか、時には学校ですとか、そういう親の思いが、例えば認めづらいケースもあれば、逆に親から情報を教えてくださいというような相談とかもあると思うんですけれども。","respondent":"高橋障害者福祉課長","answer":"それと、なかなかご相談に応じられない保護者の方につきましては、やはりきめ細かな相談ということで、もし保育園、幼稚園のほうで対応ができなければ、例えば保健所のほうでご相談したらどうですかとか、私どもの相談機関を紹介とかということで。","voiceIndex":136,"id":"exchange-058"},{"speaker":"本多委員","kind":"意見","question":"それで、親御さんへの情報ですとか、助言といいますか、そういったものとあわせて、現場の声、相談を受けているという、区でヒアリングをされているということなんですけれども、相談が来たケースを対応しているのか、それともかなりヒアリング的にいろいろな状況を把握するような取り組みなのか、その辺だけもう１度お願いしたいと思います。","respondent":"高橋障害者福祉課長","answer":"現状では困った状況について、どうしたらいいのかというご相談から始まっております。ただ今後、保健所、保健センター、もしくは教育委員会、それと保育園、幼稚園と連携する中で、今後については定期的な巡回とかいろいろな形での連携が進んでいくかと思います。","voiceIndex":138,"id":"exchange-059"},{"speaker":"本多委員","kind":"質問・要望","question":"連携を強めて、いろいろなその発達障害児、もしくは発達障害児の疑いのあるケースに携わる支援の方、家族の方、現場のスタッフの方にとってよりよい方法を考えていただきたいと思うんですが、仮に第三者の方がそういういろいろな難しい状況において、取り扱いを本当に慎重にしなければいけないケースなんかで、なかなか判定が難しい場合なんですけれども、第三者が判定をする仕組みづくりですとか。","respondent":"高橋障害者福祉課長","answer":"ただ、医療の判断をしたから、その子の対応がそれで確定するということではございませんので、それを中心に、その子のいろいろなことを支援していかなくてはならないかと考えています。","voiceIndex":140,"id":"exchange-060"},{"speaker":"市川委員","kind":"質問・要望","question":"シルバー人材センターについてですけれども、総務費の審査のところで、答弁の中で、奨学金貸付の返還金の催促をシルバー人材センターへ委託されているということを聞いたんですけれども、個人情報を扱うと思うんですけれども、この個人情報の保護はどのように徹底されているのか、確認をさせていただきたい。これが１点。この２点お願いします。","respondent":"永尾高齢事業課長、冨岡高齢福祉課長","answer":"シルバー人材センターの件で、奨学金の貸付資金の徴収についてですけれども、区のほうからシルバー人材センターに委託契約書というのを出す際に、個人情報についての規定もその中に盛り込んです。介護保険事業の中で、特定高齢者、この方たちはそのまま介護予防に心がけていただかないと、要支援、要介護の状態になるという方ですけれども、平成１９年の段階では、４２８人が特定高齢者と考えております。","voiceIndex":143,"id":"exchange-061"},{"speaker":"市川委員","kind":"質問・要望","question":"介護保険の特定高齢者のところの質問については、特定高齢者の人数、特定された方の人数と、それからサービスの内容と、その利用人数について伺ったので、再度答弁お願いします。","respondent":"冨岡高齢福祉課長","answer":"実績につきましては、マシンでトレーニングが３１４人、身近でトレーニングが３７１人、予防ミニデイが１６３人、水中トレーニングが２０人です。","voiceIndex":146,"id":"exchange-062"},{"speaker":"市川委員","kind":"質問","question":"私はこの介護予防というところでは、とても利用が低いんじゃないかと思うんです。それで、今年度数字が見えていると思いますけれども、そうした介護予防を３年経過した中で、区は予防が必要な人に介護予防事業の効果が上がっているのかどうかと思うんですけれども、費用対効果というところについてもどのように感じているのか、感想をお聞きします。","respondent":"冨岡高齢福祉課長","answer":"ご指摘のように特定高齢者につきましては、なかなかご本人が特定高齢者だと私どもは考えても、そのご自分たちの自覚といいますかがつながっていかないという、非常に難しい部分がありまして。","voiceIndex":148,"id":"exchange-063"},{"speaker":"市川委員","kind":"質問","question":"それで特定高齢者、一般高齢者に対しても保険制度によるサービスがなされることになりました。期間を定めた成果主義の予防介護サービスには多くの課題があると感じているんですけれども、質問なんですけれども、予防介護に対する区民ニーズと、区が展開しているサービスがうまく合致していないように思えるんですけれども、現場の声、当事者の意見をどのように把握しているのか、お尋ねします。","respondent":"冨岡高齢福祉課長","answer":"個々にきめ細かく対応させていただきたいと考えています。","voiceIndex":150,"id":"exchange-064"},{"speaker":"市川委員","kind":"質問","question":"国のほうでは来年の４月に介護保険制度の介護報酬の改定のほうが予定されていまして、何らかの形での制度改正というところにも及ぶのかなと思っているんですけれども、介護予防サービスの見直しというのは、今後考えていかれるのか。ニーズの多い家事援助サービスについての対策を何か考えていらっしゃるのか、国の制度ではありますけれども、制度の実施主体としての区の見解をお聞きします。","respondent":"冨岡高齢福祉課長","answer":"それから家事援助ということも、やはり保険のこの制度といいますのは、あくまでも自立の支援の制度ということがあるかと思います。それを全体で支えていくという制度でありまして、その立場に立ちまして、保険者としても対応してまいりたいと思っているところです。","voiceIndex":152,"id":"exchange-065"},{"speaker":"市川委員","kind":"質問・要望","question":"ちょっとした手助けがあれば自宅で暮らしていけるのに、そのちょっとした援助も受けられなくなってしまったというような声は、本当にたくさん届いておりますので、そういった意見も十分踏まえたサービスの内容にしていただけたらというふうに要望をいたします。それから１１７ページの障害児放課後生活サポート事業について、内容を伺います。それと、内訳があるとしましたら、内訳についてもお答えください。","respondent":"高橋障害者福祉課長","answer":"やんちゃっこクラブにつきましては、昨年の７月から知的障害児の療育の児童デイサービスに移るということで、その期間の３カ月分を委託料として出しているものです。","voiceIndex":154,"id":"exchange-066"},{"speaker":"市川委員","kind":"質問","question":"にじのひろばの２５５万円というお答えだったんですけれども、にじのひろばの実績というのはどう推移しているのか、それからもう１つの質問は、にじのひろばの事業委託費２５５万円を算定した根拠ということについてお尋ねします。","respondent":"高橋障害者福祉課長","answer":"平成１７年９月に開設したもので、平成１７年につきましては、延べ人数で４６４人、平成１８年につきましては１,２６２人、それから平成１９年につきましては２,２７３人です。内訳につきましては、東京都からの補助金をそのまま補助として、事業補助をしているものです。","voiceIndex":156,"id":"exchange-067"},{"speaker":"市川委員","kind":"質問","question":"それで、にじのひろばは障害児放課後生活サポートとして、知的障害者とそれから身体障害者ともに受け入れているわけですけれども、安全には細心の注意を払っていると思いますので、当然、これだけの人数を預かるということは、人件費もかなりかかるだろう、多分、かなり厳しい状況なんじゃないだろうかと想像するんですけれども。","respondent":"高橋障害者福祉課長","answer":"それで、この安全をどう保っているのかということでは、十分事業運営の中でご相談があれば、いろいろな形で支援している状況です。","voiceIndex":158,"id":"exchange-068"},{"speaker":"市川委員","kind":"質問","question":"区としてのこういう場をさらにつくるとか、広げるとか、そういったところで何か対策があるのかどうか、伺います。","respondent":"高橋障害者福祉課長","answer":"昨年、やんちゃっこクラブが６月で終了し、その後のところでは、今のにじのひろばにお願いしてきたもので、かなり数量的には増えているということが考えられましたので、今年の４月から障害児ナイスデイサポートとしまして。","voiceIndex":160,"id":"exchange-069"},{"speaker":"市川委員","kind":"質問・要望","question":"福栄会のナイスデイサポート事業があるというようなお答えだったんですけれども、現在、福栄会は知的障害のお子さんだけの受け入れで、肢体不自由児については受け入れていないというふうにお聞きしたんですけれども、そこの確認をさせていただきたいということと、それからぜひ品川区に場が１カ所だけでなく、複数あったほうが障害児の放課後のサポートということについては好ましいわけですので。","respondent":"高橋障害者福祉課長","answer":"今後については、そのいろいろな状況を踏まえまして、検討していく必要があるかと考えています。それと、にじのひろばの予算額を上げていくというご要望ですが、現状を踏まえ、また今後の状況もＮＰＯ法人と協議しながら、その辺については検討していくです。","voiceIndex":162,"id":"exchange-070"},{"speaker":"市川委員","kind":"質問・要望","question":"ぜひ検討していただきたいということと、それと福栄会のナイスデイサポート事業は、今は知的だけですけれども、今後は肢体不自由児も受け入れていくという確認でよろしいんでしょうか。そこの確認を１つお願いします。それと、障害者自立支援法もできて、従前の障害児タイムケア事業は、日中一時支援事業として、移行できることになっていると思います。","respondent":"高橋障害者福祉課長","answer":"今後につきましては、生活介護ということで、もしかしたら障害者自立支援法の中のところで１５歳以上については対応可能かなというところもありますので、新体系への移行ということも踏まえまして、その後検討するというような状況です。","voiceIndex":164,"id":"exchange-071"},{"speaker":"市川委員","kind":"質問・要望","question":"本当に肢体不自由児の放課後対策というところでは、お母さんたちが、このにじのひろばだけが頼りなんだということで、非常に切実な思いを持って場所をどうにか確保してほしいという要望を聞いておりますので、ぜひ前向きに検討していただくことを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-072"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは１１３ページの社会福祉総務費の中の民生委員経費、そして１１８ページの障害者福祉費の中の社会参加への支援の２つについて質問させていただきたいと思います。実際、民生委員経費を見て、約４,７９０万円という金額が計上されておりますが、この内訳、特にこの中に委員協議会９５回と書いてあるんですが、この内訳も教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"主なものといたしまして、今年につきましては、民生委員は高齢者相談員も一緒に兼ねてやっていただいておりますが、３年に一度の名簿づくりということがございまして、そこの部分の消耗品費等々もかかっているという部分があります。","voiceIndex":168,"id":"exchange-073"},{"speaker":"山元委員","kind":"質問・要望","question":"先ほど定員が２９６人と聞いているんですが、実際、人数的には何人いらっしゃって、また欠員がいるかどうか、教えていただきたいんです。","respondent":"冨岡高齢福祉課長","answer":"民生委員ですが、これは１０月末の人員ですけれども、定員が２９６人、現員が２８３人ですので、１３人ほど欠員があるです。","voiceIndex":170,"id":"exchange-074"},{"speaker":"山元委員","kind":"質問・要望","question":"実際、区から推薦されて、国に提出され、認可というか認定というか、その委員になるには日にちがどのぐらいかかるのかということと、この民生委員というのは定年制があるのかどうか、また現実に今、２８３人、民生委員の方がいらっしゃるということなんですが、大体平均年齢は何歳ぐらいになるか、もしおわかりになれば教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"平均年齢につきましては、ちょっと細かいものはありませんけれども、大体６４歳ぐらいです。これは民生委員で主任児童委員、児童を中心にされる方も各地区２人で２６人おいでになりますが、その方々は５８歳ぐらいです。","voiceIndex":172,"id":"exchange-075"},{"speaker":"山元委員","kind":"質問・要望","question":"そうした場合に、もっと幅を広げて、地元に住んでいないといけないとか、そういうことではなく、例えば地域で貢献してくださっている会社の方とか、そういう何か幅を広げると、またちょっと年齢も下がったり、また違うような角度が出てくるのではないかなと思うんですが、この現状、またどんどん平均年齢が上がってしまう町会とか民生委員に関しての区としての思いはいかがでしょうか。","respondent":"冨岡高齢福祉課長","answer":"民生委員がおいでにならない地区につきましては、ほかの民生委員、あるいは会長ということで、協議会全体で支えていただいているといういきさつがありますので、おいでにならなくても、それなりの対応は当然するです。","voiceIndex":174,"id":"exchange-076"},{"speaker":"山元委員","kind":"質問・要望","question":"これは要望です。次に行かせていただきます。１１８ページの社会参加への支援についてお聞きしたいと思います。この中に社会参加への支援ということで、リフト・寝台付福祉タクシーについて、お聞きさせていただきたいと思います。この福祉タクシーですけれども、３台あるとお聞きいたしましたが、この３台の流れというか、稼動といいますか、どんなふうになっているのか、教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"その前の平成１９年３月までは、リフト・寝台付福祉タクシーが２台、それからリフト付福祉タクシーということで、飛鳥交通が３台ということで、全部で５台で運営しておりましたが、３月末に急に飛鳥交通が撤退するということでしたので。","voiceIndex":176,"id":"exchange-077"},{"speaker":"山元委員","kind":"質問・要望","question":"去年は実は利用件数が２,３６８件あったのに対して、平成１９年度に関して、利用件数が１,７５９件になっております。この差はどういうことなのかということと、今回のこの平成１９年度の１,７５９件の利用件数に対して、交付人数というんでしょうか、それを教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"交付件数ということでは、タクシー券のところの交付件数とは違いまして、これは利用件数でして、１日なり、通院なり、社会参加ということで、いろいろなところに出かけるときに利用した件数です。","voiceIndex":178,"id":"exchange-078"},{"speaker":"山元委員","kind":"質問","question":"実はこのリフトの中の内容に、運賃とか迎えるときの料金とかあって、実は待ち時間料金も自己負担というふうに書いてあるんですね。この待ち時間料金もすべて自己負担になるというのは、やはり利用者にとってはとても負担がかかるのですが、その辺、タクシー会社との間に、例えば空き時間を上手に使えるような、また診療が終わったら連絡するとか、そういう仕組みづくりを何か考えたことはありますでしょうか。","respondent":"高橋障害者福祉課長","answer":"ですから、今回のタクシー料金が上がった段階でのお迎えのところについては、乗ったときからということの変更をさせていただいていますので、できる限り、待たなければ新しく行って、ご本人が乗った段階からのメーターという変更をさせていただいていますので。","voiceIndex":180,"id":"exchange-079"},{"speaker":"山元委員","kind":"質問","question":"いずれにしましても、体が不自由なために、動きがとれないということがあると思いますので、より手厚い福祉をお願いしたいと思います。今、３台稼動しているということなんですが、区としては、この台数を増やす予定というのはありますでしょうか。","respondent":"高橋障害者福祉課長","answer":"現在の時点では考えておりませんが、ただ現在、品川区社会福祉協議会のところで移送サービスということで、２台から４台ということで、４月から台数が増えたところですので、車いすの方についてはそちらをご利用ということでお願いしている部分もあります。","voiceIndex":182,"id":"exchange-080"},{"speaker":"山元委員","kind":"質問・要望","question":"その辺、このタクシー券の使い方といいますか、その辺をちょっと教えていただきたいと同時に、何か一覧表というか、品川は睦交通以外にこういうところが使えるよみたいな一覧表みたいなものは配布されていらっしゃるんでしょうか。","respondent":"高橋障害者福祉課長","answer":"タクシー券の利用につきましては、平成１９年度で８１社委託契約しておりますので、その一覧表につきましては、タクシー券の裏側に書いてありますので、それでご利用いただければと思っています。","voiceIndex":184,"id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一般質問でも取り上げたんですけれども、訪問介護サービスの抑制がされて、本当に高齢者につらい思いをさせていますけれども、まずこの間どういうふうに変化してきたのかということを数字で示していただきたいんですが、平成１７年度と比較して、平成１９年度がどれくらい減っているのか、訪問介護サービスを受けていた人数、時間数、給付額、その３点について減らされた数字について。","respondent":"冨岡高齢福祉課長","answer":"ただ、いろいろ制度的には確立されており、その中で区は給付に努めているわけですけれども、中にはいろいろ問題が出ている部分もありますので、その中につきまして、一定の対応が必要とお答えしたところです。","voiceIndex":187,"id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"現場のケアマネージャーからも、ぜひその高齢者に合わせた必要なケアプランが組めるようにしてほしいということをたくさんの方から在宅介護支援センターのケアマネージャーの方も含めて、お聞きしていますので、既に渋谷区、港区、それから千代田区、墨田区、こういうところが対策をとっていますので、こういうところの対策も参考にしながら。","respondent":"木下福祉高齢事業部長","answer":"そういう枠組みを前提にしながら、現場の中でいろいろ現在、対応が非常に難しくなっている部分というのがいろいろな形で起こっておりますので、その部分についてどう対応するかということについてなんですけれども、１つの方法としては。","voiceIndex":189,"id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もともと使えていたわけですから。そういう方向で私は介護保険も改善していってほしいと思います。保険料を払うだけだと。そんなにどんどん使わせるわけにはいかないんですよということで、抑制してきているわけですから、そういうところで、保険料で１００％賄う市町村特別給付で締め出されたサービスを賄うということはどう考えてもおかしい、最大の矛盾ではないかと思うんですけど、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"これは法制度が予定しているのは、特別給付でやりなさいということですから、法制度上そうだということが１つあります。","voiceIndex":191,"id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では法制度ではそうなっているということですが、ほかのところはそうじゃなくて、一般財源でやっているわけですから、一般財源でできないわけではないわけですから、そういうところでぜひ一般財源でやっていただきたいと、強く要望しておきます。これが第１点です。それともう１つは、所得の低い人への対策をとっていただきたいと思いますけれども、いかがでしょうか。","respondent":"冨岡高齢福祉課長","answer":"介護保険料につきましては、第四期の事業計画の中で、３年間の給付の見込みを立てながら今検討しています。当然、多段階化につきましても検討しているという状況です。それから、今おっしゃいました経過措置につきましても、多段階化の中で検討しているという形でお答えをします。","voiceIndex":193,"id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この部分でも、渋谷区が大変きめ細やかな対策をとっています。２５０万円以下はすべて品川区よりもかなり低い金額にしています。区民の実態が、年金が増税されて、すごい負担増になっています。ぜひ保険料を引き下げて、特に低所得者への対策をお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-086"},{"speaker":"大沢委員","kind":"質問・要望","question":"１１５ページの認知症高齢者の支援とケアの充実と、１１６ページ、高齢者世帯の安否確認事業です。安否確認事業から先に質問します。この安否確認事業においては、４つ事業がありますけれども、まず緊急通報システム、これはわかるんですが、安全確保と福祉電話についてお伺いをします。ここの成果報告書を見ると、５６万３,０００円余ということになっております。","respondent":"冨岡高齢福祉課長","answer":"それから福祉電話につきましては、貸与後の電話使用料助成、回線使用料とか、月額６００円までの通話料を区が負担していたわけですが、一応この部分を廃止いたしまして、減の状況になっているというような状況です。","voiceIndex":197,"id":"exchange-087"},{"speaker":"大沢委員","kind":"質問","question":"助成制度がなくなったので、借りる人が少なくなってきたということというふうにお伺いさせていただきましたけれども、必要性を考えてなくしたと思うんですけれども、減るということはサービスを見直す上で、やはりもう１回考えてみないといけない部分があると思うんですけれども、そこのところをどういうふうにお考えになりますでしょうか。","respondent":"冨岡高齢福祉課長","answer":"これは、新規の申請は受けておりませんけれども、継続をして実施しています。","voiceIndex":199,"id":"exchange-088"},{"speaker":"大沢委員","kind":"質問","question":"ちょっとわからないのですが、新規は受け付けていないけど、継続はしているということで、これは、どういうことなのか、もう１回教えてください。","respondent":"冨岡高齢福祉課長","answer":"この福祉電話の部分ですが、例えば民生委員の高齢者の方への訪問というものがあったり、例えばもう一方で携帯電話、要するに全然無料で買える携帯電話といったものの普及がございまして、そうしたトータルの中で判断をさせていただいて、こういう経過になったという状況です。","voiceIndex":201,"id":"exchange-089"},{"speaker":"大沢委員","kind":"意見","question":"携帯電話の普及、これはまさに普及によって減ってくると、私も思いましたけれども、ちなみに福祉電話というのは固定電話で行われているわけですね。そうなると、やはり携帯電話の普及で、今どきという表現が妥当かどうかわからないんですけれども、移動電話のこれだけの普及を考えると、固定電話の必要性というのは、私はだんだん減ってくると思うんですけれども、そこのところ、どうお考えになりますか。","respondent":"冨岡高齢福祉課長","answer":"おっしゃるように、意味についても問わなきゃいけない状況がありますが、ただ、今、これを利用されている方は生活保護を受給されている方がほとんどの状況なものですから、その部分については、今のをこのまま継続してまいりたいと考えているところです。","voiceIndex":203,"id":"exchange-090"},{"speaker":"大沢委員","kind":"質問","question":"次に行きます。介護です。認知症高齢者の支援とケアの充実ということなんですけれども、この成果報告書の中にケア事業があります。老老介護の場合もありますでしょうし、いろいろな形態があると思いますけど、主たる形態というのは、どのようにお考えですか。","respondent":"冨岡高齢福祉課長","answer":"認知症の方をケアされる方は、最初におっしゃったように高齢者の方もおいでになれば、若い方もおいでになると。家庭の中でのケアということを全体的にとらえております。","voiceIndex":205,"id":"exchange-091"},{"speaker":"大沢委員","kind":"意見","question":"それと晩婚化によって息子さんが年老いたお父さん、お母さんなりを介護をするのも多々見受けられます。その介護するためには生活費も必要なわけであって、その両親、またはお母さん、お父さん、どちらかの年金によって食べつなぎながら、両親の介護をする、この現状をどのようにお考えになりますか。","respondent":"冨岡高齢福祉課長","answer":"ただ、仕事のことはともかくとしましても、認知症の方をどのようにケアしていったらいいかというのは、まさに在宅介護支援センターでいろいろご相談をいただいて、それから家族のことも踏まえて、どういう形で社会的支援を提供できるのかということがまず一番だと思いますので。","voiceIndex":207,"id":"exchange-092"},{"speaker":"大沢委員","kind":"質問・要望","question":"よって新聞の記事に載っているように、親に手をかけてしまったり、そういう事件が起こるわけですので、そこのところは相談に乗る方も十分斟酌をしていただきながら、対応に当たっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-093"},{"speaker":"阿部委員","kind":"確認","question":"ちょっと何だか、傍目に見ると、非効率といいますか、滑稽といっては何ですけれども、その辺、もうちょっとうまく何か連携をとれたほうが、逆に行政の効率としてもよいのではないかと思うんですけれども、こういった実態が制度上あるのかどうかということと、そういったことがあるのであれば、どのようにお考えかということを１つお伺いしたいと思います。実際の訪問できた数というのを教えてください。","respondent":"高橋障害者福祉課長、永尾高齢事業課長、小林保育課長、諸岡児童課長","answer":"それと、障害児の移動支援ですが、私どもでは一応１８歳以上ということでお願いしていますので、現段階ではございません。男女比の件につきまして、こちらも実はきちんとしたカウントを集計していないんですけれども、おおよそ現場のほうを聞きますと。かなり老朽化している認識がありますが、現段階では、建て替えの計画はございません。は当面受付時間の短縮も含めて、気遣いと、それから現状あるスペースの活用で対応し、抜本的にはまた今後の課題とします。","voiceIndex":211,"id":"exchange-094"},{"speaker":"阿部委員","kind":"質問","question":"そういう事例を聞いたから伺ったもので、そういった場合は、どこかで調整をしなければいけないと思うんですけど、それはどうしたらいいのか、どこに言えばいいのかというのを教えてください。もし類似の事業があれば教えてください。それから出会いの湯なんですけれども、実際には４,０００人程度であろうと。保健センターのほうは数字を伺っていなかったかなと思うんですが、いかがでしょうか。","respondent":"冨岡高齢福祉課長、矢野品川区保健センター保健サービス課長、高橋障害者福祉課長、永尾高齢事業課長","answer":"そのときは、私どもですと、高齢者支援係でも結構ですし、相談係ということ。いずれにしろ、申請書が出されたケースについては、電話での育児相談等を含め対応しております。それと、移動支援のところで、現在は実績がございませんが、今まで２人の方について。これについては、東京都の補助金が２分の１出ておりますので、補助金に頼るという意味ではないんですけれども。","voiceIndex":217,"id":"exchange-095"},{"speaker":"阿部委員","kind":"意見","question":"それぞれいろいろ言いたいことがあるんですけど、１つだけ、ガイドヘルプなんですけれども、品川区では子どものガイドヘルプは原則親がついていけというような対応がなされると聞いております。先ほど福祉高齢事業部長からすばらしいお話がありまして、親子の依存ではなくて、ちゃんと地域の中で自立ということを目指していくべきだというお話でした。それがぜひ必要であると考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":222,"id":"exchange-096"},{"speaker":"武内委員","kind":"質問","question":"私は１１３ページの原小学校跡西大井シルバーセンター施設整備助成と、１１４ページの品川区社会福祉協議会に関連してお伺いします。社会福祉協議会のほうからお伺いしますが、今、社会福祉協議会の事業で、生活福祉資金の貸付を行っていただいておりますが、この平成１９年度で結構ですので、大体の年間の申し込み数と、そのうちご利用いただいた数がもしわかれば教えてください。","respondent":"冨岡高齢福祉課長","answer":"金額的には１,５００万円余です。","voiceIndex":224,"id":"exchange-097"},{"speaker":"武内委員","kind":"質問","question":"そうすると、更生資金ですとか福祉資金。その中で、直近のケースで言えば、転宅資金のご相談なんかもあったわけですけれども、大体相談して、品川区のほうでいろいろ聞き取りをしていただいて、書類を東京都に上げて、実際に利用したいという方にお金が行くのにどれくらいかかるんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"受付をして、当然、書類を東京都社会福祉協議会に送るわけですが、東京都社会福祉協議会は都内全域を扱っておりまして、大体月に２回審査を行っているという状況がございまして、そういうのを加味しますと、大体１カ月ちょっとぐらいかかるかなという状況です。","voiceIndex":226,"id":"exchange-098"},{"speaker":"武内委員","kind":"質問","question":"そういうときに、例えば実際東京都で審査されるわけですから、品川区はなかなかどこまでスピーディーにできるかというのは難しいところだとは思うんですが、例えば相談を受けた内容によって、そこで、１カ月ぐらいだったら何とか工面できますという方はいいんですが、にっちもさっちもいかないと、何とかしてもらいたいという方について、例えば書類をあげて、その中で区のほうから都のほうにこういう事情で。","respondent":"冨岡高齢福祉課長","answer":"やはりそれぞれの事情がおありになってお借りになるということで、一応返済が可能な方ということで、生活費に充てるという理由ではちょっとなかなか難しいというのも聞いておりますので、そういう事情がありますけれども。","voiceIndex":228,"id":"exchange-099"},{"speaker":"武内委員","kind":"質問・要望","question":"恐らく、いや、１カ月かかっちゃいますよとか、ちょっと厳しいですよと言うのかどうかわかりませんけど、言われて、「じゃ、いいです」となっている場合が多いんじゃないかなと。私が年間で五、六人の方からご相談いただくので、もっとたくさん大変で、こういうのを要望している方もいると考えていますので、その辺をぜひ社会福祉協議会の方にもお伝えいただきたいと思うんですが、答弁をお願いします。","respondent":"冨岡高齢福祉課長","answer":"今の委員のお話の内容につきましては、もう１度、私のほうでも社会福祉協議会のほうに伝えてまいりたいと考えています。","voiceIndex":230,"id":"exchange-100"},{"speaker":"武内委員","kind":"質問","question":"よろしくお願いします。時間がないんですけど、原小学校跡の西大井シルバーセンターの件ですが、端的にお聞きしたいのはこの跡地の件です。施設も非常に古いという中で、今どのように検討されているか、来年４月にはもうシルバーセンターは移りますので、その跡地について、今どのように検討されているか、教えてください。","respondent":"久保田行財政改革担当課長","answer":"その後の跡地活用につきましては、ただいま区のほうでも検討しているところでございまして、利用計画案がまとまりましたら、議会のほうにも報告をしていきたいと考えております。","voiceIndex":232,"id":"exchange-101"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひ、場所的にはちょっと立地は悪いんでしょうけれども、有効活用していただきたいというのと、これからシルバーセンターに限らず、いろいろな学校の跡地等も出てきますので、できるだけ早く間があくことのないように計画を立てていただいて、お示しをいただければと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"それから１１８ページのシルバーセンター運営費についてお聞きします。それで、保育園のほうは１２３ページの保育園ＰＴＡ活動支援の件についてちょっとだけ確認をします。ですから、あくまでも自主的に親同士の中での合意がとれている中でつくっていくのであれば、それはそれでよかろうというような形にしていただけないかなと考えていますので、それに対するご意見をいただきたいと思います。","respondent":"小林保育課長","answer":"ただ、この名簿につきましては、名簿の個人情報の前に、お互いの信頼関係が前提にあるものと考えておりますので、状況に応じて適切に対応してまいりたいと思います。","voiceIndex":237,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、その信頼関係をつくるためのということもあるわけですよね。もちろん、保育園の中で使用の目的とかいろいろありますので、ちょっと別の使用で使われちゃったりすると、それは大きな問題になりますから、管理上の指導のほうについては、ぜひお願いしていただきたいと思いますが、決してつくっちゃだめというようなスタンスではいてほしくないと考えていますので、要望したいと思っています。","respondent":"小林保育課長","answer":"その中で現状もお伝えしているようですし、今後もその連携の強化に努めてまいります。","voiceIndex":239,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"１つでも、すばらしいものが品川区には蓄積がありますので、それを有効活用していってほしいと考えていますので、お願いします。しながわシニアネットとか、あとほっとサロンとか、シルバー関係のいろいろな事業ができていると思うんですが、そもそもシルバーセンターのあり方というんですか、それは今後ちょっと具体的に考えていることがあるのであれば、教えていただきたいと思います。","respondent":"永尾高齢事業課長","answer":"今後のあり方ですけれども、今までの機能を楽しんでいらっしゃる方もたくさんいらっしゃいますので、それも重視をしつつ、ただもう少し地域に開かれた形での事業についても検討していきたいと考えております。","voiceIndex":241,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"介護制度が変わって、予防になってくるわけですよね。そうすると、筋力トレーニングであるとかと、いろいろなものをぽこぽこやっているんですね。しかしながら、全体的に考えたときにどういうふうにやっていくのか。もうちょっとシルバーセンターというものの役割をクローズアップするという形で、重要視してもいいんじゃないかなと、私は思うんですが、いかがでしょうか。","respondent":"永尾高齢事業課長","answer":"それで、今やっている筋力トレーニングだとか、いきいき脳の健康教室とか、そういうものも今はやっているところとやっていないところとありますけれども、今の施設の生かし方も考えながら、もう少し一体的に考えてまいりたいと思います。","voiceIndex":243,"id":"exchange-106"},{"speaker":"松澤委員","kind":"質問","question":"３款民生費１項社会福祉費２目高齢福祉費の中で、成果報告書の１１５ページになります。１点目のシルバーダンスパーティーですけれども、事業内容と、決算特別委員会ですので、どういうお金の使われ方をしているのかについてお伺いしたいと思います。","respondent":"永尾高齢事業課長","answer":"区から出てきたお金と、あとは品川区社会福祉協議会から助成金が４万円出ておりまして、そちらのお金と、あとは品川区社交ダンス連盟からも自主的なお金を出して、その中ですべてをやっているというような状況になっております。","voiceIndex":246,"id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"近年、ダンス熱というのは盛んで、ちょっと話をすると、私、昔やっていたのよとか、話が出るんですけれども、これ、実績が減ってきているんですよね。平成１７年度２７０人、平成１８年度２５０人、平成１９年度２２０人、これ、どうなんでしょう。見た感じ、マンネリ化しているのか。その辺、ただ予算を挙げてやっていますよじゃなくて、理事者としてどのようにとらえているのか、お聞きしたいと思います。","respondent":"永尾高齢事業課長","answer":"残念なことに減っているんですけれども、考えられることといたしましては、グループ参加の方が結構いらっしゃるんですけれども、グループ自体が高齢化していて、とりやめになったりということが大きいので、一度に何十人も減ってしまうというような状況になっております。","voiceIndex":248,"id":"exchange-108"},{"speaker":"松澤委員","kind":"質問・要望","question":"「いや、そんなことないですよ」と、民生委員がそばにいたものですから、民生委員の方も、「いや、社会福祉協議会がその分補っているように聞いているんですが」と、調べていただいたら、本当に実際に５,０００円が３,０００円になっているんですね。減っている傘寿の方が、平成１７年度が２,０７７人から、平成１８年度が２,１８４人、平成１９年度が２,２０２人ですから、そんなに増えていない。","respondent":"永尾高齢事業課長","answer":"そのかわりに、９０歳の方を反対にプラス２,０００円というような形で移行いたしました。それでＰＲですけれども、確かに区報とかそういうのにはちょっと載せてございませんけれども、民生委員協議会のほうで各地区での説明はしております。","voiceIndex":252,"id":"exchange-109"},{"speaker":"松澤委員","kind":"質問・要望","question":"私もその方に頑張れと、長生きすると２,０００円増えますよと。同じですよと言いたいと思います。次は緊急通報システムですけれども、これも昔からある事業、一時もてはやされた事業だと思うんですけど、これが民間型、消防庁型。実際的に適用される高齢者というのは増えているんですけれども、何でこの決算額が減っているのか、これについて詳しくお教えいただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"この事業ですけれども、６５歳以上の方が高齢者の方ということで、緊急事態に対応するために、日常生活で常時注意を要する状態にある方のご希望により取りつけているものです。","voiceIndex":254,"id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"消防庁型のほうはわかりましたけれども、民間型はそうすると協力員も何も要らないということなんですか。改めてどういう形で通報するようになっているのか、お聞きしたいと思います。","respondent":"冨岡高齢福祉課長","answer":"消防庁型の場合は一度協力員に連絡をして、３人お願いをしておりまして、１人おいでにならなければ次の方という形で、ある程度時間がかかるという部分があったです。","voiceIndex":256,"id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"やはり協力される方も消防庁型のほうはなくなったと言いますけれども、人の安否を握っているとなると、夜でもいなくちゃいけないとか、常に頭の中にあったりして、消防庁型が使われなくなったのかなと思いますけれども、安直にそういう冷蔵庫を開け閉めする回数でわかるとか、そういうのもあると聞いているんですけれども、そういうのは当然知っていると思いますけれども。","respondent":"冨岡高齢福祉課長","answer":"例えば品川区で孤立死を防止するネットワークというのに、今年から取り組んで、モデル地区をつくりながら、また品川標準といったものもつくっていくというソフトの面も考えながら、またハードの機器についてもどれがいいのかというのを踏まえながら。","voiceIndex":258,"id":"exchange-112"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはり緊急通報システムというものがあって、この利用者が、高齢者が増えているのに減っているという現状をとらえてみると、やはりもうちょっとＰＲ方、しっかりとしていただきたいということをお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":260,"id":"exchange-113"},{"speaker":"須貝委員","kind":"質問","question":"私は社会福祉全般についてお聞きしたいと思います。介護、医療、障害者、生活保護受給者がたくさん何人かいらっしゃると思いますが、もう少し手助けして、または手を差し伸べないと、生きていけない、生活はできないと思われるような人というのは、この品川区にはいないのでしょうか。実際、介護保険や介護保険の利用実態や、制度改善の課題がマスコミ等全国で叫ばれています。","respondent":"冨岡高齢福祉課長","answer":"ただ、その中で困った人が何人とか、そこまで勘定するなら、まず接近をして、それから地域の在宅介護支援センターと一緒になりながら、それぞれに対応していくという形で、その数字的には、ちょっと全体数はつかんでおりますが、これについてはつかんでおりません。","voiceIndex":262,"id":"exchange-114"},{"speaker":"須貝委員","kind":"質問","question":"お答えは、ほかはないという認識で今、よろしいですか。例えば生活保護、扶助のほうですね。それは全体の物価を見ているわけですから、下がっているものもあるわけですから、でも実際生活をしていく、毎日、日々暮らしていく、その生活必需品は間違いなく上がっているんです。でも、じゃ、その方たちに対して、何らかの追加支援というのはしているのかどうか、ちょっとその辺についてお聞かせください。","respondent":"志村生活福祉課長","answer":"ただいまのご質問、私どもの生活保護の観点からご答弁申し上げますと、ご質問にありましたとおり、生活保護基準自体は平成１６年４月１日に改定がありまして、それ以降、金額的な変更はありません。","voiceIndex":264,"id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"それで日々の食べるものも上がっている。それで足りるでしょうか。これは国の責任であり、そして東京都のほうもやはりそれにもっと資金を、予算を各自治体のほうに、２３区のほうにも私は振り向けなければいけないと思う。お米を支給する。やはり本当に困っている方に品川区も愛の手を私は差し伸べるべきだと思うんですが、その辺の見解を社会福祉の観点から、もしご答弁いただけたらありがたいと思います。","respondent":"木下福祉高齢事業部長","answer":"個人の責任の部分と、市場の中でやる部分と合わせまして、共助の部分、あるいはここの端的なものとして社会福祉協議会の生活福祉資金などの支援もあるわけでありますので、そういうものの諸々の社会資源を、当該の方と適切に相談する中で組み合わせていくというのが。","voiceIndex":266,"id":"exchange-116"},{"speaker":"須貝委員","kind":"質問・要望","question":"まさに財源という問題は出てくると思います。それはわかります。これもよくわかります。そして今、じゃ、まち場を見て、皆さん、仕事はあるんですか。個人で努力できるものならば、やはりそれはできるだけやっていかなきゃいけないと思いますが、私は最後、希望だけ申し上げますが、再度やはり社会福祉の観点から、品川区も、私はより誇れる品川区を目指して頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":268,"id":"exchange-117"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうからは、１１８ページ、ガイドヘルプ事業について、１２１ページ、病児保育についてお伺いいたします。第１点はガイドヘルパーの養成研修と、利用者の地域での自立支援についてお伺いいたします。どういう利用実態があって、利用内容の課題について、何か現場で掌握されていることがあったら、お聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"平成１９年度からの支援のことですが、今まででしたら、必要不可欠な通院のものと、社会参加と一緒にガイドヘルパー事業ということで行ってきたものですが、平成１９年４月からは必要不可欠な通院等の介助につきましては介護給付費で、また社会参加のところについては。","voiceIndex":270,"id":"exchange-118"},{"speaker":"山路委員","kind":"質問・要望","question":"以前は、東京都でヘルパーの養成をやっているときに、大変苦情をいただいたことがあるんです。都バスにヘルパーと一緒に乗って、利用者がバスが動いたので、転んで倒れたとか、階段でヘルパーとの間隔があいていて、倒れられたと。そこで、この養成研修がしっかり都と全く違うような、特色のある研修をやられているのかなと思いまして、お伺いしたわけなんです。","respondent":"高橋障害者福祉課長","answer":"視覚障害者のガイドヘルパーですが、生来からの視覚障害者につきましては、学校のときからかなり訓練をされていますので、一、二回ご利用になった後、ご自分で自立して、通院なり通学なり、社会参加ということでやっておられることは十分承知しておりますので。","voiceIndex":272,"id":"exchange-119"},{"speaker":"山路委員","kind":"質問・要望","question":"まちでよくすれ違うときに、陰の、目立たない存在ではありますが、ガイドヘルパーの活躍も、我々は応援しておりますので、どうぞよろしくお願いしたいと思いますが、私ども会派で行っておりますヒアリングで、視覚障害者福祉協会の方たちから、いろいろと要望をいただいているものがあるんですけど、これについては時間のお話は先ほどありましたが。","respondent":"高橋障害者福祉課長","answer":"したがいまして、新しい物が出た段階で、それが使いやすいのかどうなのかを検討し、今後もその中で検討していきたいと考えていますので、よろしくお願いします。","voiceIndex":274,"id":"exchange-120"},{"speaker":"山路委員","kind":"質問・要望","question":"続きまして、病児保育につきまして、平成１８年の第２回定例会で、病児保育の現状をお聞きして、そしてその病児保育の先生のところに子どもが病気して、助かった、心配だったんだけど、うまく預けられたというお母さん方からの例を出しまして、品川、大井地区にも何とかもう１カ所お願いしたいということを質問したことがありますが、その後の動向について、何か状況変化があったら。","respondent":"小林保育課長","answer":"したがいまして、今後、他の地域に適地、また人材等があれば、拠点を増やして、各地域の利用の便利さに大きな差異が生じないように工夫していくことも必要かと思いますし、また効率的に展開するためには、既存の病後児園との連携等も含めて、今後検討してまいりたいと思います。","voiceIndex":276,"id":"exchange-121"},{"speaker":"山路委員","kind":"質問・要望","question":"品川、大井地区のお母さん方も、先生のところでお世話になっている方から、百反坂を自転車で登るとき、時間がちょっとかかるとか、つらいとか、実情を考えますと、それくらいはと思うんですが、要望が非常に地元で強いですので、何とか関係機関にお話をかけていただいて、努力していただきたいと思いますが、最後に一言何かコメントをお願いします。","respondent":"小林保育課長","answer":"地元のご要望、需要、ご発言の趣旨を踏まえて検討してまいります。","voiceIndex":278,"id":"exchange-122"},{"speaker":"須藤委員","kind":"意見","question":"成果報告書の１１４ページ、高齢福祉費、１１６ページ、障害者福祉費、１１８ページ、社会福祉施設費、１８９ページ、介護保険特別会計について、関連してお尋ねいたします。最初に障害者福祉費のほうですけれども、作業所でいろいろ障害者の方がつくられていますけれども、そういったものの販売支援なんかはどんな形で、区でやっていますか。","respondent":"高橋障害者福祉課長","answer":"今、品川区作業所等ネットワーク支援事業ということで、今年の４月からそれぞれの作業所の方を集め、今後、品川名産を中心に販路拡大ということで、検討を始めたところです。","voiceIndex":281,"id":"exchange-123"},{"speaker":"須藤委員","kind":"質問","question":"そこは知っているんだけれども、いろいろなものをつくったりして、行政としてどんな支援をしていますかということをお聞きしたいんです。そのあたりの販売もかなり庁舎で使っているものよりもロールが長いし、取り替える手間が簡単だということで、どこかで行政が応援して使える場所があったら紹介してもらったりしたらと思っているんですが、そのあたりいかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"クッキーについては、福祉ショップテルベが販売を行っているもので、再生紙のロールで、今までのロールよりは百七十何メートルということで、１つのロールでかなり巻きがかたいということで、今その販売ルートについて、第二しいのき学園が行っていますので。","voiceIndex":283,"id":"exchange-124"},{"speaker":"須藤委員","kind":"質問","question":"それは、今、一般財源とか、都の補助とかいろいろな補助をいただきながらやっているんだけれども、そのあたりの区分けというか、分け方、拠点をつくるのは社会福祉のほうでやっているけれども、介護予防をするのは介護保険でやりますよとかという区分けをしたり何かしているけれども、そのあたりの考え方はどうなのかということ、それから介護給付等準備基金で。","respondent":"冨岡高齢福祉課長","answer":"これについては高齢福祉ということで、ベースで対応するものだと思います。","voiceIndex":285,"id":"exchange-125"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから時間がなくなるといけないので、先ほど松澤委員から質問があった、ひとり暮らしの方等の、それは２人であってもあれだけれども、孤独死という問題で、先ほど答弁で、モデル地区をつくって、今、検討に入っていますというようなお話をいただいたんだけれども、どういう仕組みづくりをされてきているのか。ちょっとお聞かせいただきたい。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"ただ、今回の制度改正の中で、特に要支援者については介護予防という冠はついておりますけれども、その基本的な考え方のものは自立支援ということです。この２つのモデルをまずつくりまして、少しでも孤独死を防止するための準備を、緊急の問題ですけれども、品川区の標準みたいなものをつくってまいりたいと思っているところです。","voiceIndex":287,"id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"私はこの仕組みというのが区民にとっても、非常に安心感のある仕組みで、民だけで行くと、いろいろなその先で、倒産されたり、どうのというような事件が今、報道されています。都心区は都心区でまた考えなければいけないというような意見書を国に出すように今、議会のほうでやっていますけれども、そういったいろいろな地方の差が出てくると思うんだけれども、保険者として、そのあたりいかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"現在、問題になっている、いろいろあります、例えば連座制の問題とか、それから介護報酬のお話がございましたけれども、その辺の人材確保の問題とか、こういう部分については品川区もいろいろな場面で発信していく必要があると考えていますし、議会のほうにおかれましても。","voiceIndex":290,"id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"最後にさっき言った介護給付費等の「等」は何だというのはまだ聞いていないんだけど、やはりこれは準備基金ですから、そのあたりを含めて、どういう形で使っていくのか、お知らせください。","respondent":"冨岡高齢福祉課長","answer":"この基金につきましては、第四期の事業計画に向けまして、やはり当然取り崩しということはありうるですので、給付も見据えながら計画の中でまた一定程度取り崩しをしてまいりたいと考えています。","voiceIndex":292,"id":"exchange-128"},{"speaker":"川西委員","kind":"質問","question":"１１３ページ、ほっとサロンに関連して、次は１１３ページ、同じく施設系サービス事業者の経営・質の向上支援、空き店舗活用型保育サービス拠点支援事業、１１４ページの特別養護老人ホーム建設費助成をお願いいたします。私が伺いたいのは、今２カ所で運営されておりまして、かなり地域に愛されているということですが、今後の条件があえば、品川区内にどういうふうに拡大していくのか、伺いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"今後につきましては、区立といいますか、区の施設をほっとサロンに貸し出しをするということは今後検討の課題になるかと思いますが、あとそれぞれ自主的に地域のほうで、ほっとサロンを運営されているところに。","voiceIndex":295,"id":"exchange-129"},{"speaker":"川西委員","kind":"質問・要望","question":"品川総合福祉センターに聞きましたら、２００円出せば、だれでも行けるんですよということを伺いました。というのは、福祉カレッジのほうは、そこに携わるヘルパーとか、ケアマネージャーたちの質の向上といいますか、研修のために継続されているもので、それから続いてこれができたわけですが、その事業内容について、この平成１９年度、どういうふうな目的に沿って成果が上がったのか伺います。","respondent":"冨岡高齢福祉課長","answer":"したがいまして、これは平成１９年の４月から開始した制度です。東京都の福祉サービスに関する第三者評価の一斉受診を図っていくもので、それに対する委託料について負担をしているものです。","voiceIndex":297,"id":"exchange-130"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、第三者評価を事業者に受けていただくための費用ですか。諸外国に比べれば、日本はおくれていると思うんです。そういう、私がちょっと申し上げたようなことは区でやれないんでしょうか。事業者に対して、そこに派遣されてくる人たちの資質の向上の研修とかというのは一般質問でも申し上げたので、ちょっと答えてください。","respondent":"冨岡高齢福祉課長","answer":"今のそれぞれの事業所にお勤めになっている職員の方の質の向上につきましては、品川介護福祉専門学校の中で、福祉カレッジというのがございまして、こちらのほうでさまざまなコース、ケアマネジメントのコースなり、介護福祉士のコース、それから認知症のコース等がありまして。","voiceIndex":299,"id":"exchange-131"},{"speaker":"川西委員","kind":"質問","question":"来年度に向けて、ぜひよろしくお願いいたします。この品川宿おばちゃんちも、さっきほっとサロンで申し上げたように、今までの質問の中にもちょっとあったように思いますが、もうちょっと増やしていただく努力もやはりお願いしたいと思います。とても活用されています。これが１つです。そういうふうに品川宿おばちゃんちに預けていてもカウントされるようなことはできないでしょうか、お伺いいたします。","respondent":"小林保育課長","answer":"前段の施設の充足度のお尋ねですが、この品川宿おばちゃんちの経営上の要素は、１つは短時間就労の人の受け皿になっていること。もう１つは一時預かりの柔軟な対応をしていること。この２つ。そして、加えてポイントは、それを地域の支え合いの中でやっている。","voiceIndex":301,"id":"exchange-132"},{"speaker":"川西委員","kind":"質問・要望","question":"保育課長のご答弁、大変よくわかっています。ですから、そういう点で、若干配慮していただきたい。ですから、そういうのも配慮していただきたいということを要望で申し上げます。これはそれなりに特別養護老人ホームに入れない人たちのために大変役立っていると思うんですが、現況の情勢の中で、こういう制度というのは呼びかけがないのか、区がその気がないのか、ちょっと教えていただきたい。","respondent":"冨岡高齢福祉課長","answer":"新たにこれをつくりますという形でのお話は来ておりません。今のこちらに出ております６施設プラスもう１施設ありますけれども、７施設で対応しているという状況です。","voiceIndex":303,"id":"exchange-133"},{"speaker":"飯沼委員","kind":"意見","question":"１２０ページの職員給与費、認証保育所助成事業、１２２ページの認定こども園開設準備経費についてお尋ねします。認証保育所なんですが、待機児が増えている中、認証保育所に頼らざるを得ない現状がありますけれども、しかし内容に不安の声が届いています。激安スーパーでの買い物がほとんど。保護者に見せる毎日の昼食のサンプルは見ばえよくつくられる。","respondent":"小林保育課長","answer":"現段階で１１施設ありますが、特に保育水準、保育の内容に問題があるというお声はいただいておりません。なお、余談ではありますけれども、先ほどのお話の保育園等につきましては、適宜都の指導も入りまして、ご承知のとおり認証の取り消しも含めて対応がされているところです。","voiceIndex":306,"id":"exchange-134"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１年に１回ということですが、ぜひ都と力を合わせて、事故が起こってからまた調べるというのでは遅いと思います。時間がないので先に行きます。説明をしていただきたいのと、品川区立においては、３つの公立保育園が認定こども園に移行しましたが、その移行した理由、そして今後品川区立の公立の保育園が認定こども園に移行を進めていくのかどうか、その辺を教えてください。","respondent":"小林保育課長","answer":"品川区におきましては、昨年９月、保育園型認定こども園ということで、一本橋保育園、旗の台保育園、五反田保育園が認定こども園になりましたが、この目的は従来やってまいりました幼児教育の体制をもう１度確認し、充実するとともに。","voiceIndex":308,"id":"exchange-135"},{"speaker":"飯沼委員","kind":"意見","question":"今後進めていくのかどうか、その点をお願いします。","respondent":"小林保育課長","answer":"そういった意味では、この３園を認定こども園とすることによって、３園にとどまらず、全園の保育の内容、職員の意識が随分変わってまいりました。今後の施設のありようにつきましては、こうした状況を踏まえて、状況に応じて判断をしてまいりたいと考えています。","voiceIndex":310,"id":"exchange-136"},{"speaker":"飯沼委員","kind":"質問","question":"１点目は認可外幼稚園と、認可外保育園にも公認していく。この２点をすごく危惧をしています。ここからが質問なんですが、今年の１２月から品川区初の株式会社立の認定こども園がオープンするわけですが、認可保育園ベースになっていると聞いていますけれども、ここの入園申し込みの手続きと、あと保育料がどうなるのか。もう１点、区との協議はどうなっているのか。この点を教えてください。","respondent":"小林保育課長","answer":"前段、認定こども園についての認識を２点ご説明いただきましたが、１点目は認定こども園になることによって、認可外保育園の基準が下げられた事実がありましょうか。","voiceIndex":312,"id":"exchange-137"},{"speaker":"飯沼委員","kind":"質問","question":"水準、最低基準が保てないという中身は、認定こども園を詳しくやりたかったんですが、時間がないから、４パターンの中で、幼保連携型は認可の幼稚園と認可の保育園のセット組み合わせですよね。このことを心配しています。企業任せでは、本当に保育制度をせっかくここまで築いてきて、これからもっとよくしていきたいという中身が壊れてしまうと思うんですが、この点はいかがでしょうか。","respondent":"小林保育課長","answer":"認定こども園を含む保育事業への対応ということかと思いますが、私はだれが保育事業をやるかではなくて、どういう内容でやるかということだと思います。民間の事業者がやったから、すべてが悪い。公立がやればすべてがよいという保障がどこにあるんでしょうか。","voiceIndex":314,"id":"exchange-138"},{"speaker":"飯沼委員","kind":"意見","question":"保育課長はだれがやるかじゃなくて、どういう内容かと、そのどういう内容かが、企業立で認定こども園をやる場合と、今の品川区が責任を持ってやっている、あの３つの認定こども園、私はすごくわかりにくくするために３園、認定こども園に運んだのではないかなと、導くためにやったのではないかと勘ぐるぐらい、同じ認定こども園と言いながら、４パターンあるんですよ。その中身がわからない。","respondent":"小林保育課長","answer":"企業だから悪いということではなく、一番確かなのは、大切な子どもを預けている保護者の目です。それはその水準も含めて、私どもと同様に、しっかりとそれぞれの保育園のありよう、水準を見守っていってくれるものと考えております。","voiceIndex":316,"id":"exchange-139"},{"speaker":"飯沼委員","kind":"質問","question":"このことをお願いしたいと思います。サービス残業についてお伺いしたいと思います。今年、３月の予算特別委員会で、サービス残業のことを伺ったところ、人事課長はサービス残業はありませんと答弁をされたわけなんですが、そのご答弁をいただいた１０日後ぐらいに、庁舎のところで配られたビラにはサービス残業８２.４％、黙認しないでくださいということで、正規職員は減らされています。","respondent":"小林保育課長","answer":"現状に応じて必要なものは命じますし、必要でないものはできるだけ元気な顔を翌日子どもたちに見せるためにも、早く帰って云々という指導を徹底しています。そういった意味で、サービス残業というのは存在しておりません。","voiceIndex":318,"id":"exchange-140"},{"speaker":"飯沼委員","kind":"質問・要望","question":"言い切っていらっしゃる。私はぜひ職員の声も聞いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-141"},{"speaker":"三上委員","kind":"質問","question":"最初にしながわお休み石設置事業について、これは大分品川区内にも数多く設置されてきているのではないかなと思いますが、トータル的な数と、今年はバス停お休み石ということで、８基ということを言っていますが、昨年と今年の状況というのはどういうふうになっているんでしょうか。ですから、１カ月前の１日に申し込まなければだめだと。そこまでご答弁をいただけますか。","respondent":"永尾高齢事業課長、諸岡児童課長","answer":"しながわお休み石設置事業のバス停お休み石の推移ですけれども、平成１９年度は８基ということで、過去５年ぐらい見ますと、平成１５年度は５基、平成１６年度は３基、平成１７年度６基、平成１８年度６基というような形で。子育て支援センターのトワイライトステイ事業に関するお尋ねです。昨年度、利用件数も大分増えてまいりましたので、制度の変更を一部いたしました。","voiceIndex":322,"id":"exchange-142"},{"speaker":"三上委員","kind":"質問","question":"そのバス停お休み石という、今年の寄付は６人の方からあったと。これを設置するのに１基お幾らかかるんでしょうか。","respondent":"永尾高齢事業課長","answer":"原材料費自体は１９万６,０００円と１５万７,０００円ですけれども、それに運搬費とか工事費とかが加わりまして、ちょっと場所によって工事の状況が変わるんですけれども、約３５万円程度です。","voiceIndex":325,"id":"exchange-143"},{"speaker":"三上委員","kind":"質問","question":"それはやはりこういう時代ですから、お休み石というのを書いたとしても、贈呈者というのは、やっぱりそういう表側にも見えるような形に書いたほうがいいんじゃないか。そういうことについて私はこう思いますけれども、それについてのお考えはどうでしょうか。それから、トワイライトステイ事業についてですけれども、そうすると、これは１日に預かれる人数というのは何人になっていますか。","respondent":"諸岡児童課長、永尾高齢事業課長","answer":"トワイライトステイ事業の１日にお預かりする定員は２０人となっています。お休み石の表示の件ですけれども、企業だけでなく個人の方もあります。温かい気持ちで寄付をいただいたということですので、どちらにするかということは今後検討をしてまいります。","voiceIndex":327,"id":"exchange-144"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そういった意味においては、区として予算がそれだけ年間５０基あたり設置できるだけの予算をつくっていただけるのだったら、それは別かもわかりませんけれども、そういう検討をちょっとお願いしたいと思います。それから１日２０人ということで、そうすると、まだ余裕はあると思っていいんでしょうか。","respondent":"諸岡児童課長","answer":"時期的にはかなり満員となる時期もありますが、年間通してはさほどいつもいっぱいという状況ではございません。","voiceIndex":330,"id":"exchange-145"},{"speaker":"三上委員","kind":"質問","question":"これは１カ所で品川区はやっていますよね。やはり近い方については使いやすい、ありがたいと思うでしょうし、平塚に遠いという方については使いたいけれども使えないということもあります。ですから、いろいろ検討していただいて、場所の確保をお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":332,"id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから２点目に、先ほど高齢事業課長からお答えがいろいろあった中で、後期高齢者の関係だったので、後期高齢者健診のほうをちょっと確認しますけれども、先ほど３万３００人というお話があったんですけど、ちょっと聞いた話というか、資料を見た中で、誕生日の関係で、何人か受けられない方が出てくるということをお聞きしました。何か対応方法があるのかどうか、その３点をお答えお願いします。","respondent":"本城国保年金課長、永尾高齢事業課長、高橋障害者福祉課長","answer":"それに関しては、窓口の対応の中で一つ一つ丁寧にご説明させていただきまして、社会保険事務所のほうにつなげるという体制をとっているところです。早生まれの方、翌年の１月から３月にお生まれの方は、年度内の受診を促すということで、１２月末に受診券のほうを送付しております。大塚ろう学校の品川分教室跡地を品川地区知的障害特別支援学校ということで、事業概要を東京都から説明を受けた時点で、何らかの地域開放なり。","voiceIndex":334,"id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"国民年金は窓口で、本来の事務からするとちょっと違うかもしれないけど、うまくお客様が来たときに対応していただきたいということをお願いします。それから受診券を送っていただくということで、７４歳の方も全員受けられるということで、それは一つ安心しました。区からも都に対して要望をしていく。そういう形のものをとっていただけないのかどうか、もう１回ちょっとお答えをお願いしたいと思います。","respondent":"高橋障害者福祉課長","answer":"放課後対策は具体的にはやはり学校の中で行う場合については、そこの特別支援学校の中で対応をしていただくのが得策かと思います。","voiceIndex":338,"id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その状況を踏まえて、できる限りのことをやっていただきたいなということを要望しておきます。新しい方も当然採用していらっしゃって、十分その対応はしていらっしゃるんですが、これから人的な配置がどうなっていくのか。それから今までやっていた方の経験をやっぱり生かしていってもらいたい。その引き継ぎのノウハウみたいなものを何か考えていらっしゃるのか。","respondent":"小林保育課長","answer":"そういった意味で、今後５年ないし、本年を入れると６年間、平成２５年ぐらいまでの間に退職、定年退職だけでも、１１４人ほど、約２０％ほどの職員が変わっていきますので、組織の当然の新陳代謝として必要な人員を新規採用等で確保、要望しながら。","voiceIndex":340,"id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"意見","question":"民間の力、先ほど保育水準を守ること、引き上げることという話もありました。民間ができないということはないと思いますので、そういう点で、これから水準を守り、引き上げるという大前提を持ちながらも、公設民営ということも考えが出ると思うんですけれども、ここら辺、区として現在では、今やるやらないは別にして、考え方を持っていらっしゃるのかどうか。","respondent":"小林保育課長","answer":"そういった意味で、コストも大切な要素ですけれども、物の値段というのは、僭越ですけれども、表面上の価格ではなくて、幾ら出して何を買うかだろうと考えています。そういった意味で、区民の信頼を勝ち得るような保育の内容をできるだけ節約したコストの中でやってまいりたい。","voiceIndex":342,"id":"exchange-150"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１点、都南病院の跡地の件で、もうここまででき上がっています。なるべく入る人にとっては負担のないようにするためには、何か方法を考えていかなければいけない中で、先ほど一般財源を使うのか、市町村特別給付を使うのかという話も、ここじゃないですけど、別の面で話がありましたけれども、こういったものを使うことはできないんでしょうか。その辺のお考えをお願いしたいと思います。","respondent":"冨岡高齢福祉課長","answer":"法律上問題はないかなと考えています。それにつきましては、さまざまな角度からまた検討して決めてまいりたいと考えています。これにつきましては、スケジュールといたしまして、１月に募集がありますので、その前の委員会でご報告をして、それで進めてまいりたいと考えています。","voiceIndex":344,"id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"確認","question":"委員会というのもありますけれども、私もちょっと資料を見た中で、独自の市町村特別給付に関しては、条例により実施することができるというところまで入っていますね。その通常の委員会報告ですと、条例ではないということを考えると、ある程度第４回定例会とか第１回定例会という形になるのか、その辺、条例化までということで、考えてよろしいんですね。確認です。","respondent":"冨岡高齢福祉課長、堺委員長","answer":"何を特別給付にするかというのは、これからですけれども、実施する場合は当然条例でお願いをして、決めていただくということになります。以上をもちまして、本日予定の審査はすべて終了いたしました。次の会議は明日午前１０時から開きます。本日はこれをもって閉会といたします。","voiceIndex":346,"id":"exchange-152"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1296#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":112090,"voices":348}}]);
